CREATE OR REPLACE PACKAGE BODY MGPA_INS_SCM2MGTIF
IS
	C_OFF		CONSTANT MAPA_META.FLG%TYPE := '0' ;
	C_ON		CONSTANT MAPA_META.FLG%TYPE := '1' ;

	C_OK		CONSTANT INTEGER := 0 ;
	C_ERR		CONSTANT INTEGER := 1 ;

	C_NULL_VAL	CONSTANT MAPA_META.STR20%TYPE := MAC_STR.NULL_VAL ;

	C_STR_CHK	CONSTANT MAPA_META.STR20%TYPE := MGC_STR.CHK_STR_DLM ;

	G_LOG_NO	MAPA_META.BATCH_LOG_NO%TYPE ;
	G_LOG_SUB_KEY1	MAPA_META.BATCH_LOG_SUB_KEY1%TYPE ;
	G_LOG_SUB_KEY2	MAPA_META.BATCH_LOG_SUB_KEY2%TYPE ;

	TYPE LIST_CHK_ITM IS TABLE OF MGPA_META.CONCAT_ITM_MFG_INST%TYPE INDEX BY MGPA_META.CONCAT_ITM_MFG_INST%TYPE ;
	REC_CHK_ITM	LIST_CHK_ITM ;

	TYPE LIST_CHK_OPER IS TABLE OF MGPA_META.CONCAT_OPER_ACT%TYPE INDEX BY MGPA_META.CONCAT_OPER_ACT%TYPE ;
	REC_CHK_OPER	LIST_CHK_OPER ;

	TYPE LIST_MFG_IF IS TABLE OF MGT_ACT_MFG_IF%ROWTYPE INDEX BY BINARY_INTEGER ;
	REC_w1	LIST_MFG_IF ;
	w1	BINARY_INTEGER ;

	TYPE LIST_PURC_IF IS TABLE OF MGT_ACT_PURC_IF%ROWTYPE INDEX BY BINARY_INTEGER ;
	REC_w2	LIST_PURC_IF ;
	w2	BINARY_INTEGER ;

	TYPE LIST_INPT_IF IS TABLE OF MGT_ACT_INPT_IF%ROWTYPE INDEX BY BINARY_INTEGER ;
	REC_w3	LIST_INPT_IF ;
	w3	BINARY_INTEGER ;

	TYPE LIST_IO_IF IS TABLE OF MGT_ACT_IO_IF%ROWTYPE INDEX BY BINARY_INTEGER ;
	REC_w4	LIST_IO_IF ;
	w4	BINARY_INTEGER ;

	TYPE LIST_SLS_IF IS TABLE OF MGT_ACT_SLS_IF%ROWTYPE INDEX BY BINARY_INTEGER ;
	REC_w5	LIST_SLS_IF ;
	w5	BINARY_INTEGER ;

	TYPE LIST_ITM_MFG IS TABLE OF MGT_ITM_MFG_INST%ROWTYPE INDEX BY BINARY_INTEGER ;
	REC_w6	LIST_ITM_MFG ;
	w6	BINARY_INTEGER ;

	TYPE LIST_INST_OPER IS TABLE OF MGT_INST_OPER%ROWTYPE INDEX BY BINARY_INTEGER ;
	REC_w7	LIST_INST_OPER ;
	w7	BINARY_INTEGER ;

	TYPE LIST_ACT_INST_WK_IF IS TABLE OF MGT_ACT_INST_WK_IF%ROWTYPE INDEX BY BINARY_INTEGER ;
	REC_w8	LIST_ACT_INST_WK_IF ;
	w8	BINARY_INTEGER ;

	TYPE LIST_W_INPT_IF IS TABLE OF MGW_ACT_INPT_IF%ROWTYPE INDEX BY BINARY_INTEGER ;
	TMP_w3	LIST_W_INPT_IF ;
	t3	BINARY_INTEGER ;

	TMP_w6	LIST_ITM_MFG ;
	t6	BINARY_INTEGER ;
	REC_CHK_IV	LIST_CHK_ITM ;
	REC_CHK_IV2	LIST_CHK_OPER ;
	UPD_w6	LIST_ITM_MFG ;
	u6	BINARY_INTEGER ;

	BULK_ERROR	EXCEPTION ;
	PRAGMA	EXCEPTION_INIT(BULK_ERROR, -24381) ;

	G_MFG_CNT	NUMBER ;
	G_PURC_CNT	NUMBER ;
	G_INPT_CNT	NUMBER ;
	G_IO_CNT	NUMBER ;
	G_SLS_CNT	NUMBER ;
	G_INST_WK_CNT	NUMBER ;
	G_MFG_INST_CNT	NUMBER ;
	G_INST_OPER_CNT NUMBER ;

	TYPE LIST_ROWID IS TABLE OF ROWID INDEX BY BINARY_INTEGER ;
	REC_ID	LIST_ROWID ;
	d1	BINARY_INTEGER ;

	G_PARM_ITM_CNT		BINARY_INTEGER ;
	G_PARM_PURC_IF_CNT	BINARY_INTEGER ;
	G_PARM_SLS_IF_CNT	BINARY_INTEGER ;

	C_TAB_ITM	CONSTANT MAPA_META.COST_TABLE_TYP%TYPE := MAC_COST_TABLE_TYP.ITM_MFG_INST ;
	C_TAB_PURC_IF	CONSTANT MAPA_META.COST_TABLE_TYP%TYPE := MAC_COST_TABLE_TYP.ACT_PURC_IF ;
	C_TAB_SLS_IF	CONSTANT MAPA_META.COST_TABLE_TYP%TYPE := MAC_COST_TABLE_TYP.ACT_SLS_IF ;
	C_TGT_PO_NO	CONSTANT MAPA_META.TGT_COL_TYP%TYPE := MAC_TGT_COL_TYP.PO_NO ;
	C_TGT_SLO_NO	CONSTANT MAPA_META.TGT_COL_TYP%TYPE := MAC_TGT_COL_TYP.SLO_NO ;
	C_TGT_IV_NO	CONSTANT MAPA_META.TGT_COL_TYP%TYPE := MAC_TGT_COL_TYP.IV_NO ;
	C_PROC_SET_UP	CONSTANT MAPA_META.COL_PROC_TYP%TYPE := MAC_COL_PROC_TYP.SET_UP ;
	C_PROC_NOT_SET	CONSTANT MAPA_META.COL_PROC_TYP%TYPE := MAC_COL_PROC_TYP.NOT_SET ;

	TYPE LIST_IF_PARM IS TABLE OF MAM_IF_PARM%ROWTYPE INDEX BY BINARY_INTEGER ;
	REC_PARM_ITM		LIST_IF_PARM ;
	REC_PARM_PURC_IF	LIST_IF_PARM ;
	REC_PARM_SLS_IF		LIST_IF_PARM ;

	G_YM			MAPA_META.YM%TYPE ;
	G_LOT_NON_MOV_FLG	MAPA_META.FLG%TYPE ;
	G_SUBLOT_NON_MOV_FLG	MAPA_META.FLG%TYPE ;
	G_SNO1_NON_MOV_FLG	MAPA_META.FLG%TYPE ;
	G_SNO2_NON_MOV_FLG	MAPA_META.FLG%TYPE ;
	G_SNO3_NON_MOV_FLG	MAPA_META.FLG%TYPE ;
	G_SNO4_NON_MOV_FLG	MAPA_META.FLG%TYPE ;
	G_WG_NON_MOV_FLG	MAPA_META.FLG%TYPE ;

FUNCTION F_GET_MSC_IO_ACT_TYP_IO_TYP (
	I_IO_ACT_TYP IN VARCHAR2
)
RETURN VARCHAR2
/************************************************************************
<SYNOPSIS>
	ＭＳモジュールの受払区分の属性値IO_TYPを取得する
<REMARKS>
	ＭＳモジュールが存在しているときのみ取得される
<ARGUMENTS>
<IN>	I_IO_ACT_TYP
		受払区分
<RETURN VALUE>
		MSC_IO_ACT_TYP.IO_TYPの結果
<HISTORY>
*************************************************************************/
AS
	L_SQL	CONSTANT VARCHAR2(10000) := 
				'
				BEGIN :IO_TYP := MSC_IO_ACT_TYP.IO_TYP(:IO_ACT_TYP) ; END;
				' ;
	L_IO_TYP	MAPA_META.STR20%TYPE ;
/************************************************************************/
BEGIN
	L_IO_TYP := NULL ;
	EXECUTE IMMEDIATE L_SQL USING OUT L_IO_TYP, I_IO_ACT_TYP ;

	RETURN L_IO_TYP ;

END F_GET_MSC_IO_ACT_TYP_IO_TYP ;


PROCEDURE P_COL_PROC_ITM
/************************************************************************
<SYNOPSIS>
	品目製造指図情報を変更する
<REMARKS>
	原価ＩＦパラメータマスタの設定により品目製造指図情報の指定項目を変更する
<ARGUMENTS>
<HISTORY>
*************************************************************************/
AS
/************************************************************************/
BEGIN
	IF G_PARM_ITM_CNT = 0 THEN
		RETURN ;
	END IF ;

	FOR i IN 1..G_PARM_ITM_CNT LOOP
		CASE REC_PARM_ITM(i).TGT_COL_TYP
		WHEN C_TGT_PO_NO THEN
			REC_w6(w6).PO_NO := NULL ;
		WHEN C_TGT_SLO_NO THEN
			REC_w6(w6).SLO_NO := NULL ;
		WHEN C_TGT_IV_NO THEN
			REC_w6(w6).IV_NO := NULL ;
		END CASE ;
	END LOOP ;
END P_COL_PROC_ITM ;

PROCEDURE P_COL_PROC_PURC
/************************************************************************
<SYNOPSIS>
	購買実績ＩＦを変更する
<REMARKS>
	原価ＩＦパラメータマスタの設定により購買実績ＩＦの指定項目を変更する
<ARGUMENTS>
<HISTORY>
*************************************************************************/
AS
/************************************************************************/
BEGIN
