		RETURN ;
	END IF ;

	FOR i IN 1..G_PARM_PURC_IF_CNT LOOP
		CASE REC_PARM_PURC_IF(i).TGT_COL_TYP
		WHEN C_TGT_PO_NO THEN
			REC_w2(w2).PO_NO := NULL ;
		WHEN C_TGT_SLO_NO THEN
			REC_w2(w2).SLO_NO := NULL ;
		WHEN C_TGT_IV_NO THEN
			REC_w2(w2).IV_NO := NULL ;
		END CASE ;
	END LOOP ;
END P_COL_PROC_PURC ;

PROCEDURE P_COL_PROC_SLS
/************************************************************************
<SYNOPSIS>
	売上実績ＩＦを変更する
