	FOR i IN 1..G_PARM_SLS_IF_CNT LOOP
		CASE REC_PARM_SLS_IF(i).TGT_COL_TYP
		WHEN C_TGT_SLO_NO THEN
			REC_w5(w5).SLO_NO := NULL ;
		WHEN C_TGT_IV_NO THEN
			REC_w5(w5).IV_NO := NULL ;
		END CASE ;
	END LOOP ;
END P_COL_PROC_SLS ;

FUNCTION F_CHK_ITM (
	I_ITM_CD		IN	MAPA_META.ITM_CD%TYPE,
	I_ITM_SUB1		IN	MAPA_META.ITM_SUB1%TYPE,
	I_ITM_SUB2		IN	MAPA_META.ITM_SUB2%TYPE,
	I_ITM_SUB3		IN	MAPA_META.ITM_SUB3%TYPE,
	I_ITM_MFG_INST_NO	IN	MAPA_META.ITM_MFG_INST_NO%TYPE,
	I_MFG_ACT_NO	IN	MAPA_META.MFG_ACT_NO%TYPE
	)
RETURN INTEGER
/************************************************************************
<SYNOPSIS>
	品目ＣＤ、枝番１～３、品目製造指図ＮＯ、製造実績ＮＯごとに重複チェックを行う
<REMARKS>
	重複なしならOK、重複ありならERRとする
<ARGUMENTS>
<IN>	I_ITM_CD
		品目ＣＤ
<IN>	I_ITM_SUB1
		枝番１
<IN>	I_ITM_SUB2
		枝番２
<IN>	I_ITM_SUB3
		枝番３
<IN>	I_ITM_MFG_INST_NO
		品目製造指図ＮＯ
<IN>	I_MFG_ACT_NO
		製造実績ＮＯ
<HISTORY>
*************************************************************************/
AS
	L_CHK_STR	MGPA_META.CONCAT_ITM_MFG_INST%TYPE ;
/************************************************************************/
BEGIN
	IF I_ITM_MFG_INST_NO IS NULL AND NVL(I_MFG_ACT_NO, C_NULL_VAL) = C_NULL_VAL THEN
		RETURN C_ERR ;
	END IF ;

	L_CHK_STR := I_ITM_CD
		|| C_STR_CHK || I_ITM_SUB1
		|| C_STR_CHK || I_ITM_SUB2
		|| C_STR_CHK || I_ITM_SUB3
		|| C_STR_CHK || I_ITM_MFG_INST_NO
		|| C_STR_CHK || I_MFG_ACT_NO ;

	IF REC_CHK_ITM.EXISTS(L_CHK_STR) THEN
		RETURN C_ERR ;
	ELSE
		REC_CHK_ITM(L_CHK_STR) := L_CHK_STR ;
		RETURN C_OK ;
	END IF ;
END F_CHK_ITM ;

FUNCTION F_CHK_OPER (
	I_ITM_CD		IN	MAPA_META.ITM_CD%TYPE,
	I_ITM_SUB1		IN	MAPA_META.ITM_SUB1%TYPE,
	I_ITM_SUB2		IN	MAPA_META.ITM_SUB2%TYPE,
	I_ITM_SUB3		IN	MAPA_META.ITM_SUB3%TYPE,
	I_ITM_MFG_INST_NO	IN	MAPA_META.ITM_MFG_INST_NO%TYPE,
	I_MFG_ACT_NO	IN	MAPA_META.MFG_ACT_NO%TYPE,
	I_OPER_ACT_NO	IN	MAPA_META.OPER_ACT_NO%TYPE
	)
RETURN INTEGER
/************************************************************************
<SYNOPSIS>
	品目ＣＤ、枝番１～３、品目製造指図ＮＯ、製造実績ＮＯ、工程実績ＮＯごとに重複チェックを行う
<REMARKS>
	重複なしならOK、重複ありならERRとする
<ARGUMENTS>
<IN>	I_ITM_CD
		品目ＣＤ
<IN>	I_ITM_SUB1
		枝番１
<IN>	I_ITM_SUB2
		枝番２
<IN>	I_ITM_SUB3
		枝番３
<IN>	I_ITM_MFG_INST_NO
		品目製造指図ＮＯ
<IN>	I_MFG_ACT_NO
		製造実績ＮＯ
<IN>	I_OPER_ACT_NO
		工程実績ＮＯ
<HISTORY>
*************************************************************************/
AS
	L_CHK_STR	MGPA_META.CONCAT_OPER_ACT%TYPE ;
/************************************************************************/
BEGIN
	IF (I_ITM_MFG_INST_NO IS NULL AND NVL(I_MFG_ACT_NO, C_NULL_VAL) = C_NULL_VAL) OR NVL(I_OPER_ACT_NO, C_NULL_VAL) = C_NULL_VAL THEN
		RETURN C_ERR ;
	END IF ;

	L_CHK_STR := I_ITM_CD
		|| C_STR_CHK || I_ITM_SUB1
		|| C_STR_CHK || I_ITM_SUB2
		|| C_STR_CHK || I_ITM_SUB3
		|| C_STR_CHK || I_ITM_MFG_INST_NO
		|| C_STR_CHK || I_MFG_ACT_NO
		|| C_STR_CHK || I_OPER_ACT_NO ;

	IF REC_CHK_OPER.EXISTS(L_CHK_STR) THEN
		RETURN C_ERR ;
	ELSE
		REC_CHK_OPER(L_CHK_STR) := L_CHK_STR ;
		RETURN C_OK ;
	END IF ;
END F_CHK_OPER ;

FUNCTION F_CHK_IV (
	I_ITM_CD		IN	MAPA_META.ITM_CD%TYPE,
	I_ITM_SUB1		IN	MAPA_META.ITM_SUB1%TYPE,
	I_ITM_SUB2		IN	MAPA_META.ITM_SUB2%TYPE,
	I_ITM_SUB3		IN	MAPA_META.ITM_SUB3%TYPE,
	I_ITM_MFG_INST_NO	IN	MAPA_META.ITM_MFG_INST_NO%TYPE,
	I_MFG_ACT_NO	IN	MAPA_META.MFG_ACT_NO%TYPE,
	I_IV_NO		IN	MAPA_META.IV_NO%TYPE
	)
RETURN INTEGER
/************************************************************************
<SYNOPSIS>
	品目ＣＤ、枝番１～３、品目製造指図ＮＯ、製造実績ＮＯごとにインボイスＮＯの重複チェックを行う
<REMARKS>
	インボイスＮＯ違いで重複している場合は-1を返す
	重複なしならOK、重複ありならERRとする
<ARGUMENTS>
<IN>	I_ITM_CD
		品目ＣＤ
<IN>	I_ITM_SUB1
		枝番１
<IN>	I_ITM_SUB2
		枝番２
<IN>	I_ITM_SUB3
		枝番３
<IN>	I_ITM_MFG_INST_NO
		品目製造指図ＮＯ
<IN>	I_MFG_ACT_NO
		製造実績ＮＯ
<IN>	I_IV_NO
		インボイスＮＯ
<HISTORY>
*************************************************************************/
AS
	L_CHK_STR	MGPA_META.CONCAT_ITM_MFG_INST%TYPE ;
	L_CHK_STR2	MGPA_META.CONCAT_OPER_ACT%TYPE ;
/************************************************************************/
BEGIN
	IF (I_ITM_MFG_INST_NO IS NULL AND NVL(I_MFG_ACT_NO, C_NULL_VAL) = C_NULL_VAL) THEN
		RETURN C_ERR ;
	END IF ;

	L_CHK_STR := I_ITM_CD
		|| C_STR_CHK || I_ITM_SUB1
		|| C_STR_CHK || I_ITM_SUB2
		|| C_STR_CHK || I_ITM_SUB3
		|| C_STR_CHK || I_ITM_MFG_INST_NO
		|| C_STR_CHK || I_MFG_ACT_NO ;

	L_CHK_STR2 := L_CHK_STR || C_STR_CHK || I_IV_NO ;

	IF REC_CHK_IV.EXISTS(L_CHK_STR) THEN
		IF REC_CHK_IV2.EXISTS(L_CHK_STR2) THEN
			RETURN C_ERR ;
		ELSE
			REC_CHK_IV2(L_CHK_STR2) := L_CHK_STR2 ;
			RETURN -1 ;
		END IF ;
	ELSE
		REC_CHK_IV(L_CHK_STR) := L_CHK_STR ;
		REC_CHK_IV2(L_CHK_STR2) := L_CHK_STR2 ;
		RETURN C_OK ;
	END IF ;
END F_CHK_IV ;

PROCEDURE P_INS_TRAN
/************************************************************************
<SYNOPSIS>
	受払情報から原価ＩＦテーブルを作成する
<REMARKS>
	品目製造指図情報、指図工程情報は作成対象のデータと同一キーの
	データを対象テーブルから削除して後にデータを作成する
<ARGUMENTS>
<HISTORY>
*************************************************************************/
AS
/************************************************************************/
BEGIN
	IF w1 > 0 THEN
		G_MFG_CNT := G_MFG_CNT + w1 ;
		FORALL t IN 1..w1
			INSERT INTO MGT_ACT_MFG_IF VALUES REC_w1(t) ;
	END IF ;

	REC_w1.DELETE ;
	w1 := 0 ;

	IF w2 > 0 THEN
		G_PURC_CNT := G_PURC_CNT + w2 ;
		FORALL t IN 1..w2
			INSERT INTO MGT_ACT_PURC_IF VALUES REC_w2(t) ;
	END IF ;

	REC_w2.DELETE ;
	w2 := 0 ;

	IF w3 > 0 THEN
		G_INPT_CNT := G_INPT_CNT + w3 ;
		FORALL t IN 1..w3
			INSERT INTO MGT_ACT_INPT_IF VALUES REC_w3(t) ;
	END IF ;

	REC_w3.DELETE ;
	w3 := 0 ;

	IF w4 > 0 THEN
		G_IO_CNT := G_IO_CNT + w4 ;
		FORALL t IN 1..w4
			INSERT INTO MGT_ACT_IO_IF VALUES REC_w4(t) ;
	END IF ;

	REC_w4.DELETE ;
	w4 := 0 ;

	IF w5 > 0 THEN
		G_SLS_CNT := G_SLS_CNT + w5 ;
		FORALL t IN 1..w5
			INSERT INTO MGT_ACT_SLS_IF VALUES REC_w5(t) ;
	END IF ;

	REC_w5.DELETE ;
	w5 := 0 ;

	IF w6 > 0 THEN
		G_MFG_INST_CNT := G_MFG_INST_CNT + w6 ;
		FORALL t IN 1..w6
			DELETE	MGT_ITM_MFG_INST t
			WHERE	0=0
			AND	t.CALC_CTG_CD = REC_w6(t).CALC_CTG_CD
			AND	t.ITM_CD = REC_w6(t).ITM_CD
			AND	t.ITM_SUB1 = REC_w6(t).ITM_SUB1
			AND	t.ITM_SUB2 = REC_w6(t).ITM_SUB2
			AND	t.ITM_SUB3 = REC_w6(t).ITM_SUB3
			AND	t.ITM_MFG_INST_NO = REC_w6(t).ITM_MFG_INST_NO
			AND	t.MFG_ACT_NO = REC_w6(t).MFG_ACT_NO
			;
		FORALL t IN 1..w6
			INSERT INTO MGT_ITM_MFG_INST VALUES REC_w6(t) ;
	END IF ;

	REC_w6.DELETE ;
	w6 := 0 ;

	IF w7 > 0 THEN
		G_INST_OPER_CNT := G_INST_OPER_CNT + w7 ;
		FORALL t IN 1..w7
			DELETE	MGT_INST_OPER t
			WHERE	0=0
			AND	t.CALC_CTG_CD = REC_w7(t).CALC_CTG_CD
			AND	t.ITM_CD = REC_w7(t).ITM_CD
			AND	t.ITM_SUB1 = REC_w7(t).ITM_SUB1
			AND	t.ITM_SUB2 = REC_w7(t).ITM_SUB2
			AND	t.ITM_SUB3 = REC_w7(t).ITM_SUB3
			AND	t.ITM_MFG_INST_NO = REC_w7(t).ITM_MFG_INST_NO
			AND	t.MFG_ACT_NO = REC_w7(t).MFG_ACT_NO
			AND	t.OPER_ACT_NO = REC_w7(t).OPER_ACT_NO
			;
		FORALL t IN 1..w7
			INSERT INTO MGT_INST_OPER VALUES REC_w7(t) ;
	END IF ;

	REC_w7.DELETE ;
	w7 := 0 ;

	IF t3 > 0 THEN
		FORALL t IN 1..t3
			INSERT INTO MGW_ACT_INPT_IF VALUES TMP_w3(t) ;
	END IF ;

	TMP_w3.DELETE ;
	t3 := 0 ;

	IF d1 > 0 THEN
		FORALL t IN 1..d1
			UPDATE	MGVT_MST_IO_ACT t1
			SET	t1.C_IMP_FLG = C_ON
			WHERE	0=0
			AND	t1.ROWID = REC_ID(t)
			AND	t1.SEND_FLG = C_ON
			AND	t1.C_IMP_FLG = C_OFF
			;
	END IF ;

	REC_ID.DELETE ;
	d1 := 0 ;

	IF w8 > 0 THEN
		G_INST_WK_CNT := G_INST_WK_CNT + w8 ;
		FORALL t IN 1..w8
			INSERT INTO MGT_ACT_INST_WK_IF VALUES REC_w8(t) ;
	END IF ;

	REC_w8.DELETE ;
	w8 := 0 ;

END P_INS_TRAN ;

PROCEDURE P_SET_NON_MOVE
/************************************************************************
<SYNOPSIS>
	滞留情報の計算
<REMARKS>
	月次受払在庫詳細情報と滞留制御情報から滞留在庫情報を作成する
<ARGUMENTS>
<HISTORY>
*************************************************************************/
AS
	C_GI		CONSTANT MAPA_META.STR20%TYPE := '2' ;	-- 出庫（入出庫区分）
	C_GR		CONSTANT MAPA_META.STR20%TYPE := '1' ;	-- 入庫（入出庫区分）

	C_END_STK	CONSTANT MAPA_META.STR20%TYPE := 'Z0101' ;	-- 月末在庫

	L_CNT		NUMBER ;
	L_GI_FLG	MAPA_META.FLG%TYPE := C_OFF ;
	L_GR_FLG	MAPA_META.FLG%TYPE := C_OFF ;
	L_GI_YM		MAPA_META.YM%TYPE ;
	L_GR_YM		MAPA_META.YM%TYPE ;

	TYPE LIST_NON_MOV_STK IS TABLE OF MGT_NON_MOV_STK%ROWTYPE INDEX BY BINARY_INTEGER ;
	REC_I	LIST_NON_MOV_STK ;
	TYPE LIST_NON_MOV_STK_KEY IS TABLE OF MGW_NON_MOV_STK_KEY%ROWTYPE INDEX BY BINARY_INTEGER ;
	REC_D	LIST_NON_MOV_STK_KEY ;

	i	BINARY_INTEGER ;

/************************************************************************/
BEGIN

	SELECT COUNT(*) INTO L_CNT FROM MGC_NON_MOV_CTL T
	WHERE F_GET_MSC_IO_ACT_TYP_IO_TYP(T.IO_ACT_TYP) = C_GI AND ROWNUM = 1 ;
	IF L_CNT <> 0 THEN
		L_GI_FLG := C_ON ;
	END IF ;

	SELECT COUNT(*) INTO L_CNT FROM MGC_NON_MOV_CTL T
	WHERE F_GET_MSC_IO_ACT_TYP_IO_TYP(T.IO_ACT_TYP) = C_GR AND ROWNUM = 1 ;
	IF L_CNT <> 0 THEN
		L_GR_FLG := C_ON ;
	END IF ;

	IF L_GI_FLG = C_OFF AND L_GR_FLG = C_OFF THEN
		RETURN ;
	END IF ;

	--処理を開始しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0001', 'MGPA_INS_SCM2MGTIF.P_SET_NON_MOVE') ;

	REC_I.DELETE ;
	REC_D.DELETE ;
	i := 0 ;

	FOR x IN (
		SELECT DISTINCT
			T.ITM_CD,
			T.ITM_SUB1,
			T.ITM_SUB2,
			T.ITM_SUB3,
			DECODE(G_LOT_NON_MOV_FLG, C_ON, T.LOT_NO, C_NULL_VAL) LOT_NO,
			DECODE(G_SUBLOT_NON_MOV_FLG, C_ON, T.SUBLOT_NO, C_NULL_VAL) SUBLOT_NO,
			DECODE(G_SNO1_NON_MOV_FLG, C_ON, T.SNO1, C_NULL_VAL) SNO1,
			DECODE(G_SNO2_NON_MOV_FLG, C_ON, T.SNO2, C_NULL_VAL) SNO2,
			DECODE(G_SNO3_NON_MOV_FLG, C_ON, T.SNO3, C_NULL_VAL) SNO3,
			DECODE(G_SNO4_NON_MOV_FLG, C_ON, T.SNO4, C_NULL_VAL) SNO4,
			DECODE(G_WG_NON_MOV_FLG, C_ON, LOC.WG_CD, C_NULL_VAL) WG_CD
		FROM
			MGVT_MST_MLY_STK_DTL T,
			MAM_LOC LOC
		WHERE 0=0
		AND LOC.LOC_CD = T.LOC_CD
		AND LOC.DEL_FLG = C_OFF
		AND T.AC_YM = G_YM
		AND T.IO_ACT_TYP = C_END_STK
	)
	LOOP
		L_GI_YM := NULL ;
		L_GR_YM := NULL ;

		IF L_GI_FLG = C_OFF THEN
			GOTO SKIP_GI ;
		END IF ;

		-- 出庫滞留基準年月取得
		SELECT
			MAX(T.AC_YM) INTO L_GI_YM
		FROM
			MGVT_MST_MLY_STK_DTL T,
			MAM_LOC LOC,
			MGC_NON_MOV_CTL CTL
		WHERE 0=0
		AND LOC.LOC_CD = T.LOC_CD
		AND LOC.DEL_FLG = C_OFF
		AND CTL.IO_ACT_TYP = T.IO_ACT_TYP
		AND T.ITM_CD = x.ITM_CD
		AND T.ITM_SUB1 = x.ITM_SUB1
		AND T.ITM_SUB2 = x.ITM_SUB2
		AND T.ITM_SUB3 = x.ITM_SUB3
		AND (G_LOT_NON_MOV_FLG = C_OFF OR T.LOT_NO = x.LOT_NO)
		AND (G_SUBLOT_NON_MOV_FLG = C_OFF OR T.SUBLOT_NO = x.SUBLOT_NO)
		AND (G_SNO1_NON_MOV_FLG = C_OFF OR T.SNO1 = x.SNO1)
		AND (G_SNO2_NON_MOV_FLG = C_OFF OR T.SNO2 = x.SNO2)
		AND (G_SNO3_NON_MOV_FLG = C_OFF OR T.SNO3 = x.SNO3)
		AND (G_SNO4_NON_MOV_FLG = C_OFF OR T.SNO4 = x.SNO4)
		AND (G_WG_NON_MOV_FLG = C_OFF OR LOC.WG_CD = x.WG_CD)
		AND T.AC_YM <= G_YM
		AND F_GET_MSC_IO_ACT_TYP_IO_TYP(T.IO_ACT_TYP) = C_GI
		;

		<<SKIP_GI>>
		IF L_GR_FLG = C_OFF THEN
			GOTO SKIP_GR ;
		END IF ;

		-- 入庫滞留基準年月取得
		SELECT
			MAX(T.AC_YM) INTO L_GR_YM
		FROM
			MGVT_MST_MLY_STK_DTL T,
			MAM_LOC LOC,
			MGC_NON_MOV_CTL CTL
		WHERE 0=0
		AND LOC.LOC_CD = T.LOC_CD
		AND LOC.DEL_FLG = C_OFF
		AND CTL.IO_ACT_TYP = T.IO_ACT_TYP
		AND T.AC_YM <= G_YM
		AND F_GET_MSC_IO_ACT_TYP_IO_TYP(T.IO_ACT_TYP) = C_GR
		AND T.ITM_CD = x.ITM_CD
		AND T.ITM_SUB1 = x.ITM_SUB1
		AND T.ITM_SUB2 = x.ITM_SUB2
		AND T.ITM_SUB3 = x.ITM_SUB3
		AND (G_LOT_NON_MOV_FLG = C_OFF OR T.LOT_NO = x.LOT_NO)
		AND (G_SUBLOT_NON_MOV_FLG = C_OFF OR T.SUBLOT_NO = x.SUBLOT_NO)
		AND (G_SNO1_NON_MOV_FLG = C_OFF OR T.SNO1 = x.SNO1)
		AND (G_SNO2_NON_MOV_FLG = C_OFF OR T.SNO2 = x.SNO2)
		AND (G_SNO3_NON_MOV_FLG = C_OFF OR T.SNO3 = x.SNO3)
		AND (G_SNO4_NON_MOV_FLG = C_OFF OR T.SNO4 = x.SNO4)
		AND (G_WG_NON_MOV_FLG = C_OFF OR LOC.WG_CD = x.WG_CD)
		AND (
			SELECT
				NVL(SUM(W.BASE_UNIT_QTY), 0)
			FROM
				MGVT_MST_MLY_STK_DTL W,
				MAM_LOC W2
			WHERE 0=0
			AND W2.LOC_CD = W.LOC_CD
			AND W2.DEL_FLG = C_OFF
			AND W.AC_YM = ADD_MONTHS(T.AC_YM, -1)
			AND W.IO_ACT_TYP = C_END_STK
			AND W.ITM_CD = T.ITM_CD
			AND W.ITM_SUB1 = T.ITM_SUB1
			AND W.ITM_SUB2 = T.ITM_SUB2
			AND W.ITM_SUB3 = T.ITM_SUB3
			AND (G_LOT_NON_MOV_FLG = C_OFF OR W.LOT_NO = x.LOT_NO)
			AND (G_SUBLOT_NON_MOV_FLG = C_OFF OR W.SUBLOT_NO = x.SUBLOT_NO)
			AND (G_SNO1_NON_MOV_FLG = C_OFF OR W.SNO1 = x.SNO1)
			AND (G_SNO2_NON_MOV_FLG = C_OFF OR W.SNO2 = x.SNO2)
			AND (G_SNO3_NON_MOV_FLG = C_OFF OR W.SNO3 = x.SNO3)
			AND (G_SNO4_NON_MOV_FLG = C_OFF OR W.SNO4 = x.SNO4)
			AND (G_WG_NON_MOV_FLG = C_OFF OR W2.WG_CD = x.WG_CD)
		) = 0
		;

		<<SKIP_GR>>
		CONTINUE WHEN L_GI_YM IS NULL AND L_GR_YM IS NULL ;

		i := i + 1 ;

		REC_D(i).ITM_CD		:= x.ITM_CD ;
		REC_D(i).ITM_SUB1	:= x.ITM_SUB1 ;
		REC_D(i).ITM_SUB2	:= x.ITM_SUB2 ;
		REC_D(i).ITM_SUB3	:= x.ITM_SUB3 ;
		REC_D(i).LOT_NO		:= x.LOT_NO ;
		REC_D(i).SUBLOT_NO	:= x.SUBLOT_NO ;
		REC_D(i).SNO1		:= x.SNO1 ;
		REC_D(i).SNO2		:= x.SNO2 ;
		REC_D(i).SNO3		:= x.SNO3 ;
		REC_D(i).SNO4		:= x.SNO4 ;
		REC_D(i).WG_CD		:= x.WG_CD ;

		REC_I(i).ITM_CD		:= x.ITM_CD ;
		REC_I(i).ITM_SUB1	:= x.ITM_SUB1 ;
		REC_I(i).ITM_SUB2	:= x.ITM_SUB2 ;
		REC_I(i).ITM_SUB3	:= x.ITM_SUB3 ;
		REC_I(i).LOT_NO		:= x.LOT_NO ;
		REC_I(i).SUBLOT_NO	:= x.SUBLOT_NO ;
		REC_I(i).SNO1		:= x.SNO1 ;
		REC_I(i).SNO2		:= x.SNO2 ;
		REC_I(i).SNO3		:= x.SNO3 ;
		REC_I(i).SNO4		:= x.SNO4 ;
		REC_I(i).WG_CD		:= x.WG_CD ;
		REC_I(i).CALC_YM	:= G_YM ;

		-- 滞留基準年月判定
		IF L_GR_YM IS NULL OR L_GI_YM >= L_GR_YM THEN
			REC_I(i).NON_MOV_BASE_YM	:= L_GI_YM ;
			REC_I(i).NON_MOV_GI_YM		:= L_GI_YM ;
		ELSE
			REC_I(i).NON_MOV_BASE_YM	:= L_GR_YM ;
			REC_I(i).NON_MOV_GR_YM		:= L_GR_YM ;
		END IF ;

	END LOOP ;

	IF i > 0 THEN

		-- 既存滞留在庫情報削除
		FORALL t IN 1..i
			DELETE FROM MGT_NON_MOV_STK T
			WHERE 0=0
			AND T.ITM_CD = REC_D(t).ITM_CD
			AND T.ITM_SUB1 = REC_D(t).ITM_SUB1
			AND T.ITM_SUB2 = REC_D(t).ITM_SUB2
			AND T.ITM_SUB3 = REC_D(t).ITM_SUB3
			AND T.LOT_NO = REC_D(t).LOT_NO
			AND T.SUBLOT_NO = REC_D(t).SUBLOT_NO
			AND T.SNO1 = REC_D(t).SNO1
			AND T.SNO2 = REC_D(t).SNO2
			AND T.SNO3 = REC_D(t).SNO3
			AND T.SNO4 = REC_D(t).SNO4
			AND T.WG_CD = REC_D(t).WG_CD
			;

		-- 滞留在庫情報作成
		FORALL t IN 1..i
			INSERT INTO MGT_NON_MOV_STK VALUES REC_I(t) ;

	END IF ;

	--処理が終了しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0002', 'MGPA_INS_SCM2MGTIF.P_SET_NON_MOVE') ;

END P_SET_NON_MOVE ;

PROCEDURE P_IF (
	I_YM	IN	MAPA_META.YM%TYPE,
	I_CALC_CTG_CD	IN	MAPA_META.CALC_CTG_CD%TYPE,
	I_IO	IN	MAPA_META.FLG%TYPE,
	I_WK	IN	MAPA_META.FLG%TYPE,
	I_WIP	IN	MAPA_META.FLG%TYPE,
	I_STK	IN	MAPA_META.FLG%TYPE,
	I_RERUN	IN	MAPA_META.FLG%TYPE,
	I_NON_MOV	IN	MAPA_META.FLG%TYPE DEFAULT '0'
)
/************************************************************************
<SYNOPSIS>
	ＳＣＭデータから原価実績インターフェースデータの作成処理を行う
<REMARKS>

<ARGUMENTS>
<IN>	I_YM
		対象年月
<IN>	I_CALC_CTG_CD
		計算カテゴリＣＤ
<IN>	I_IO
		受払実績 0:実行しない 1:実行する
<IN>	I_WK
		作業実績 0:実行しない 1:実行する
<IN>	I_WIP
		仕掛実績 0:実行しない 1:実行する
<IN>	I_STK
		在庫情報 0:実行しない 1:実行する
<IN>	I_RERUN
		0:追加処理 1:再取込
<HISTORY>
*************************************************************************/
AS
/************************************************************************/
	C_PURC		CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PURC ;		--仕入
	C_PURC_XPNS	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PURC_XPNS ;	--経費購買
	C_ARR_IN_TRANSIT	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.ARR_IN_TRANSIT ;		--未着品入荷
	C_PURC_RET	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PURC_RET ;	--仕入返品
	C_PURC_RET_XPNS	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PURC_RET_XPNS ;	--経費返品
	C_PURC_DSCNT	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PURC_DSCNT ;	--仕入値引
	C_PURC_DSCNT_XPNS	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PURC_DSCNT_XPNS ;	--経費値引
	C_PURC_XTRA	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PURC_XTRA ;	--仕入値増
	C_PURC_XTRA_XPNS	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PURC_XTRA_XPNS ;	--経費値増
	C_SLS		CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.SLS ;		--売上
	C_SLS_RET	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.SLS_RET ;	--売上返品
	C_SLS_DSCNT	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.SLS_DSCNT ;	--売上値引
	C_SLS_XTRA	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.SLS_XTRA ;	--売上値増
	C_MFG		CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.MFG ;		--製造
	C_BYPROD	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.BYPROD ;		--副産物製造
	C_INPUT		CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.INPUT ;		--投入
	C_IN_ONR	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.IN_ONR ;		--投入(有償)
	C_IN_SS		CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.IN_SS ;		--投入(自給)
	C_FFR_PROV	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.FFR_PROV ;	--無償支給
	C_ONR_PROV	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.ONR_PROV ;	--有償支給
	C_FFR_PRVR	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.FFR_PRVR ;	--無償支給戻
	C_ONR_PRVR	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.ONR_PRVR ;	--有償支給戻
	C_INSP_SMPL	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.INSP_SMPL ;	--検査抜取
	C_DISP_SCRP	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.DISP_SCRP ;	--廃棄
	C_SO_STKTK	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.SO_STKTK ;	--棚卸出庫
	C_IN_STKTK	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.IN_STKTK ;	--棚卸入庫
	C_PROD_ITM_SO	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PROD_ITM_SO ;	--販売倉入
	C_PROD_ITM_RET_SO CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PROD_ITM_RET_SO ; --生産戻入
	C_DPT_XFR_SO	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.DPT_XFR_SO ;	--部門間移動
	C_OTH_CCN_SO	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.OTH_CCN_SO ;	--他勘定出庫
	C_OTH_CCN_GR	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.OTH_CCN_GR ;	--他勘定入庫
	C_STK_SW_SO	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.STK_SW_SO ;	--在庫振替出庫
	C_STK_SW_GR	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.STK_SW_GR ;	--在庫振替入庫
	C_SHIP		CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.SHIP ;		--出荷
	C_SHIP_RET	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.SHIP_RET ;	--出荷返品
	C_EOM_STK_PROD	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.EOM_STK_PROD ;	--月末在庫(生産)
	C_EOM_STK_SLS	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.EOM_STK_SLS ;	--月末在庫(販売)

	C_CRT	CONSTANT MAPA_META.SLIP_STS_TYP%TYPE := MAC_SLIP_STS_TYP.CRT ;	-- 新規
	C_DIS	CONSTANT MAPA_META.SLIP_STS_TYP%TYPE := MAC_SLIP_STS_TYP.DIS ;	-- 無効
	C_CAN	CONSTANT MAPA_META.SLIP_STS_TYP%TYPE := MAC_SLIP_STS_TYP.CAN ;	-- 取消

	C_STR_NO	CONSTANT MAPA_META.STR20%TYPE := MGC_STR.ITM_MFG_INST_NO_PREFIX ;
	C_STR_NO2	CONSTANT MAPA_META.STR20%TYPE := MGC_STR.ITM_MFG_INST_NO_PREFIX2 ;
	C_STR_TRD2	CONSTANT MAPA_META.STR20%TYPE := MGC_STR.TRD_PREFIX2 ;
	C_STR_TRD3	CONSTANT MAPA_META.STR20%TYPE := MGC_STR.TRD_PREFIX3 ;

	C_ITM_MFG_INST			CONSTANT MAPA_META.NUM_SYS_TYP%TYPE := MGC_NUM_SYS_TYP.ITM_MFG_INST ;	-- 品目製造指図ＮＯ
	C_ITM_MFG_INST_LENGTH	CONSTANT NUMBER := MGC_NUM_SYS_TYP.LENGTH(C_ITM_MFG_INST) ;
	C_ACT_MFG_IF_DATA_LNO	CONSTANT MAPA_META.NUM_SYS_TYP%TYPE := MGC_NUM_SYS_TYP.ACT_MFG_IF_DATA_LNO ;	-- 製造実績ＩＦデータ行ＮＯ
	C_ACT_PURC_IF_DATA_LNO	CONSTANT MAPA_META.NUM_SYS_TYP%TYPE := MGC_NUM_SYS_TYP.ACT_PURC_IF_DATA_LNO ;	-- 購買実績ＩＦデータ行ＮＯ
	C_ACT_INPT_IF_DATA_LNO	CONSTANT MAPA_META.NUM_SYS_TYP%TYPE := MGC_NUM_SYS_TYP.ACT_INPT_IF_DATA_LNO ;	-- 投入実績ＩＦデータ行ＮＯ
	C_ACT_IO_IF_DATA_LNO	CONSTANT MAPA_META.NUM_SYS_TYP%TYPE := MGC_NUM_SYS_TYP.ACT_IO_IF_DATA_LNO ;	-- 入出庫実績ＩＦデータ行ＮＯ
	C_ACT_SLS_IF_DATA_LNO	CONSTANT MAPA_META.NUM_SYS_TYP%TYPE := MGC_NUM_SYS_TYP.ACT_SLS_IF_DATA_LNO ;	-- 売上実績ＩＦデータ行ＮＯ
	C_ACT_STK_IF_DATA_LNO	CONSTANT MAPA_META.NUM_SYS_TYP%TYPE := MGC_NUM_SYS_TYP.ACT_STK_IF_DATA_LNO ;	-- 在庫実績ＩＦデータ行ＮＯ
	C_ACT_INST_WIP_IF_DATA_LNO	CONSTANT MAPA_META.NUM_SYS_TYP%TYPE := MGC_NUM_SYS_TYP.ACT_INST_WIP_IF_DATA_LNO ;	-- 指図仕掛実績ＩＦデータ行ＮＯ
	C_ACT_INST_WK_IF_DATA_LNO	CONSTANT MAPA_META.NUM_SYS_TYP%TYPE := MGC_NUM_SYS_TYP.ACT_INST_WK_IF_DATA_LNO ;	-- 指図工数実績ＩＦデータ行ＮＯ
	C_ACT_OTHER_WK_IF_DATA_LNO	CONSTANT MAPA_META.NUM_SYS_TYP%TYPE := MGC_NUM_SYS_TYP.ACT_OTHER_WK_IF_DATA_LNO ;	-- 指図外工数実績ＩＦデータ行ＮＯ

	C_ITM		CONSTANT MAPA_META.MFG_INST_UNIT_TYP%TYPE := MAC_MFG_INST_UNIT_TYP.ITM ;	--品目単位
	C_OPER		CONSTANT MAPA_META.MFG_INST_UNIT_TYP%TYPE := MAC_MFG_INST_UNIT_TYP.OPER ;	--工程単位

	C_ACT1		CONSTANT MAPA_META.ACT_SET_TYP%TYPE := MAC_ACT_SET_TYP.NON ;	--対象外
	C_ACT2		CONSTANT MAPA_META.ACT_SET_TYP%TYPE := MAC_ACT_SET_TYP.ALL_SET ;--設定
	C_ACT3		CONSTANT MAPA_META.ACT_SET_TYP%TYPE := MAC_ACT_SET_TYP.IN_SET ;	--受入のみ設定

	C_PS_USE1	CONSTANT MAPA_META.PS_USE_TYP%TYPE := MAC_PS_USE_TYP.PRODSLS ;	--生産・販売データで使用する
	C_PS_USE2	CONSTANT MAPA_META.PS_USE_TYP%TYPE := MAC_PS_USE_TYP.PROD ;	--生産データのみ使用する
	C_PS_USE3	CONSTANT MAPA_META.PS_USE_TYP%TYPE := MAC_PS_USE_TYP.SLS ;	--販売データのみ使用する

	C_ASST1		CONSTANT MAPA_META.ASST_TYP%TYPE := MAC_ASST_TYP.CO_SLS ;	 --自社(販売)
	C_ASST2		CONSTANT MAPA_META.ASST_TYP%TYPE := MAC_ASST_TYP.CO_PROD ;	 --自社(生産)
	C_ASST3		CONSTANT MAPA_META.ASST_TYP%TYPE := MAC_ASST_TYP.OTH ;		 --他社

	C_STK_ID1	CONSTANT MAPA_META.STR20%TYPE := '1' ;	--自社在庫
	C_STK_ID8	CONSTANT MAPA_META.STR20%TYPE := '8' ;	--有償支給

	C_MODULE_MG	CONSTANT MAPA_META.MODULE_ID%TYPE := FSC_MODULE_ID.CostManagement ;	-- 原価管理

	C_ASST_MNG1	CONSTANT MAPA_META.ASSET_MNG_TYP%TYPE := MAC_ASSET_MNG_TYP.MNG ;	--資産管理する
	C_ASST_MNG2	CONSTANT MAPA_META.ASSET_MNG_TYP%TYPE := MAC_ASSET_MNG_TYP.NOT_MNG ;	--資産管理しない
	C_ASST_MNG3	CONSTANT MAPA_META.ASSET_MNG_TYP%TYPE := MAC_ASSET_MNG_TYP.PHANTOM ;	--架空品

	C_END_STK	CONSTANT MAPA_META.STR20%TYPE := 'Z0101' ;	-- 月末在庫

	C_FIX_NO_DLV_SLIP_NO	CONSTANT MAPA_META.STR20%TYPE := '2' ;	--納品書ＮＯ
	C_FIX_NO_IV_NO			CONSTANT MAPA_META.STR20%TYPE := '3' ;	--インボイスＮＯ
	C_FIX_NO_PURC_ACT_IO	CONSTANT MAPA_META.STR20%TYPE := '6' ;	--仕入実績受払ＮＯ

	C_TRD_PTN_SLS_RTN	CONSTANT MAPA_META.TRD_PTN_TYP%TYPE := MAC_TRD_PTN_TYP.SLS_RTN ;	--売上返品
	C_TRD_PTN_SLS	CONSTANT MAPA_META.TRD_PTN_TYP%TYPE := MAC_TRD_PTN_TYP.SLS ;	--売上

	C_UNFIXED	CONSTANT MAPA_META.STR20%TYPE := '**' ;	--未確定

	C_STR_NO3		CONSTANT MAPA_META.STR20%TYPE := MGC_STR.ITM_MFG_INST_NO_PREFIX3 ;
	C_INST_LOC		CONSTANT MAPA_META.ITM_MFG_INST_NO_SET_TYP%TYPE := MAC_ITM_MFG_INST_NO_SET_TYP.LOC ;	--場所
	C_MFG_NON		CONSTANT MAPA_META.MFG_ACT_NO_SET_TYP%TYPE := MAC_MFG_ACT_NO_SET_TYP.NON ;		--設定なし
	C_OPER_NON		CONSTANT MAPA_META.OPER_ACT_NO_SET_TYP%TYPE := MAC_OPER_ACT_NO_SET_TYP.NON ;		--設定なし
	C_OPER_OPER		CONSTANT MAPA_META.OPER_ACT_NO_SET_TYP%TYPE := MAC_OPER_ACT_NO_SET_TYP.OPER ;		--工程
	C_ITM_MFG_INST_NO_L	CONSTANT NUMBER := MAPA_META.ITM_MFG_INST_NO_L ;
	C_MFG_ACT_NO_L		CONSTANT NUMBER := MAPA_META.MFG_ACT_NO_L ;

	L_RSLT		INTEGER ;
	L_DPT_ERR	INTEGER ;

	L_MSG		FCPA_ERR.MSG_BINDER ;

	L_CO		MAM_CO%ROWTYPE ;

	L_SIGN		MAPA_META.MONEY%TYPE ;
	L_QTY		MAPA_META.QTY%TYPE ;

	L_TERM		MAPA_META.YM%TYPE ;
	L_ST_DT		MAPA_META.DT%TYPE ;
	L_END_DT	MAPA_META.DT%TYPE ;

	L_PARM		MAPA_META.PARM_VAL%TYPE ;

	REC_DPT		MGPA_COST_IF.LIST_DPT ;

	L_PURC_DPT	MAPA_META.COST_DPT_CD%TYPE ;	--購買部門
	L_AP_DPT	MAPA_META.COST_DPT_CD%TYPE ;	--債務部門
	L_SLS_DPT	MAPA_META.COST_DPT_CD%TYPE ;	--売上部門
	L_AR_DPT	MAPA_META.COST_DPT_CD%TYPE ;	--債権部門
	L_GI_DPT	MAPA_META.COST_DPT_CD%TYPE ;	--出庫部門
	L_GR_DPT	MAPA_META.COST_DPT_CD%TYPE ;	--入庫部門
	L_BD_DPT	MAPA_META.COST_DPT_CD%TYPE ;	--負担部門
	L_SUB_DPT1	MAPA_META.COST_DPT_CD%TYPE ;	--予備部門1
	L_SUB_DPT2	MAPA_META.COST_DPT_CD%TYPE ;	--予備部門2
	L_SUB_DPT3	MAPA_META.COST_DPT_CD%TYPE ;	--予備部門3
	L_OUTSRC_MFG_LOC_DPT_CD	MAPA_META.COST_DPT_CD%TYPE ;	--外注製造場所部門ＣＤ

	L_MDPT		MAPA_META.COST_DPT_CD%TYPE ;	--管理部門
	L_ODPT		MAPA_META.COST_DPT_CD%TYPE ;	--配賦部門、親部門、相手部門、売上部門

	L_WG		MAPA_META.WG_CD%TYPE ;	--ワーキンググループＣＤ
	L_OWG		MAPA_META.WG_CD%TYPE ;	--相手ワーキンググループＣＤ

	L_LOC		MAPA_META.LOC_CD%TYPE ;

	L_TRD_RATIO	MGPA_META.TRD_RATIO%TYPE ;

	L_CO_PARM		MAM_CO_PARM%ROWTYPE ;
	L_LOT_USE_TYP	MAPA_META.PS_USE_TYP%TYPE ;
	L_SUBLOT_USE_TYP	MAPA_META.PS_USE_TYP%TYPE ;
	L_SNO1_USE_TYP	MAPA_META.PS_USE_TYP%TYPE ;
	L_SNO2_USE_TYP	MAPA_META.PS_USE_TYP%TYPE ;
	L_SNO3_USE_TYP	MAPA_META.PS_USE_TYP%TYPE ;
	L_SNO4_USE_TYP	MAPA_META.PS_USE_TYP%TYPE ;
	L_FIX_DPT		MAPA_META.COST_DPT_CD%TYPE ;
	L_TRD_FLG		MAPA_META.FLG%TYPE ;
	L_STOP_SLIP_FLG	MAPA_META.FLG%TYPE ;
	L_OPER_SUM_FLG	MAPA_META.FLG%TYPE ;
	L_NON_PROD_FLG	MAPA_META.FLG%TYPE ;
	L_NON_SLS_FLG	MAPA_META.FLG%TYPE ;
	L_ASST_FLG		MAPA_META.FLG%TYPE ;
	L_STK_BP_FLG	MAPA_META.FLG%TYPE ;
	L_MFG_ZERO_FLG	MAPA_META.FLG%TYPE ;

	L_CNT			NUMBER ;
	L_CHK_ERR		MAPA_META.FLG%TYPE ;
	L_TMP_DT		DATE ;

	L_REC_CNT		NUMBER ;
	L_INST_WK_CNT	NUMBER ;
	L_OTHER_WK_CNT	NUMBER ;
	L_STK_CNT		NUMBER ;
	L_WIP_CNT		NUMBER ;
	L_ITM_OUT_CNT	NUMBER ;
	L_RSN_GI_CNT	NUMBER ;

	L_BASE_CUR_CD		MAPA_META.CUR_CD%TYPE ;
	L_UPRI_DEC_PLACE	MAPA_META.DEC_PLACE%TYPE ;
	L_AMT_DEC_PLACE		MAPA_META.DEC_PLACE%TYPE ;

	L_ITM_MFG_INST_NO	MAPA_META.ITM_MFG_INST_NO%TYPE ;
	L_MFG_ACT_NO	MAPA_META.MFG_ACT_NO%TYPE ;
	L_OPER_ACT_NO	MAPA_META.OPER_ACT_NO%TYPE ;
	L_ASST_TYP		MAPA_META.ASST_TYP%TYPE ;

	L_TGT_PO_NO_FLG	MAPA_META.FLG%TYPE := C_OFF ;
	L_TGT_SLO_FLG	MAPA_META.FLG%TYPE := C_OFF ;
	L_TGT_IV_FLG	MAPA_META.FLG%TYPE := C_OFF ;

	L_MAX_TS		MAPA_META.SYS_TS%TYPE ;

	C_MAX_CNT		CONSTANT BINARY_INTEGER := 50000 ;	--バルクインサートでの最大レコード数

	LOCK_ERROR     EXCEPTION ;
	PRAGMA EXCEPTION_INIT(LOCK_ERROR, -54) ;

/************************************************************************/
BEGIN
	--処理を開始しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0001', 'MGPA_INS_SCM2MGTIF.P_IF') ;

	--期の取得
	L_TERM := MAPA_TERM.F_GET_TERM_NE(I_YM) ;

	--自社情報の取得
	L_CO := MAPA_CO.F_GET_CO_REC() ;

	--基準通貨情報の取得
	MAPA_XCHNG.P_GET_BASE_CUR_INFO(L_BASE_CUR_CD, L_UPRI_DEC_PLACE, L_AMT_DEC_PLACE) ;

	--月初／月度末日の計算
	L_ST_DT := MAPA_DT.F_GET_YM_ST_DT_NE(I_YM, L_CO.AC_CL_DAY, L_CO.AC_CL_MON_BASE) ;
	L_END_DT := MAPA_DT.F_GET_YM_END_DT_NE(I_YM, L_CO.AC_CL_DAY, L_CO.AC_CL_MON_BASE) ;

	--パラメータの取得
	L_CO_PARM := MGPA_CO_PARM.F_GET_REC ;
	L_LOT_USE_TYP := NVL(L_CO_PARM.LOT_USE_TYP, C_PS_USE1) ;
	L_SUBLOT_USE_TYP := NVL(L_CO_PARM.SUBLOT_USE_TYP, C_PS_USE1) ;
	L_SNO1_USE_TYP := NVL(L_CO_PARM.SNO1_USE_TYP, C_PS_USE1) ;
	L_SNO2_USE_TYP := NVL(L_CO_PARM.SNO2_USE_TYP, C_PS_USE1) ;
	L_SNO3_USE_TYP := NVL(L_CO_PARM.SNO3_USE_TYP, C_PS_USE1) ;
	L_SNO4_USE_TYP := NVL(L_CO_PARM.SNO4_USE_TYP, C_PS_USE1) ;
	L_FIX_DPT := L_CO_PARM.FIX_DPT_CD ;
	L_TRD_FLG  := L_CO_PARM.TRD_RATIO_FLG ;
	L_STOP_SLIP_FLG  := L_CO_PARM.STOP_SLIP_FLG ;
	L_OPER_SUM_FLG := L_CO_PARM.OPER_SUM_FLG ;
	L_NON_PROD_FLG := L_CO_PARM.NON_PROD_FLG ;
	L_NON_SLS_FLG := L_CO_PARM.NON_SLS_FLG ;
	L_ASST_FLG := L_CO_PARM.ASST_FLG ;
	L_STK_BP_FLG := L_CO_PARM.STK_BP_FLG ;
	G_LOT_NON_MOV_FLG  := L_CO_PARM.LOT_NON_MOV_FLG ;
	G_SUBLOT_NON_MOV_FLG  := L_CO_PARM.SUBLOT_NON_MOV_FLG ;
	G_SNO1_NON_MOV_FLG  := L_CO_PARM.SNO1_NON_MOV_FLG ;
	G_SNO2_NON_MOV_FLG  := L_CO_PARM.SNO2_NON_MOV_FLG ;
	G_SNO3_NON_MOV_FLG  := L_CO_PARM.SNO3_NON_MOV_FLG ;
	G_SNO4_NON_MOV_FLG  := L_CO_PARM.SNO4_NON_MOV_FLG ;
	G_WG_NON_MOV_FLG  := L_CO_PARM.WG_NON_MOV_FLG ;

	L_RSLT := C_OK ;

	G_MFG_CNT := 0 ;
	G_PURC_CNT := 0 ;
	G_INPT_CNT := 0 ;
	G_IO_CNT := 0 ;
	G_SLS_CNT := 0 ;
	G_INST_WK_CNT := 0 ;
	G_MFG_INST_CNT := 0 ;
	G_INST_OPER_CNT := 0 ;

	REC_CHK_ITM.DELETE ;
	REC_CHK_OPER.DELETE ;
	REC_CHK_IV.DELETE ;
	REC_CHK_IV2.DELETE ;

	REC_w1.DELETE ;
	REC_w2.DELETE ;
	REC_w3.DELETE ;
	REC_w4.DELETE ;
	REC_w5.DELETE ;
	REC_w6.DELETE ;
	REC_w7.DELETE ;
	REC_w8.DELETE ;
	TMP_w3.DELETE ;
	REC_ID.DELETE ;
	TMP_w6.DELETE ;
	UPD_w6.DELETE ;

	w1 := 0 ;
	w2 := 0 ;
	w3 := 0 ;
	w4 := 0 ;
	w5 := 0 ;
	w6 := 0 ;
	w7 := 0 ;
	w8 := 0 ;
	t3 := 0 ;
	d1 := 0 ;
	t6 := 0 ;
	u6 := 0 ;

	SELECT	COUNT(m.ITM_CD)
	INTO	L_ITM_OUT_CNT
	FROM	MAM_COST_ITM_OUT m
	WHERE	0=0
	AND	m.YM <= I_YM
	;
	G_PARM_ITM_CNT := 0 ;
	G_PARM_PURC_IF_CNT := 0 ;
	G_PARM_SLS_IF_CNT := 0 ;

	REC_PARM_ITM.DELETE ;
	REC_PARM_PURC_IF.DELETE ;
	REC_PARM_SLS_IF.DELETE ;

	FOR z1 IN (
		SELECT	t.*
		FROM	MAM_IF_PARM t
		WHERE	0=0
		)
	LOOP
		IF z1.COL_PROC_TYP <> C_PROC_SET_UP THEN
			CASE z1.COST_TABLE_TYP
			WHEN C_TAB_ITM THEN
				G_PARM_ITM_CNT := G_PARM_ITM_CNT + 1 ;
				REC_PARM_ITM(G_PARM_ITM_CNT) := z1 ;
			WHEN C_TAB_PURC_IF THEN
				G_PARM_PURC_IF_CNT := G_PARM_PURC_IF_CNT + 1 ;
				REC_PARM_PURC_IF(G_PARM_PURC_IF_CNT) := z1 ;
			WHEN C_TAB_SLS_IF THEN
				G_PARM_SLS_IF_CNT := G_PARM_SLS_IF_CNT + 1 ;
				REC_PARM_SLS_IF(G_PARM_SLS_IF_CNT) := z1 ;
			END CASE ;
		END IF ;
	END LOOP ;
	IF G_PARM_ITM_CNT > 0 THEN
		FOR i IN 1..G_PARM_ITM_CNT LOOP
			CASE REC_PARM_ITM(i).TGT_COL_TYP
			WHEN C_TGT_PO_NO THEN
				L_TGT_PO_NO_FLG := C_ON ;
			WHEN C_TGT_SLO_NO THEN
				L_TGT_SLO_FLG := C_ON ;
			WHEN C_TGT_IV_NO THEN
				L_TGT_IV_FLG := C_ON ;
			END CASE ;
		END LOOP ;
	END IF ;

	L_PARM := MAPA_COMM.F_GET_PARM('ITM_SUB_TYP') ;

	--受払情報の取込
	IF I_IO = C_OFF THEN
		GOTO SKIP_TRAN ;
	END IF ;

	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0037', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2) ;

	--ロック後に追加されたレコードは取込対象外にする
	L_MAX_TS := NULL ;
	FOR y1 IN (
		SELECT	t.INS_TS
		FROM	MGVT_MST_IO_ACT t
		WHERE	0=0
		AND	t.AC_YM = I_YM
		AND	t.SEND_FLG = C_ON
		AND	(t.C_IMP_FLG = C_OFF OR I_RERUN = C_ON)
		ORDER BY t.INS_TS DESC, t.SLIP_NO, t.SLIP_SEQ_NO
		FOR UPDATE NOWAIT
		)
	LOOP
		L_MAX_TS := y1.INS_TS ;
		EXIT ;
	END LOOP ;

	IF I_RERUN = C_ON THEN
		DELETE	MGT_ITM_MFG_INST t
		WHERE	0=0
		AND	t.ITM_MFG_INST_NO LIKE C_STR_NO || '%'
		AND	LENGTH(t.ITM_MFG_INST_NO) = C_ITM_MFG_INST_LENGTH + LENGTH(C_STR_NO)
		AND	t.MFG_ACT_NO = C_NULL_VAL
		AND	t.CALC_CTG_CD = I_CALC_CTG_CD
		AND	EXISTS (
				SELECT	'X'
				FROM	MGT_ACT_INPT_IF w
				WHERE	0=0
				AND	w.PAR_ITM_CD = t.ITM_CD
				AND	w.PAR_ITM_SUB1 = t.ITM_SUB1
				AND	w.PAR_ITM_SUB2 = t.ITM_SUB2
				AND	w.PAR_ITM_SUB3 = t.ITM_SUB3
				AND	w.ITM_MFG_INST_NO = t.ITM_MFG_INST_NO
				AND	w.MFG_ACT_NO = t.MFG_ACT_NO
				AND	w.CALC_CTG_CD = t.CALC_CTG_CD
				AND	w.YM = I_YM
				)
		;

		DELETE	MGT_ITM_MFG_INST t
		WHERE	0=0
		AND	t.MFG_ACT_NO LIKE C_STR_NO || '%'
		AND	LENGTH(t.MFG_ACT_NO) = C_ITM_MFG_INST_LENGTH + LENGTH(C_STR_NO)
		AND	t.CALC_CTG_CD = I_CALC_CTG_CD
		AND	EXISTS (
				SELECT	'X'
				FROM	MGT_ACT_MFG_IF w
				WHERE	0=0
				AND	w.ITM_CD = t.ITM_CD
				AND	w.ITM_SUB1 = t.ITM_SUB1
				AND	w.ITM_SUB2 = t.ITM_SUB2
				AND	w.ITM_SUB3 = t.ITM_SUB3
				AND	w.ITM_MFG_INST_NO = t.ITM_MFG_INST_NO
				AND	w.MFG_ACT_NO = t.MFG_ACT_NO
				AND	w.CALC_CTG_CD = t.CALC_CTG_CD
				AND	w.YM = I_YM
				)
		;

		DELETE MGT_ACT_MFG_IF  t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG_CD ;
		DELETE MGT_ACT_PURC_IF t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG_CD ;
		DELETE MGT_ACT_INPT_IF t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG_CD ;
		DELETE MGT_ACT_IO_IF   t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG_CD ;
		DELETE MGT_ACT_SLS_IF  t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG_CD ;

		UPDATE	MGVT_MST_IO_ACT t
		SET	t.C_IMP_FLG = C_OFF
		WHERE	0=0
		AND	t.AC_YM = I_YM
		AND	t.SEND_FLG = C_ON
		AND	t.C_IMP_FLG = C_ON
		AND	t.INS_TS <= L_MAX_TS
		;

	END IF ;

	SELECT	COUNT(m.AC_RSN_CD)
	INTO	L_RSN_GI_CNT
	FROM	MAM_AC_RSN m
	WHERE	0=0
	AND	m.COST_INVALID_FLG = C_ON
	;

	IF L_STOP_SLIP_FLG = C_ON THEN
		GOTO SKIP_STOP ;
	END IF ;

	UPDATE	MGVT_MST_IO_ACT t1
	SET	t1.C_IMP_FLG = C_ON
	WHERE	0=0
	AND	t1.AC_YM = I_YM
	AND	t1.SEND_FLG = C_ON
	AND	t1.C_IMP_FLG = C_OFF
	AND	t1.INS_TS <= L_MAX_TS
	AND	EXISTS (
			SELECT	'X'
			FROM	MGVT_MST_IO_ACT t2
			WHERE	0=0
			AND	t2.SLIP_NO = t1.SLIP_NO
			AND	t2.SLIP_REV_NO = t1.SLIP_REV_NO
			AND	t2.AC_YM = I_YM
			AND	t2.SEND_FLG = C_ON
			AND	t2.C_IMP_FLG = C_OFF
			AND	t2.INS_TS <= L_MAX_TS
			AND	t2.SLIP_STS_TYP = C_DIS
			)
	AND	EXISTS (
			SELECT	'X'
			FROM	MGVT_MST_IO_ACT t2
			WHERE	0=0
			AND	t2.SLIP_NO = t1.SLIP_NO
			AND	t2.SLIP_REV_NO = t1.SLIP_REV_NO
			AND	t2.AC_YM = I_YM
			AND	t2.SEND_FLG = C_ON
			AND	t2.C_IMP_FLG = C_OFF
			AND	t2.INS_TS <= L_MAX_TS
			AND	t2.SLIP_STS_TYP = C_CAN
			)
	;

	<<SKIP_STOP>>
		NULL ;

	IF L_CO_PARM.NON_TRANSIT_FLG = C_ON THEN
		UPDATE	MGVT_MST_IO_ACT t1
		SET	t1.C_IMP_FLG = C_ON
		WHERE	0=0
		AND	t1.AC_YM = I_YM
		AND	t1.SEND_FLG = C_ON
		AND	t1.C_IMP_FLG = C_OFF
		AND	t1.INS_TS <= L_MAX_TS
		AND	t1.AC_SLIP_TYP = C_PURC AND t1.FIX_NO_TYP = C_FIX_NO_PURC_ACT_IO
		AND	(t1.ITM_MFG_INST_NO IS NULL OR t1.ASSET_MNG_TYP <> C_ASST_MNG1);
	END IF ;

	L_REC_CNT := 0 ;
	L_TMP_DT := NULL ;
	REC_DPT.DELETE ;
	FOR x1 IN
		(
		SELECT	t.ROWID		ROW_ID,
			t.SLIP_NO,
			t.SLIP_SEQ_NO,
			t.AC_YM	AC_YM,
			TRUNC(t.AC_DT, 'DD')	AC_DT,
			t.AC_SLIP_TYP,
			t.AC_RSN_CD,
			t.GI_WG_CD,
			t.GR_WG_CD,
			t.BD_WG_CD,
			m6.WG_CD	PURC_WG_CD,
			t.PURC_TYP,
			t.PURC_DPT_CD,	--購買部門
			t.AP_DPT_CD,	--債務部門
			t.SLS_DPT_CD,	--売上部門
			t.AR_DPT_CD,	--債権部門
			t.GI_DPT_CD,	--出庫部門
			t.GR_DPT_CD,	--入庫部門
			t.BD_DPT_CD,	--負担部門
			t.SUB_DPT_CD1,	--予備部門1
			t.SUB_DPT_CD2,	--予備部門2
			t.SUB_DPT_CD3,	--予備部門3
			t.LOC_CD,
			t.STR_LN_CD,
			t.SLS_USR_CD,
			t.ITM_CD,
			t.ITM_SUB1,
			t.ITM_SUB2,
			t.ITM_SUB3,
			t.LOT_NO,
			t.SUBLOT_NO,
			t.SNO1,
			t.SNO2,
			t.SNO3,
			t.SNO4,
			t.FIX_NO_TYP,
			t.ASST_TYP,
			t.STK_ID_TYP,
			t.BASE_UNIT_QTY	QTY,
			t.BASE_CUR_AMT	AMT,
			t.TRD_CUR_CD,
			t.TRD_CUR_AMT,
			t.XRATE,
			t.SLO_NO,
			t.PO_NO,
			t.IV_NO,
			t.RCPT_IV_NO,
			t.BD_CTG_CD,
			t.BD_BP_CD,
			t.BD_OPER_CD,
			t.BD_LOC_CD,
			t.BD_SLO_NO,
			t.BD_PO_NO,
			t.BD_IV_NO,
			t.DLV_CD,
			NVL(t.CST_CD, t.ACST_CD)	CST_CD,
			t.DEST_CD1,
			t.DEST_CD2,
			t.DEST_CD3,
			NVL(t.SPPL_CD, t.ASPPL_CD)	BP_CD,
			t.ITM_MFG_INST_NO,
			t.ITM_INST_QTY,
			t.MFG_ST_QTY,
			t.MFG_ACT_NO,
			t.OPER_ACT_NO,
			t.DISP_SEQ,
			t.OPER_CD,
			t.OUTSRC_MFG_LOC_CD,
			t.OUTSRC_MFG_LOC_DPT_CD,
			t.OUTSRC_MFG_LOC_WG_CD,
			t.MFG_INST_UNIT_TYP,
			t.PAR_ITM_CD,
			t.PAR_ITM_SUB1,
			t.PAR_ITM_SUB2,
			t.PAR_ITM_SUB3,
			t.PAR_LOT_NO,
			t.PAR_SUBLOT_NO,
			t.PAR_SNO1,
			t.PAR_SNO2,
			t.PAR_SNO3,
			t.PAR_SNO4,
			t.ACT_NO,
			NVL(t.YIELD_RATE, 100)	YIELD_RATE,
			t.TRD_RMRKS,
			t.TRD_D_RMRKS,
			t.TRD_PTN_TYP,
			NVL(m1.ASSET_MNG_TYP, C_ASST1)	ASSET_MNG_TYP,
			NVL(m1.DEL_FLG, C_ON)			DEL_FLG,
			NVL(m1.DSCNT_ITM_FLG, C_OFF)	DSCNT_ITM_FLG,
			NVL(m2.LOT_ACT_TYP, C_ACT1)		LOT_ACT_TYP,
			NVL(m2.SUBLOT_ACT_TYP, C_ACT1)	SUBLOT_ACT_TYP,
			NVL(m2.SNO1_ACT_TYP, C_ACT1)	SNO1_ACT_TYP,
			NVL(m2.SNO2_ACT_TYP, C_ACT1)	SNO2_ACT_TYP,
			NVL(m2.SNO3_ACT_TYP, C_ACT1)	SNO3_ACT_TYP,
			NVL(m2.SNO4_ACT_TYP, C_ACT1)	SNO4_ACT_TYP,
			DECODE(t.PAR_ITM_CD, NULL, m2.ITM_MFG_INST_NO_SET_TYP, m4.ITM_MFG_INST_NO_SET_TYP)	ITM_MFG_INST_NO_SET_TYP,
			DECODE(t.PAR_ITM_CD, NULL, m2.MFG_ACT_NO_SET_TYP, m4.MFG_ACT_NO_SET_TYP)			MFG_ACT_NO_SET_TYP,
			DECODE(t.PAR_ITM_CD, NULL, m2.OPER_ACT_NO_SET_TYP, m4.OPER_ACT_NO_SET_TYP)			OPER_ACT_NO_SET_TYP,
			NVL(m3.ASSET_MNG_TYP, C_ASST1)	PAR_ASSET_MNG_TYP,
			NVL(m3.DEL_FLG, C_ON)			PAR_DEL_FLG,
			NVL(m4.LOT_ACT_TYP, C_ACT1)		PAR_LOT_ACT_TYP,
			NVL(m4.SUBLOT_ACT_TYP, C_ACT1)	PAR_SUBLOT_ACT_TYP,
			NVL(m4.SNO1_ACT_TYP, C_ACT1)	PAR_SNO1_ACT_TYP,
			NVL(m4.SNO2_ACT_TYP, C_ACT1)	PAR_SNO2_ACT_TYP,
			NVL(m4.SNO3_ACT_TYP, C_ACT1)	PAR_SNO3_ACT_TYP,
			NVL(m4.SNO4_ACT_TYP, C_ACT1)	PAR_SNO4_ACT_TYP,
			NVL(m5.DLV_FLG, C_OFF)			DLV_FLG,
			NVL(m5.TDLV_FLG, C_ON)			TDLV_FLG
		FROM	MGVT_MST_IO_ACT t, MAM_ITM_SRCH m1, MAM_CALC_PTN m2, MAM_ITM_SRCH m3, MAM_CALC_PTN m4, MAM_BP m5, MAM_DPT m6
		WHERE	0=0
		AND	t.AC_YM = I_YM
		AND	t.SEND_FLG = C_ON
		AND	t.C_IMP_FLG = C_OFF
		AND	t.INS_TS <= L_MAX_TS
		AND	t.ITM_CD = m1.ITM_CD(+)
		AND	t.ITM_SUB1 = m1.ITM_SUB1(+)
		AND	t.ITM_SUB2 = m1.ITM_SUB2(+)
		AND	t.ITM_SUB3 = m1.ITM_SUB3(+)
		AND	m1.CALC_PTN_CD = m2.CALC_PTN_CD(+)
		AND	t.PAR_ITM_CD = m3.ITM_CD(+)
		AND	t.PAR_ITM_SUB1 = m3.ITM_SUB1(+)
		AND	t.PAR_ITM_SUB2 = m3.ITM_SUB2(+)
		AND	t.PAR_ITM_SUB3 = m3.ITM_SUB3(+)
		AND	m3.CALC_PTN_CD = m4.CALC_PTN_CD(+)
		AND	t.DLV_CD = m5.BP_CD(+)
		AND	m1.DEL_FLG(+) = C_OFF
		AND	m1.RELEASE_FLG(+) = C_ON
		AND	m3.DEL_FLG(+) = C_OFF
		AND	m3.RELEASE_FLG(+) = C_ON
		AND	t.PURC_DPT_CD = m6.DPT_CD(+)
		AND	t.AC_DT >= m6.ST_DT(+)
		AND	t.AC_DT <= m6.END_DT(+)
		AND	m6.DEL_FLG(+) = C_OFF
		ORDER BY t.AC_DT DESC, t.SLIP_NO DESC, t.SLIP_SEQ_NO DESC
		)
	LOOP
		L_DPT_ERR := C_OK ;

		L_MDPT := NULL ;
		L_ODPT := NULL ;
		L_WG := NULL ;
		L_OWG := NULL ;
		L_LOC := NULL ;
		L_MFG_ZERO_FLG := C_OFF ;

		IF x1.QTY = 0 AND (x1.AMT = 0 OR x1.AMT IS NULL) THEN
			IF x1.AC_SLIP_TYP = C_MFG THEN
				L_MFG_ZERO_FLG := C_ON ;
			ELSE
				GOTO NEXT_LOOP ;
			END IF ;
		END IF ;

		--有償支給・有償支給戻・投入(有償)・投入(自給)以外で資産区分=1,2以外は対象外
		IF x1.AC_SLIP_TYP IN (C_ONR_PROV, C_ONR_PRVR, C_IN_ONR, C_IN_SS) THEN
			NULL ;
		ELSIF x1.ASST_TYP <> C_ASST1 AND x1.ASST_TYP <> C_ASST2 THEN
			--外注先の他社資産の受払は対象とする
			IF x1.ASST_TYP = C_ASST3 AND x1.BP_CD IS NOT NULL THEN
				NULL ;
			ELSE
				GOTO NEXT_LOOP ;
			END IF ;
		END IF ;

		IF L_ITM_OUT_CNT > 0 THEN
			--原価対象外のチェック
			SELECT	COUNT(m.ITM_CD)
			INTO	L_CNT
			FROM	MAM_COST_ITM_OUT m
			WHERE	0=0
			AND	m.ITM_CD = x1.ITM_CD
			AND	m.ITM_SUB1 = x1.ITM_SUB1
			AND	m.ITM_SUB2 = x1.ITM_SUB2
			AND	m.ITM_SUB3 = x1.ITM_SUB3
			AND	m.YM <= I_YM
			;

			IF L_CNT > 0 THEN
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.PAR_ITM_CD IS NOT NULL THEN
				SELECT	COUNT(m.ITM_CD)
				INTO	L_CNT
				FROM	MAM_COST_ITM_OUT m
				WHERE	0=0
				AND	m.ITM_CD = x1.PAR_ITM_CD
				AND	m.ITM_SUB1 = x1.PAR_ITM_SUB1
				AND	m.ITM_SUB2 = x1.PAR_ITM_SUB2
				AND	m.ITM_SUB3 = x1.PAR_ITM_SUB3
				AND	m.YM <= I_YM
				;

				IF L_CNT > 0 THEN
					--原価対象外品目マスタに親品目が登録されています。取込対象外となるため子品目の払い出しも無効になります。
					--テーブル：{1} 親品目：{2} 品目：{3}
					FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0046', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, 'MST_IO_ACT',
						MAPA_COMM.F_TO_DISP_ITM(x1.PAR_ITM_CD, x1.PAR_ITM_SUB1, x1.PAR_ITM_SUB2, x1.PAR_ITM_SUB3, L_PARM),
						MAPA_COMM.F_TO_DISP_ITM(x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, L_PARM)) ;
					L_RSLT := C_ERR ;
					GOTO NEXT_LOOP ;
				END IF ;
			END IF ;
		END IF ;

		IF L_RSN_GI_CNT > 0 AND x1.AC_RSN_CD IS NOT NULL THEN
			--原価対象外のチェック
			SELECT	COUNT(m.AC_RSN_CD)
			INTO	L_CNT
			FROM	MAM_AC_RSN m
			WHERE	0=0
			AND	m.AC_RSN_CD = x1.AC_RSN_CD
			AND	m.COST_INVALID_FLG = C_ON
			;

			IF L_CNT > 0 THEN
				GOTO NEXT_LOOP ;
			END IF ;
		END IF ;

		IF x1.DEL_FLG = C_ON THEN
			--品目マスタに登録されていません。テーブル：{1} 品目：{2}
			FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0011', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, 'MST_IO_ACT',
						MAPA_COMM.F_TO_DISP_ITM(x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, L_PARM)) ;
			L_RSLT := C_ERR ;
			GOTO NEXT_LOOP ;
		END IF ;
		IF x1.PAR_ITM_CD IS NOT NULL AND (x1.PAR_DEL_FLG = C_ON) THEN
			--親品目が品目マスタに登録されていません。取込対象外となるため子品目の払い出しも無効になります。
			--テーブル：{1} 親品目：{2} 品目：{3}
			FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0047', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, 'MST_IO_ACT',
						MAPA_COMM.F_TO_DISP_ITM(x1.PAR_ITM_CD, x1.PAR_ITM_SUB1, x1.PAR_ITM_SUB2, x1.PAR_ITM_SUB3, L_PARM),
						MAPA_COMM.F_TO_DISP_ITM(x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, L_PARM)) ;
			L_RSLT := C_ERR ;
			GOTO NEXT_LOOP ;
		END IF ;

		--部門の変換
		IF L_TMP_DT IS NULL OR L_TMP_DT <> x1.AC_DT THEN
			REC_DPT.DELETE ;
			L_TMP_DT := x1.AC_DT ;
		END IF ;

		MGPA_COST_IF.P_GET_DPT(x1.PURC_DPT_CD, NULL, x1.AC_DT, REC_DPT, L_PURC_DPT, C_ON) ;
		IF x1.PURC_DPT_CD IS NOT NULL AND L_PURC_DPT IS NULL THEN
			GOTO NEXT_LOOP_ERR ;
		END IF ;

		MGPA_COST_IF.P_GET_DPT(x1.AP_DPT_CD, NULL, x1.AC_DT, REC_DPT, L_AP_DPT, C_ON) ;
		IF x1.AP_DPT_CD IS NOT NULL AND L_AP_DPT IS NULL THEN
			GOTO NEXT_LOOP_ERR ;
		END IF ;

		MGPA_COST_IF.P_GET_DPT(x1.SLS_DPT_CD, NULL, x1.AC_DT, REC_DPT, L_SLS_DPT, C_ON) ;
		IF x1.SLS_DPT_CD IS NOT NULL AND L_SLS_DPT IS NULL THEN
			GOTO NEXT_LOOP_ERR ;
		END IF ;

		MGPA_COST_IF.P_GET_DPT(x1.AR_DPT_CD, NULL, x1.AC_DT, REC_DPT, L_AR_DPT, C_ON) ;
		IF x1.AR_DPT_CD IS NOT NULL AND L_AR_DPT IS NULL THEN
			GOTO NEXT_LOOP_ERR ;
		END IF ;

		MGPA_COST_IF.P_GET_DPT(x1.GI_DPT_CD, NULL, x1.AC_DT, REC_DPT, L_GI_DPT, C_ON) ;
		IF x1.GI_DPT_CD IS NOT NULL AND L_GI_DPT IS NULL THEN
			GOTO NEXT_LOOP_ERR ;
		END IF ;

		MGPA_COST_IF.P_GET_DPT(x1.GR_DPT_CD, NULL, x1.AC_DT, REC_DPT, L_GR_DPT, C_ON) ;
		IF x1.GR_DPT_CD IS NOT NULL AND L_GR_DPT IS NULL THEN
			GOTO NEXT_LOOP_ERR ;
		END IF ;

		MGPA_COST_IF.P_GET_DPT(x1.BD_DPT_CD, NULL, x1.AC_DT, REC_DPT, L_BD_DPT, C_ON) ;
		IF x1.BD_DPT_CD IS NOT NULL AND L_BD_DPT IS NULL THEN
			GOTO NEXT_LOOP_ERR ;
		END IF ;

		MGPA_COST_IF.P_GET_DPT(x1.SUB_DPT_CD1, NULL, x1.AC_DT, REC_DPT, L_SUB_DPT1, C_ON) ;
		IF x1.SUB_DPT_CD1 IS NOT NULL AND L_SUB_DPT1 IS NULL THEN
			GOTO NEXT_LOOP_ERR ;
		END IF ;

		MGPA_COST_IF.P_GET_DPT(x1.SUB_DPT_CD2, NULL, x1.AC_DT, REC_DPT, L_SUB_DPT2, C_ON) ;
		IF x1.SUB_DPT_CD2 IS NOT NULL AND L_SUB_DPT2 IS NULL THEN
			GOTO NEXT_LOOP_ERR ;
		END IF ;

		MGPA_COST_IF.P_GET_DPT(x1.SUB_DPT_CD3, NULL, x1.AC_DT, REC_DPT, L_SUB_DPT3, C_ON) ;
		IF x1.SUB_DPT_CD3 IS NOT NULL AND L_SUB_DPT3 IS NULL THEN
			GOTO NEXT_LOOP_ERR ;
		END IF ;

		MGPA_COST_IF.P_GET_DPT(x1.OUTSRC_MFG_LOC_DPT_CD, NULL, x1.AC_DT, REC_DPT, L_OUTSRC_MFG_LOC_DPT_CD, C_ON) ;
		IF x1.OUTSRC_MFG_LOC_DPT_CD IS NOT NULL AND L_OUTSRC_MFG_LOC_DPT_CD IS NULL THEN
			GOTO NEXT_LOOP_ERR ;
		END IF ;

		--数量の設定 値引・値増関連は数量を0とする
		IF x1.AC_SLIP_TYP IN (C_PURC_DSCNT, C_PURC_DSCNT_XPNS, C_PURC_XTRA, C_PURC_XTRA_XPNS, C_SLS_DSCNT, C_SLS_XTRA) THEN
			L_QTY := 0 ;
		ELSE
			L_QTY := x1.QTY ;
		END IF ;
		--数量の設定２ 値引品目かつ経費購買、経費返品、売上、売上返品は数量を0とする
		IF x1.DSCNT_ITM_FLG = C_ON AND x1.AC_SLIP_TYP IN (C_PURC_XPNS, C_PURC_RET_XPNS, C_SLS, C_SLS_RET) THEN
			L_QTY := 0 ;
		END IF ;

		--販売資産を生産資産として取込む
		IF L_ASST_FLG = C_ON THEN
			IF x1.ASST_TYP = C_ASST3 THEN
				L_ASST_TYP := C_ASST3 ;
			ELSE
				L_ASST_TYP := C_ASST2 ;
			END IF ;
		ELSE
			L_ASST_TYP := x1.ASST_TYP ;
		END IF ;

		-- 製造指図単位区分
		IF x1.MFG_INST_UNIT_TYP = C_OPER THEN
			x1.MFG_ACT_NO := C_NULL_VAL ;
		END IF ;

		-- 品目製造指図ＮＯ設定区分
		IF x1.ITM_MFG_INST_NO_SET_TYP = C_INST_LOC AND
			(x1.ITM_MFG_INST_NO IS NOT NULL
			OR x1.AC_SLIP_TYP IN (
				C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS,				--経費
				C_INSP_SMPL, C_DISP_SCRP, C_SO_STKTK, C_OTH_CCN_SO, C_IN_STKTK, C_OTH_CCN_GR	--入出庫
				) AND x1.PAR_ITM_CD IS NOT NULL AND NVL(x1.BD_LOC_CD, x1.LOC_CD) IS NOT NULL
			)
		THEN
			x1.ITM_MFG_INST_NO := C_STR_NO3 || SUBSTR(NVL(x1.OUTSRC_MFG_LOC_CD, x1.LOC_CD), 1, C_ITM_MFG_INST_NO_L-LENGTH(C_STR_NO3)) ;
			x1.ITM_INST_QTY := 0 ;
			x1.MFG_ST_QTY := 0 ;
		END IF ;

		-- 製造実績ＮＯ設定区分
		IF x1.MFG_ACT_NO_SET_TYP = C_MFG_NON THEN
			IF x1.ITM_MFG_INST_NO_SET_TYP = C_INST_LOC AND x1.ITM_MFG_INST_NO IS NOT NULL THEN
				x1.MFG_ACT_NO := NVL(SUBSTR(NVL(x1.OUTSRC_MFG_LOC_CD, x1.LOC_CD), C_ITM_MFG_INST_NO_L-LENGTH(C_STR_NO3)+1, C_MFG_ACT_NO_L), C_NULL_VAL) ;
			ELSE
				x1.MFG_ACT_NO := C_NULL_VAL ;
			END IF ;
			x1.ITM_INST_QTY := 0 ;
			x1.MFG_ST_QTY := 0 ;
		END IF ;

		-- 工程実績ＮＯ設定区分
		IF x1.OPER_ACT_NO_SET_TYP = C_OPER_NON THEN
			x1.OPER_ACT_NO := C_NULL_VAL ;
		ELSIF x1.OPER_ACT_NO_SET_TYP = C_OPER_OPER THEN
			x1.OPER_ACT_NO := x1.OPER_CD ;
		ELSIF L_OPER_SUM_FLG = C_ON THEN
			x1.OPER_ACT_NO := NVL(x1.OPER_CD, C_NULL_VAL) ;
		END IF ;

		--製造実績関連の取込
		IF x1.AC_SLIP_TYP = C_MFG
		OR x1.AC_SLIP_TYP IN (C_PURC, C_ARR_IN_TRANSIT, C_PURC_RET, C_PURC_DSCNT, C_PURC_XTRA) AND x1.ITM_MFG_INST_NO IS NOT NULL AND x1.ASSET_MNG_TYP = C_ASST_MNG1 --外注
		THEN
			IF L_NON_PROD_FLG = C_ON THEN
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.ASSET_MNG_TYP <> C_ASST_MNG1 THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0044', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2,
						MAPA_COMM.F_TO_DISP_ITM(x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, L_PARM), x1.AC_SLIP_TYP) ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.AC_SLIP_TYP = C_MFG THEN
				--製造は入庫部門を管理部門とする
				L_MDPT := L_GR_DPT ;
				L_WG := x1.GR_WG_CD ;
			ELSE
				--外注先場所を使用する
				x1.LOC_CD	:= x1.OUTSRC_MFG_LOC_CD ;
				x1.STR_LN_CD	:= C_NULL_VAL ;

				--外注先場所に対する部門を管理部門とする
				L_MDPT := L_OUTSRC_MFG_LOC_DPT_CD ;
				L_WG := x1.OUTSRC_MFG_LOC_WG_CD ;

				IF x1.AC_SLIP_TYP = C_PURC THEN
					IF x1.FIX_NO_TYP = C_FIX_NO_PURC_ACT_IO THEN
						--未着品の仕入は外注先場所に対する部門を設定する
						L_ODPT := L_OUTSRC_MFG_LOC_DPT_CD ;
						L_OWG := x1.OUTSRC_MFG_LOC_WG_CD ;

						--仕掛があるので在庫を作らない
						L_QTY := 0 ;
					ELSE
						--入庫場所に対する部門を設定する
						L_ODPT := L_GR_DPT ;
						L_OWG := x1.GR_WG_CD ;
					END IF ;
				ELSIF x1.AC_SLIP_TYP = C_ARR_IN_TRANSIT THEN
					--入庫場所に対する部門を設定する
					L_ODPT := L_GR_DPT ;
					L_OWG := x1.GR_WG_CD ;
				ELSIF x1.AC_SLIP_TYP = C_PURC_RET THEN
					--出庫場所に対する部門を設定する
					L_ODPT := L_GI_DPT ;
					L_OWG := x1.GI_WG_CD ;
				END IF ;
			END IF ;

			IF L_WG IS NULL THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0018', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
				L_DPT_ERR := C_ERR ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF L_MDPT IS NULL THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0017', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
				L_DPT_ERR := C_ERR ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.AC_SLIP_TYP IN (C_PURC_RET, C_PURC_DSCNT) THEN
				--符号を反転させる
				L_SIGN := -1 ;
			ELSE
				--符号はそのまま
				L_SIGN := 1 ;
			END IF ;

			IF L_MFG_ZERO_FLG = C_ON THEN
				GOTO MFG_ZERO ;
			END IF ;

			IF x1.AC_SLIP_TYP IN (C_PURC, C_PURC_RET, C_ARR_IN_TRANSIT)
			AND (L_FIX_DPT IS NULL AND L_MDPT <> L_ODPT OR L_WG <> L_OWG)
			AND L_QTY <> 0 THEN
				--外注で出庫ＷＧと入庫ＷＧもしくは出庫部門と入庫部門が異なるときは入出庫実績を作成する
				IF L_OWG IS NULL THEN
					FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0018', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
					L_DPT_ERR := C_ERR ;
					GOTO NEXT_LOOP ;
				END IF ;

				IF L_ODPT IS NULL THEN
					FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0017', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
					L_DPT_ERR := C_ERR ;
					GOTO NEXT_LOOP ;
				END IF ;

				W4 := W4 + 1 ;

				REC_w4(w4).DATA_LNO	:= MAPA_NUM.F_GET_SEQ(C_ACT_IO_IF_DATA_LNO) ;
				REC_w4(w4).CALC_CTG_CD	:= I_CALC_CTG_CD ;
				REC_w4(w4).WG_CD		:= L_WG ;
				REC_w4(w4).YM		:= x1.AC_YM ;
				REC_w4(w4).AC_DT		:= x1.AC_DT ;
				REC_w4(w4).MNG_DPT_CD	:= L_MDPT ;
				REC_w4(w4).ITM_CD	:= x1.ITM_CD ;
				REC_w4(w4).ITM_SUB1	:= x1.ITM_SUB1 ;
				REC_w4(w4).ITM_SUB2	:= x1.ITM_SUB2 ;
				REC_w4(w4).ITM_SUB3	:= x1.ITM_SUB3 ;

				IF L_LOT_USE_TYP <> C_PS_USE3 AND x1.LOT_ACT_TYP = C_ACT2 THEN
					REC_w4(w4).LOT_NO	:= x1.LOT_NO ;
				ELSE
					REC_w4(w4).LOT_NO	:= C_NULL_VAL ;
				END IF ;

				IF L_SUBLOT_USE_TYP <> C_PS_USE3 AND x1.SUBLOT_ACT_TYP = C_ACT2 THEN
					REC_w4(w4).SUBLOT_NO	:= x1.SUBLOT_NO ;
				ELSE
					REC_w4(w4).SUBLOT_NO	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO1_USE_TYP <> C_PS_USE3 AND x1.SNO1_ACT_TYP = C_ACT2 THEN
					REC_w4(w4).SNO1	:= x1.SNO1 ;
				ELSE
					REC_w4(w4).SNO1	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO2_USE_TYP <> C_PS_USE3 AND x1.SNO2_ACT_TYP = C_ACT2 THEN
					REC_w4(w4).SNO2	:= x1.SNO2 ;
				ELSE
					REC_w4(w4).SNO2	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO3_USE_TYP <> C_PS_USE3 AND x1.SNO3_ACT_TYP = C_ACT2 THEN
					REC_w4(w4).SNO3	:= x1.SNO3 ;
				ELSE
					REC_w4(w4).SNO3	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO4_USE_TYP <> C_PS_USE3 AND x1.SNO4_ACT_TYP = C_ACT2 THEN
					REC_w4(w4).SNO4	:= x1.SNO4 ;
				ELSE
					REC_w4(w4).SNO4	:= C_NULL_VAL ;
				END IF ;

				REC_w4(w4).AC_SLIP_TYP	:= C_DPT_XFR_SO ;
				REC_w4(w4).AC_RSN_CD	:= x1.AC_RSN_CD ;
				REC_w4(w4).OTHER_WG_CD	:= L_OWG ;
				IF REC_w4(w4).WG_CD = REC_w4(w4).OTHER_WG_CD THEN
					REC_w4(w4).OTHER_WG_CD := NULL ;
				END IF ;
				REC_w4(w4).OTHER_DPT_CD	:= L_ODPT ;
				REC_w4(w4).BP_CD	:= NULL ;
				REC_w4(w4).STK_BP_CD	:= NULL ;
				REC_w4(w4).ASST_TYP	:= C_ASST2 ;
				REC_w4(w4).QTY		:= L_QTY * L_SIGN ;
				REC_w4(w4).AMT		:= NULL ;
				REC_w4(w4).TRD_CUR_CD	:= NULL ;
				REC_w4(w4).TRD_CUR_AMT	:= NULL ;
				REC_w4(w4).XRATE	:= NULL ;
				REC_w4(w4).TRD_GRP	:= C_STR_TRD3 || TO_CHAR(REC_w4(w4).DATA_LNO) ;
				REC_w4(w4).TRD_RATIO	:= NULL ;
				REC_w4(w4).ALC_AC_CD	:= NULL ;
				REC_w4(w4).ALC_AMT_FLG	:= C_OFF ;
				REC_w4(w4).ALC_WG_CD	:= NULL ;
				REC_w4(w4).ALC_DPT_CD	:= NULL ;
				REC_w4(w4).ALC_LOC_CD	:= NULL ;
				REC_w4(w4).ALC_OPER_CD	:= NULL ;
				REC_w4(w4).ALC_BP_CD	:= NULL ;
				REC_w4(w4).ALC_CTG_CD	:= NULL ;
				REC_w4(w4).ALC_ITM_CD	:= NULL ;
				REC_w4(w4).ALC_ITM_SUB1	:= NULL ;
				REC_w4(w4).ALC_ITM_SUB2	:= NULL ;
				REC_w4(w4).ALC_ITM_SUB3	:= NULL ;
				REC_w4(w4).ALC_LOT_NO	:= NULL ;
				REC_w4(w4).ALC_SUBLOT_NO	:= NULL ;
				REC_w4(w4).ALC_SNO1	:= NULL ;
				REC_w4(w4).ALC_SNO2	:= NULL ;
				REC_w4(w4).ALC_SNO3	:= NULL ;
				REC_w4(w4).ALC_SNO4	:= NULL ;
				REC_w4(w4).ALC_ITM_MFG_INST_NO	:= NULL ;
				REC_w4(w4).REC_EVAL_TYP	:= NULL ;
				REC_w4(w4).NO_PLN_FLG	:= C_OFF ;
				REC_w4(w4).NO_ITM_INFO_FLG	:= C_OFF ;
				REC_w4(w4).ZERO_EFFECT_FLG := C_OFF ;
				REC_w4(w4).SLIP_NO	:= x1.SLIP_NO ;
				REC_w4(w4).SLIP_SEQ_NO	:= x1.SLIP_SEQ_NO ;
				REC_w4(w4).RMRKS	:= x1.TRD_D_RMRKS ;
				REC_w4(w4).SUB_CHAR1	:= NULL ;
				REC_w4(w4).SUB_CHAR2	:= NULL ;
				REC_w4(w4).SUB_CHAR3	:= NULL ;
			END IF ;

			w1 := w1 + 1 ;

			REC_w1(w1).DATA_LNO	:= MAPA_NUM.F_GET_SEQ(C_ACT_MFG_IF_DATA_LNO) ;
			REC_w1(w1).CALC_CTG_CD	:= I_CALC_CTG_CD ;
			REC_w1(w1).WG_CD	:= L_WG ;
			REC_w1(w1).YM		:= x1.AC_YM ;
			REC_w1(w1).AC_DT		:= x1.AC_DT ;
			REC_w1(w1).ITM_CD	:= x1.ITM_CD ;
			REC_w1(w1).ITM_SUB1	:= x1.ITM_SUB1 ;
			REC_w1(w1).ITM_SUB2	:= x1.ITM_SUB2 ;
			REC_w1(w1).ITM_SUB3	:= x1.ITM_SUB3 ;
			REC_w1(w1).ITM_MFG_INST_NO := x1.ITM_MFG_INST_NO ;
			REC_w1(w1).MFG_ACT_NO := NVL(x1.MFG_ACT_NO, C_NULL_VAL) ;
			REC_w1(w1).OPER_ACT_NO	:= NVL(x1.OPER_ACT_NO, C_NULL_VAL) ;

			IF L_LOT_USE_TYP <> C_PS_USE3 AND x1.LOT_ACT_TYP <> C_ACT1 THEN
				REC_w1(w1).LOT_NO	:= x1.LOT_NO ;
			ELSE
				REC_w1(w1).LOT_NO	:= C_NULL_VAL ;
			END IF ;

			IF L_SUBLOT_USE_TYP <> C_PS_USE3 AND x1.SUBLOT_ACT_TYP <> C_ACT1 THEN
				REC_w1(w1).SUBLOT_NO	:= x1.SUBLOT_NO ;
			ELSE
				REC_w1(w1).SUBLOT_NO	:= C_NULL_VAL ;
			END IF ;

			IF L_SNO1_USE_TYP <> C_PS_USE3 AND x1.SNO1_ACT_TYP <> C_ACT1 THEN
				REC_w1(w1).SNO1	:= x1.SNO1 ;
			ELSE
				REC_w1(w1).SNO1	:= C_NULL_VAL ;
			END IF ;

			IF L_SNO2_USE_TYP <> C_PS_USE3 AND x1.SNO2_ACT_TYP <> C_ACT1 THEN
				REC_w1(w1).SNO2	:= x1.SNO2 ;
			ELSE
				REC_w1(w1).SNO2	:= C_NULL_VAL ;
			END IF ;

			IF L_SNO3_USE_TYP <> C_PS_USE3 AND x1.SNO3_ACT_TYP <> C_ACT1 THEN
				REC_w1(w1).SNO3	:= x1.SNO3 ;
			ELSE
				REC_w1(w1).SNO3	:= C_NULL_VAL ;
			END IF ;

			IF L_SNO4_USE_TYP <> C_PS_USE3 AND x1.SNO4_ACT_TYP <> C_ACT1 THEN
				REC_w1(w1).SNO4	:= x1.SNO4 ;
			ELSE
				REC_w1(w1).SNO4	:= C_NULL_VAL ;
			END IF ;

			REC_w1(w1).LOC_CD	:= x1.LOC_CD ;
			REC_w1(w1).STR_LN_CD	:= NVL(x1.STR_LN_CD, C_NULL_VAL) ;
			REC_w1(w1).AC_SLIP_TYP	:= x1.AC_SLIP_TYP ;
			REC_w1(w1).AC_RSN_CD	:= x1.AC_RSN_CD ;
			REC_w1(w1).QTY		:= L_QTY * L_SIGN ;
			IF x1.BP_CD IS NOT NULL THEN
				REC_w1(w1).AMT		:= x1.AMT * L_SIGN ;
				REC_w1(w1).TRD_CUR_CD	:= x1.TRD_CUR_CD ;
				REC_w1(w1).TRD_CUR_AMT	:= x1.TRD_CUR_AMT * L_SIGN ;
				REC_w1(w1).XRATE	:= x1.XRATE ;
			ELSE
				REC_w1(w1).AMT		:= NULL ;
				REC_w1(w1).TRD_CUR_CD	:= NULL ;
				REC_w1(w1).TRD_CUR_AMT	:= NULL ;
				REC_w1(w1).XRATE	:= NULL ;
			END IF ;
			REC_w1(w1).MFG_PER	:= x1.YIELD_RATE ;
			REC_w1(w1).MFG_COST_RATIO := NULL ;
			REC_w1(w1).EXPNS_CD	:= NULL ;
			REC_w1(w1).ALC_VAL1	:= NULL ;
			REC_w1(w1).ALC_VAL2	:= NULL ;
			REC_w1(w1).ALC_VAL3	:= NULL ;
			REC_w1(w1).ALC_VAL4	:= NULL ;
			REC_w1(w1).ALC_VAL5	:= NULL ;
			REC_w1(w1).NO_PLN_FLG	:= C_OFF ;
			REC_w1(w1).NO_ITM_INFO_FLG	:= C_OFF ;
			REC_w1(w1).SLIP_NO	:= x1.SLIP_NO ;
			REC_w1(w1).SLIP_SEQ_NO	:= x1.SLIP_SEQ_NO ;
			REC_w1(w1).RMRKS	:= x1.TRD_D_RMRKS ;
			REC_w1(w1).SUB_CHAR1	:= NULL ;
			REC_w1(w1).SUB_CHAR2	:= NULL ;
			REC_w1(w1).SUB_CHAR3	:= NULL ;

			--未着品の入荷では仕入に対する赤伝と入荷の黒伝を作成する
			IF x1.AC_SLIP_TYP = C_ARR_IN_TRANSIT THEN
				w1 := w1 + 1 ;
				REC_w1(w1)	:= REC_w1(w1-1) ;

				IF L_LOT_USE_TYP <> C_PS_USE3 AND x1.LOT_ACT_TYP <> C_ACT1 THEN
					REC_w1(w1-1).LOT_NO := C_UNFIXED ;
				ELSE
					REC_w1(w1-1).LOT_NO := C_NULL_VAL ;
				END IF ;

				IF L_SUBLOT_USE_TYP <> C_PS_USE3 AND x1.SUBLOT_ACT_TYP <> C_ACT1 THEN
					REC_w1(w1-1).SUBLOT_NO := C_UNFIXED ;
				ELSE
					REC_w1(w1-1).SUBLOT_NO := C_NULL_VAL ;
				END IF ;

				REC_w1(w1-1).AC_SLIP_TYP	:= C_PURC ;
				REC_w1(w1-1).QTY	:= 0 ;
				REC_w1(w1-1).AMT	:= REC_w1(w1-1).AMT * -1 ;
				REC_w1(w1-1).TRD_CUR_AMT	:= REC_w1(w1-1).TRD_CUR_AMT * -1 ;

				REC_w1(w1).DATA_LNO	:= MAPA_NUM.F_GET_SEQ(C_ACT_MFG_IF_DATA_LNO) ;

				--品目製造指図、指図工程は作成しない
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.AC_SLIP_TYP IN (C_PURC_RET, C_PURC_DSCNT, C_PURC_XTRA) THEN
				--仕入返品・値増・値引は品目製造指図及び指図工程情報を作成しない
				GOTO NEXT_LOOP ;
			END IF ;

			<<MFG_ZERO>>

			IF x1.RCPT_IV_NO IS NULL OR L_TGT_IV_FLG = C_ON OR x1.MFG_ACT_NO_SET_TYP = C_MFG_NON THEN
				IF F_CHK_ITM(x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_MFG_INST_NO, x1.MFG_ACT_NO) = C_ERR THEN
					GOTO OPER_MFG ;
				END IF ;
			ELSE
				L_CNT := F_CHK_IV(x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_MFG_INST_NO, x1.MFG_ACT_NO, x1.RCPT_IV_NO) ;

				IF L_CNT = C_ERR THEN
					GOTO OPER_MFG ;
				ELSIF L_CNT = -1 THEN
					REC_w1(w1).MFG_ACT_NO := C_STR_NO || LPAD(MAPA_NUM.F_GET_SEQ(C_ITM_MFG_INST), C_ITM_MFG_INST_LENGTH, '0') ;
					x1.MFG_ACT_NO := REC_w1(w1).MFG_ACT_NO ;
					x1.MFG_ST_QTY := 0 ;
					x1.ITM_INST_QTY := 0 ;
				END IF ;
			END IF ;

			w6 := w6 + 1 ;

			REC_w6(w6).CALC_CTG_CD	:= I_CALC_CTG_CD ;
			REC_w6(w6).ITM_CD	:= x1.ITM_CD ;
			REC_w6(w6).ITM_SUB1	:= x1.ITM_SUB1 ;
			REC_w6(w6).ITM_SUB2	:= x1.ITM_SUB2 ;
			REC_w6(w6).ITM_SUB3	:= x1.ITM_SUB3 ;
			REC_w6(w6).ITM_MFG_INST_NO := x1.ITM_MFG_INST_NO ;
			REC_w6(w6).MFG_ACT_NO := x1.MFG_ACT_NO ;
			REC_w6(w6).WG_CD	:= L_WG ;
			REC_w6(w6).MNG_DPT_CD	:= NVL(L_FIX_DPT, L_MDPT) ;

			IF x1.ITM_MFG_INST_NO_SET_TYP = C_INST_LOC THEN
				REC_w6(w6).LOT_NO	:= C_NULL_VAL ;
				REC_w6(w6).SUBLOT_NO	:= C_NULL_VAL ;
				REC_w6(w6).SNO1	:= C_NULL_VAL ;
				REC_w6(w6).SNO2	:= C_NULL_VAL ;
				REC_w6(w6).SNO3	:= C_NULL_VAL ;
				REC_w6(w6).SNO4	:= C_NULL_VAL ;
			ELSE
				IF L_LOT_USE_TYP <> C_PS_USE3 AND x1.LOT_ACT_TYP <> C_ACT1 THEN
					REC_w6(w6).LOT_NO	:= NVL(x1.PAR_LOT_NO, C_NULL_VAL) ;
				ELSE
					REC_w6(w6).LOT_NO	:= C_NULL_VAL ;
				END IF ;

				IF L_SUBLOT_USE_TYP <> C_PS_USE3 AND x1.SUBLOT_ACT_TYP <> C_ACT1 THEN
					REC_w6(w6).SUBLOT_NO	:= NVL(x1.PAR_SUBLOT_NO, C_NULL_VAL) ;
				ELSE
					REC_w6(w6).SUBLOT_NO	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO1_USE_TYP <> C_PS_USE3 AND x1.SNO1_ACT_TYP <> C_ACT1 THEN
					REC_w6(w6).SNO1	:= x1.SNO1 ;
				ELSE
					REC_w6(w6).SNO1	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO2_USE_TYP <> C_PS_USE3 AND x1.SNO2_ACT_TYP <> C_ACT1 THEN
					REC_w6(w6).SNO2	:= x1.SNO2 ;
				ELSE
					REC_w6(w6).SNO2	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO3_USE_TYP <> C_PS_USE3 AND x1.SNO3_ACT_TYP <> C_ACT1 THEN
					REC_w6(w6).SNO3	:= x1.SNO3 ;
				ELSE
					REC_w6(w6).SNO3	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO4_USE_TYP <> C_PS_USE3 AND x1.SNO4_ACT_TYP <> C_ACT1 THEN
					REC_w6(w6).SNO4	:= x1.SNO4 ;
				ELSE
					REC_w6(w6).SNO4	:= C_NULL_VAL ;
				END IF ;
			END IF ;

			REC_w6(w6).SPPL_CD	:= x1.BP_CD ;
			REC_w6(w6).PO_NO	:= x1.PO_NO ;
			REC_w6(w6).SLO_NO	:= x1.SLO_NO ;
			REC_w6(w6).IV_NO	:= x1.RCPT_IV_NO ;
			REC_w6(w6).ASST_TYP	:= L_ASST_TYP ;
			IF x1.MFG_INST_UNIT_TYP = C_ITM THEN
				REC_w6(w6).QTY		:= NVL(x1.MFG_ST_QTY, 0) ;
			ELSE
				REC_w6(w6).QTY		:= NVL(x1.ITM_INST_QTY, 0) ;
			END IF ;
			REC_w6(w6).SCHD_ST_DT	:= NULL ;
			REC_w6(w6).SCHD_END_DT	:= NULL ;
			REC_w6(w6).ACT_ST_DT	:= NULL ;
			REC_w6(w6).ACT_END_DT	:= NULL ;
			REC_w6(w6).RMRKS	:= NULL ;--x1.TRD_RMRKS ;
			REC_w6(w6).SUB_CHAR1	:= NULL ;
			REC_w6(w6).SUB_CHAR2	:= NULL ;
			REC_w6(w6).SUB_CHAR3	:= NULL ;
			P_COL_PROC_ITM() ;

			IF x1.RCPT_IV_NO IS NOT NULL AND NVL(x1.MFG_ACT_NO_SET_TYP, C_NULL_VAL) <> C_MFG_NON THEN
				u6 := u6 + 1 ;
				UPD_w6(u6) := REC_w6(w6) ;

				REC_w6.DELETE(w6) ;
				w6 := w6 - 1 ;
			END IF ;

			IF L_MFG_ZERO_FLG = C_ON THEN
				GOTO NEXT_LOOP ;
			END IF ;

			<<OPER_MFG>>
				NULL ;

			IF x1.OPER_CD IS NULL OR x1.OPER_CD = C_NULL_VAL OR F_CHK_OPER(x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.ITM_MFG_INST_NO, x1.MFG_ACT_NO, x1.OPER_ACT_NO) = C_ERR THEN
				GOTO NEXT_LOOP ;
			END IF ;

			w7 := w7 + 1 ;

			REC_w7(w7).CALC_CTG_CD	:= I_CALC_CTG_CD ;
			REC_w7(w7).ITM_CD	:= x1.ITM_CD ;
			REC_w7(w7).ITM_SUB1	:= x1.ITM_SUB1 ;
			REC_w7(w7).ITM_SUB2	:= x1.ITM_SUB2 ;
			REC_w7(w7).ITM_SUB3	:= x1.ITM_SUB3 ;
			REC_w7(w7).ITM_MFG_INST_NO := x1.ITM_MFG_INST_NO ;
			REC_w7(w7).MFG_ACT_NO := x1.MFG_ACT_NO ;
			REC_w7(w7).OPER_ACT_NO	:= x1.OPER_ACT_NO ;
			REC_w7(w7).WG_CD	:= L_WG ;
			REC_w7(w7).MNG_DPT_CD	:= NVL(L_FIX_DPT, L_MDPT) ;
			REC_w7(w7).OPER_CD	:= x1.OPER_CD ;
			REC_w7(w7).OPER_SEQ	:= 1 ;
			REC_w7(w7).DISP_SEQ	:= NVL(x1.DISP_SEQ, 1) ;
			REC_w7(w7).QTY		:= NULL ;
			REC_w7(w7).SCHD_ST_DT	:= NULL ;
			REC_w7(w7).SCHD_END_DT	:= NULL ;
			REC_w7(w7).ACT_ST_DT	:= NULL ;
			REC_w7(w7).ACT_END_DT	:= NULL ;
			REC_w7(w7).RMRKS	:= NULL ;--x1.TRD_D_RMRKS ;
			REC_w7(w7).SUB_CHAR1	:= NULL ;
			REC_w7(w7).SUB_CHAR2	:= NULL ;
			REC_w7(w7).SUB_CHAR3	:= NULL ;

			GOTO NEXT_LOOP ;
		END IF ;

		--購買実績関連の取込
		IF x1.AC_SLIP_TYP IN (C_PURC, C_ARR_IN_TRANSIT, C_PURC_RET, C_PURC_DSCNT, C_PURC_XTRA)
		OR x1.AC_SLIP_TYP IN (C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS) AND (x1.PAR_ITM_CD IS NULL OR NVL(x1.BD_LOC_CD, x1.LOC_CD) IS NULL)
		THEN
			IF L_NON_PROD_FLG = C_OFF AND x1.ASST_TYP = C_ASST2
			OR L_NON_SLS_FLG = C_OFF AND x1.ASST_TYP = C_ASST1
			THEN
				NULL ;
			ELSE
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.AC_SLIP_TYP IN (C_PURC_RET, C_PURC_DSCNT, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS) THEN
				--値引・返品関連
				IF x1.AC_SLIP_TYP = C_PURC_RET THEN
					--仕入返品は出庫部門を管理部門とする
					L_MDPT := L_GI_DPT ;
					L_WG := x1.GI_WG_CD ;
				ELSE
					--経費返品・値引は負担部門を管理部門とする
					L_MDPT := L_BD_DPT ;
					L_WG := x1.BD_WG_CD ;
				END IF ;

				--符号を反転させる
				L_SIGN := -1 ;
			ELSE
				IF x1.AC_SLIP_TYP IN (C_PURC, C_ARR_IN_TRANSIT) THEN
					--仕入は入庫部門を管理部門とする
					L_MDPT := L_GR_DPT ;
					L_WG := x1.GR_WG_CD ;
				ELSE
					--経費購買・値増は負担部門を管理部門とする
					L_MDPT := L_BD_DPT ;
					L_WG := x1.BD_WG_CD ;
				END IF ;

				--符号はそのまま
				L_SIGN := 1 ;
			END IF ;

			IF L_WG IS NULL THEN
				IF x1.AC_SLIP_TYP = C_PURC_XPNS THEN
					L_WG := x1.GR_WG_CD ;
				ELSIF x1.AC_SLIP_TYP = C_PURC_RET_XPNS THEN
					L_WG := x1.GI_WG_CD ;
				ELSIF x1.AC_SLIP_TYP IN (C_PURC_DSCNT, C_PURC_DSCNT_XPNS, C_PURC_XTRA, C_PURC_XTRA_XPNS) THEN
					L_WG := x1.PURC_WG_CD ;
				END IF ;
			END IF ;

			-- 値引品目かつ経費購買、経費返品は符号を反転する
			IF x1.DSCNT_ITM_FLG = C_ON AND x1.AC_SLIP_TYP IN (C_PURC_XPNS, C_PURC_RET_XPNS) THEN
				L_SIGN := - L_SIGN ;
			END IF ;

			--配賦部門コードの設定
			L_ODPT := NVL(L_BD_DPT, NVL(L_PURC_DPT, L_AP_DPT)) ;

			IF L_WG IS NULL THEN
				IF x1.AC_SLIP_TYP IN (C_PURC_DSCNT, C_PURC_XTRA, C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS) THEN
					FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0020', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
				ELSE
					FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0018', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
					L_DPT_ERR := C_ERR ;
				END IF ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF L_MDPT IS NULL OR L_ODPT IS NULL THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0017', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
				L_DPT_ERR := C_ERR ;
				GOTO NEXT_LOOP ;
			END IF ;

			w2 := w2 + 1 ;

			REC_w2(w2).DATA_LNO	:= MAPA_NUM.F_GET_SEQ(C_ACT_PURC_IF_DATA_LNO) ;
			REC_w2(w2).CALC_CTG_CD	:= I_CALC_CTG_CD ;
			REC_w2(w2).WG_CD	:= L_WG ;
			REC_w2(w2).YM		:= x1.AC_YM ;
			REC_w2(w2).AC_DT		:= x1.AC_DT ;
			REC_w2(w2).MNG_DPT_CD	:= NVL(L_FIX_DPT, L_MDPT) ;
			REC_w2(w2).ITM_CD	:= x1.ITM_CD ;
			REC_w2(w2).ITM_SUB1	:= x1.ITM_SUB1 ;
			REC_w2(w2).ITM_SUB2	:= x1.ITM_SUB2 ;
			REC_w2(w2).ITM_SUB3	:= x1.ITM_SUB3 ;

			IF x1.LOT_ACT_TYP <> C_ACT1
			AND (L_LOT_USE_TYP = C_PS_USE2 AND x1.ASST_TYP = C_ASST2
			  OR L_LOT_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_LOT_USE_TYP = C_PS_USE1
			  )
			THEN
				IF x1.AC_SLIP_TYP IN (C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS) THEN
					REC_w2(w2).LOT_NO	:= NVL(x1.PAR_LOT_NO, x1.LOT_NO) ;
				ELSE
					REC_w2(w2).LOT_NO	:= x1.LOT_NO ;
				END IF;
			ELSE
				REC_w2(w2).LOT_NO	:= C_NULL_VAL ;
			END IF ;

			IF x1.SUBLOT_ACT_TYP <> C_ACT1
			AND (L_SUBLOT_USE_TYP = C_PS_USE2 AND x1.ASST_TYP = C_ASST2
			  OR L_SUBLOT_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SUBLOT_USE_TYP = C_PS_USE1
			  )
			THEN
				IF x1.AC_SLIP_TYP IN (C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS) THEN
					REC_w2(w2).SUBLOT_NO	:= NVL(x1.PAR_SUBLOT_NO, x1.SUBLOT_NO) ;
				ELSE
					REC_w2(w2).SUBLOT_NO	:= x1.SUBLOT_NO ;
				END IF;
			ELSE
				REC_w2(w2).SUBLOT_NO	:= C_NULL_VAL ;
			END IF ;

			IF x1.SNO1_ACT_TYP <> C_ACT1
			AND (L_SNO1_USE_TYP = C_PS_USE2 AND x1.ASST_TYP = C_ASST2
			  OR L_SNO1_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SNO1_USE_TYP = C_PS_USE1
			  )
			THEN
				IF x1.AC_SLIP_TYP IN (C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS) THEN
					REC_w2(w2).SNO1	:= NVL(x1.PAR_SNO1, x1.SNO1) ;
				ELSE
					REC_w2(w2).SNO1	:= x1.SNO1 ;
				END IF;
			ELSE
				REC_w2(w2).SNO1	:= C_NULL_VAL ;
			END IF ;

			IF x1.SNO2_ACT_TYP <> C_ACT1
			AND (L_SNO2_USE_TYP = C_PS_USE2 AND x1.ASST_TYP = C_ASST2
			  OR L_SNO2_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SNO2_USE_TYP = C_PS_USE1
			  )
			THEN
				IF x1.AC_SLIP_TYP IN (C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS) THEN
					REC_w2(w2).SNO2	:= NVL(x1.PAR_SNO2, x1.SNO2) ;
				ELSE
					REC_w2(w2).SNO2	:= x1.SNO2 ;
				END IF;
			ELSE
				REC_w2(w2).SNO2	:= C_NULL_VAL ;
			END IF ;

			IF x1.SNO3_ACT_TYP <> C_ACT1
			AND (L_SNO3_USE_TYP = C_PS_USE2 AND x1.ASST_TYP = C_ASST2
			  OR L_SNO3_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SNO3_USE_TYP = C_PS_USE1
			  )
			THEN
				IF x1.AC_SLIP_TYP IN (C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS) THEN
					REC_w2(w2).SNO3	:= NVL(x1.PAR_SNO3, x1.SNO3) ;
				ELSE
					REC_w2(w2).SNO3	:= x1.SNO3 ;
				END IF;
			ELSE
				REC_w2(w2).SNO3	:= C_NULL_VAL ;
			END IF ;

			IF x1.SNO4_ACT_TYP <> C_ACT1
			AND (L_SNO4_USE_TYP = C_PS_USE2 AND x1.ASST_TYP = C_ASST2
			  OR L_SNO4_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SNO4_USE_TYP = C_PS_USE1
			  )
			THEN
				IF x1.AC_SLIP_TYP IN (C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS) THEN
					REC_w2(w2).SNO4	:= NVL(x1.PAR_SNO4, x1.SNO4) ;
				ELSE
					REC_w2(w2).SNO4	:= x1.SNO4 ;
				END IF;
			ELSE
				REC_w2(w2).SNO4	:= C_NULL_VAL ;
			END IF ;

			IF x1.AC_SLIP_TYP IN (C_PURC, C_ARR_IN_TRANSIT, C_PURC_RET, C_PURC_DSCNT, C_PURC_XTRA) THEN
				REC_w2(w2).SPPL_CD	:= x1.BP_CD ;
				REC_w2(w2).PO_NO	:= x1.PO_NO ;
				REC_w2(w2).SLO_NO	:= x1.SLO_NO ;
				REC_w2(w2).IV_NO	:= x1.RCPT_IV_NO ;
				REC_w2(w2).ALC_LOC_CD	:= NULL ;
				REC_w2(w2).ALC_OPER_CD	:= NULL ;
				REC_w2(w2).ALC_CTG_CD	:= NULL ;
			ELSE
				REC_w2(w2).SPPL_CD	:= NVL(x1.BD_BP_CD, x1.BP_CD) ;
				REC_w2(w2).PO_NO	:= NVL(x1.BD_PO_NO, x1.PO_NO) ;
				REC_w2(w2).SLO_NO	:= NVL(x1.BD_SLO_NO, x1.SLO_NO) ;
				REC_w2(w2).IV_NO	:= NVL(x1.BD_IV_NO, x1.RCPT_IV_NO) ;
				REC_w2(w2).ALC_LOC_CD	:= x1.BD_LOC_CD ;
				REC_w2(w2).ALC_OPER_CD	:= x1.BD_OPER_CD ;
				REC_w2(w2).ALC_CTG_CD	:= x1.BD_CTG_CD ;
			END IF ;
			REC_w2(w2).ALC_DPT_CD	:= L_ODPT ;
			REC_w2(w2).AC_SLIP_TYP	:= x1.AC_SLIP_TYP ;
			REC_w2(w2).AC_RSN_CD	:= x1.AC_RSN_CD ;
			REC_w2(w2).ASST_TYP	:= L_ASST_TYP ;
			REC_w2(w2).QTY		:= L_QTY * L_SIGN ;
			REC_w2(w2).AMT		:= x1.AMT * L_SIGN ;
			REC_w2(w2).TRD_CUR_CD	:= x1.TRD_CUR_CD ;
			REC_w2(w2).TRD_CUR_AMT	:= x1.TRD_CUR_AMT * L_SIGN ;
			REC_w2(w2).XRATE	:= x1.XRATE ;
			REC_w2(w2).EXPNS_CD	:= NULL ;
			REC_w2(w2).ALC_VAL1	:= NULL ;
			REC_w2(w2).ALC_VAL2	:= NULL ;
			REC_w2(w2).ALC_VAL3	:= NULL ;
			REC_w2(w2).ALC_VAL4	:= NULL ;
			REC_w2(w2).ALC_VAL5	:= NULL ;
			REC_w2(w2).NO_PLN_FLG	:= C_OFF ;
			REC_w2(w2).NO_ITM_INFO_FLG	:= C_OFF ;
			REC_w2(w2).NO_EVAL_FLG	:= C_OFF ;
			REC_w2(w2).SLIP_NO	:= x1.SLIP_NO ;
			REC_w2(w2).SLIP_SEQ_NO	:= x1.SLIP_SEQ_NO ;
			REC_w2(w2).RMRKS	:= x1.TRD_D_RMRKS ;
			REC_w2(w2).SUB_CHAR1	:= NULL ;
			REC_w2(w2).SUB_CHAR2	:= NULL ;
			REC_w2(w2).SUB_CHAR3	:= NULL ;

			P_COL_PROC_PURC() ;

			--未着品の入荷では仕入に対する赤伝と入荷の黒伝を作成する
			IF x1.AC_SLIP_TYP = C_ARR_IN_TRANSIT AND L_CO_PARM.NON_TRANSIT_FLG = C_OFF THEN
				w2 := w2 + 1 ;
				REC_w2(w2)	:= REC_w2(w2-1) ;

				IF x1.LOT_ACT_TYP <> C_ACT1
				AND (L_LOT_USE_TYP = C_PS_USE2 AND x1.ASST_TYP = C_ASST2
				  OR L_LOT_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
				  OR L_LOT_USE_TYP = C_PS_USE1
				  )
				THEN
					REC_w2(w2-1).LOT_NO := C_UNFIXED ;
				ELSE
					REC_w2(w2-1).LOT_NO := C_NULL_VAL ;
				END IF ;

				IF x1.SUBLOT_ACT_TYP <> C_ACT1
				AND (L_SUBLOT_USE_TYP = C_PS_USE2 AND x1.ASST_TYP = C_ASST2
				  OR L_SUBLOT_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
				  OR L_SUBLOT_USE_TYP = C_PS_USE1
				  )
				THEN
					REC_w2(w2-1).SUBLOT_NO := C_UNFIXED ;
				ELSE
					REC_w2(w2-1).SUBLOT_NO := C_NULL_VAL ;
				END IF ;

				REC_w2(w2-1).AC_SLIP_TYP	:= C_PURC ;
				REC_w2(w2-1).QTY	:= REC_w2(w2-1).QTY * -1 ;
				REC_w2(w2-1).AMT	:= REC_w2(w2-1).AMT * -1 ;
				REC_w2(w2-1).TRD_CUR_AMT	:= REC_w2(w2-1).TRD_CUR_AMT * -1 ;

				REC_w2(w2).DATA_LNO	:= MAPA_NUM.F_GET_SEQ(C_ACT_PURC_IF_DATA_LNO) ;
			END IF ;

			GOTO NEXT_LOOP ;
		END IF ;

		--投入実績関連の取込
		IF x1.AC_SLIP_TYP IN (C_INPUT, C_IN_ONR, C_IN_SS, C_BYPROD)
		OR x1.AC_SLIP_TYP IN (
			C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS,				--経費
			C_INSP_SMPL, C_DISP_SCRP, C_SO_STKTK, C_OTH_CCN_SO, C_IN_STKTK, C_OTH_CCN_GR	--入出庫
			) AND x1.PAR_ITM_CD IS NOT NULL AND NVL(x1.BD_LOC_CD, x1.LOC_CD) IS NOT NULL
		THEN
			IF L_NON_PROD_FLG = C_ON THEN
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.PAR_ASSET_MNG_TYP <> C_ASST_MNG1 THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0045', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2,
						MAPA_COMM.F_TO_DISP_ITM(x1.PAR_ITM_CD, x1.PAR_ITM_SUB1, x1.PAR_ITM_SUB2, x1.PAR_ITM_SUB3, L_PARM), x1.AC_SLIP_TYP) ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.AC_SLIP_TYP IN (C_INSP_SMPL, C_DISP_SCRP, C_SO_STKTK, C_OTH_CCN_SO, C_IN_STKTK, C_OTH_CCN_GR)	--入出庫
			AND x1.ASSET_MNG_TYP <> C_ASST_MNG1 THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0044', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2,
						MAPA_COMM.F_TO_DISP_ITM(x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, L_PARM), x1.AC_SLIP_TYP) ;
				GOTO NEXT_LOOP ;
			END IF ;

			L_ITM_MFG_INST_NO := x1.ITM_MFG_INST_NO ;
			L_MFG_ACT_NO := NVL(x1.MFG_ACT_NO, C_NULL_VAL) ;
			L_OPER_ACT_NO := NVL(x1.OPER_ACT_NO, C_NULL_VAL) ;

			IF x1.AC_SLIP_TYP IN (
				C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS,				--経費
				C_INSP_SMPL, C_DISP_SCRP, C_SO_STKTK, C_OTH_CCN_SO, C_IN_STKTK, C_OTH_CCN_GR	--入出庫
			) THEN
				IF x1.AC_SLIP_TYP IN (C_PURC_XPNS, C_PURC_XTRA_XPNS) THEN
					--経費購買は負担部門を管理部門（投入）とする
					L_MDPT	:= L_BD_DPT ;
					L_WG	:= x1.BD_WG_CD ;
					L_OWG	:= x1.BD_WG_CD ;

					L_SIGN := 1 ;
				ELSIF x1.AC_SLIP_TYP IN (C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS) THEN
					--経費返品は負担部門を管理部門（投入）とする
					L_MDPT	:= L_BD_DPT ;
					L_WG	:= x1.BD_WG_CD ;
					L_OWG	:= x1.BD_WG_CD ;

					L_SIGN := -1 ;
				ELSIF x1.AC_SLIP_TYP IN (C_INSP_SMPL, C_DISP_SCRP, C_SO_STKTK, C_OTH_CCN_SO) THEN
					--出庫は出庫部門を管理部門（投入）とする
					L_MDPT	:= L_GI_DPT ;
					L_WG	:= x1.GI_WG_CD ;
					L_OWG	:= NVL(x1.BD_WG_CD, x1.GI_WG_CD) ;

					L_SIGN := 1 ;
				ELSIF x1.AC_SLIP_TYP IN (C_IN_STKTK, C_OTH_CCN_GR) THEN
					--入庫は入庫部門を管理部門（投入）とする
					L_MDPT	:= L_GR_DPT ;
					L_WG	:= x1.GR_WG_CD ;
					L_OWG	:= NVL(x1.BD_WG_CD, x1.GR_WG_CD) ;

					L_SIGN := -1 ;
				END IF ;

				IF L_WG IS NULL THEN
					IF x1.AC_SLIP_TYP = C_PURC_XPNS THEN
						L_WG := x1.GR_WG_CD ;
					ELSIF x1.AC_SLIP_TYP = C_PURC_RET_XPNS THEN
						L_WG := x1.GI_WG_CD ;
					ELSIF x1.AC_SLIP_TYP IN (C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS) THEN
						L_WG := x1.PURC_WG_CD ;
					END IF ;
					L_OWG := L_WG ;
				END IF ;

				-- 値引品目かつ経費購買、経費返品は符号を反転する
				IF x1.DSCNT_ITM_FLG = C_ON AND x1.AC_SLIP_TYP IN (C_PURC_XPNS, C_PURC_RET_XPNS) THEN
					L_SIGN := - L_SIGN ;
				END IF ;

				--負担部門を管理部門（品目製造指図）とする
				L_ODPT	:= L_BD_DPT ;
				L_LOC	:= NVL(x1.BD_LOC_CD, x1.LOC_CD) ;

				IF x1.ITM_MFG_INST_NO IS NULL THEN
					L_ITM_MFG_INST_NO := C_NULL_VAL ;
					L_MFG_ACT_NO := C_NULL_VAL ;
					L_OPER_ACT_NO := C_NULL_VAL ;
				END IF ;

			ELSIF x1.AC_SLIP_TYP = C_BYPROD THEN
				--副産物製造は入庫部門を管理部門（投入）、管理部門（品目製造指図）とする
				L_MDPT	:= L_GR_DPT ;
				L_WG	:= x1.GR_WG_CD ;

				L_ODPT	:= L_GR_DPT ;
				L_OWG	:= x1.GR_WG_CD ;

				L_LOC	:= x1.LOC_CD ;

				--符号を反転
				L_SIGN := -1 ;
			ELSE
				--出庫部門を管理部門（投入）、管理部門（品目製造指図）とする
				L_MDPT	:= L_GI_DPT ;
				L_WG	:= x1.GI_WG_CD ;

				L_ODPT := L_GI_DPT ;
				L_OWG	:= x1.GI_WG_CD ;

				L_LOC	:= x1.LOC_CD ;

				--符号はそのまま
				L_SIGN := 1 ;
			END IF ;

			IF L_WG IS NULL OR L_OWG IS NULL THEN
				IF x1.AC_SLIP_TYP IN (C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS) THEN	--経費
					FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0020', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
				ELSE
					FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0018', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
					L_DPT_ERR := C_ERR ;
				END IF ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF L_MDPT IS NULL OR L_ODPT IS NULL THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0017', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
				L_DPT_ERR := C_ERR ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.AC_SLIP_TYP IN (C_INSP_SMPL, C_DISP_SCRP, C_SO_STKTK, C_OTH_CCN_SO, C_IN_STKTK, C_OTH_CCN_GR)
			AND (L_FIX_DPT IS NULL AND L_MDPT <> L_ODPT OR L_WG <> L_OWG)
			AND L_QTY <> 0 THEN
				--入出庫で出庫ＷＧと入庫ＷＧもしくは出庫部門と入庫部門が異なるときは入出庫実績を作成する
				W4 := W4 + 1 ;

				REC_w4(w4).DATA_LNO	:= MAPA_NUM.F_GET_SEQ(C_ACT_IO_IF_DATA_LNO) ;
				REC_w4(w4).CALC_CTG_CD	:= I_CALC_CTG_CD ;
				REC_w4(w4).WG_CD		:= L_WG ;
				REC_w4(w4).YM		:= x1.AC_YM ;
				REC_w4(w4).AC_DT		:= x1.AC_DT ;
				REC_w4(w4).MNG_DPT_CD	:= L_MDPT ;
				REC_w4(w4).ITM_CD	:= x1.ITM_CD ;
				REC_w4(w4).ITM_SUB1	:= x1.ITM_SUB1 ;
				REC_w4(w4).ITM_SUB2	:= x1.ITM_SUB2 ;
				REC_w4(w4).ITM_SUB3	:= x1.ITM_SUB3 ;

				IF L_LOT_USE_TYP <> C_PS_USE3 AND x1.LOT_ACT_TYP = C_ACT2 THEN
					REC_w4(w4).LOT_NO	:= x1.LOT_NO ;
				ELSE
					REC_w4(w4).LOT_NO	:= C_NULL_VAL ;
				END IF ;

				IF L_SUBLOT_USE_TYP <> C_PS_USE3 AND x1.SUBLOT_ACT_TYP = C_ACT2 THEN
					REC_w4(w4).SUBLOT_NO	:= x1.SUBLOT_NO ;
				ELSE
					REC_w4(w4).SUBLOT_NO	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO1_USE_TYP <> C_PS_USE3 AND x1.SNO1_ACT_TYP = C_ACT2 THEN
					REC_w4(w4).SNO1	:= x1.SNO1 ;
				ELSE
					REC_w4(w4).SNO1	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO2_USE_TYP <> C_PS_USE3 AND x1.SNO2_ACT_TYP = C_ACT2 THEN
					REC_w4(w4).SNO2	:= x1.SNO2 ;
				ELSE
					REC_w4(w4).SNO2	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO3_USE_TYP <> C_PS_USE3 AND x1.SNO3_ACT_TYP = C_ACT2 THEN
					REC_w4(w4).SNO3	:= x1.SNO3 ;
				ELSE
					REC_w4(w4).SNO3	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO4_USE_TYP <> C_PS_USE3 AND x1.SNO4_ACT_TYP = C_ACT2 THEN
					REC_w4(w4).SNO4	:= x1.SNO4 ;
				ELSE
					REC_w4(w4).SNO4	:= C_NULL_VAL ;
				END IF ;

				REC_w4(w4).AC_SLIP_TYP	:= C_DPT_XFR_SO ;
				REC_w4(w4).AC_RSN_CD	:= x1.AC_RSN_CD ;
				REC_w4(w4).OTHER_WG_CD	:= L_OWG ;
				IF REC_w4(w4).WG_CD = REC_w4(w4).OTHER_WG_CD THEN
					REC_w4(w4).OTHER_WG_CD := NULL ;
				END IF ;
				REC_w4(w4).OTHER_DPT_CD	:= L_ODPT ;
				REC_w4(w4).BP_CD	:= NULL ;
				REC_w4(w4).STK_BP_CD	:= x1.BP_CD ;
				REC_w4(w4).ASST_TYP	:= L_ASST_TYP ;
				REC_w4(w4).QTY		:= L_QTY * L_SIGN ;
				REC_w4(w4).AMT		:= NULL ;
				REC_w4(w4).TRD_CUR_CD	:= NULL ;
				REC_w4(w4).TRD_CUR_AMT	:= NULL ;
				REC_w4(w4).XRATE	:= NULL ;
				REC_w4(w4).TRD_GRP	:= C_STR_TRD3 || TO_CHAR(REC_w4(w4).DATA_LNO) ;
				REC_w4(w4).TRD_RATIO	:= NULL ;
				REC_w4(w4).ALC_AC_CD	:= NULL ;
				REC_w4(w4).ALC_AMT_FLG	:= C_OFF ;
				REC_w4(w4).ALC_WG_CD	:= NULL ;
				REC_w4(w4).ALC_DPT_CD	:= NULL ;
				REC_w4(w4).ALC_LOC_CD	:= NULL ;
				REC_w4(w4).ALC_OPER_CD	:= NULL ;
				REC_w4(w4).ALC_BP_CD	:= NULL ;
				REC_w4(w4).ALC_CTG_CD	:= NULL ;
				REC_w4(w4).ALC_ITM_CD	:= NULL ;
				REC_w4(w4).ALC_ITM_SUB1	:= NULL ;
				REC_w4(w4).ALC_ITM_SUB2	:= NULL ;
				REC_w4(w4).ALC_ITM_SUB3	:= NULL ;
				REC_w4(w4).ALC_LOT_NO	:= NULL ;
				REC_w4(w4).ALC_SUBLOT_NO	:= NULL ;
				REC_w4(w4).ALC_SNO1	:= NULL ;
				REC_w4(w4).ALC_SNO2	:= NULL ;
				REC_w4(w4).ALC_SNO3	:= NULL ;
				REC_w4(w4).ALC_SNO4	:= NULL ;
				REC_w4(w4).ALC_ITM_MFG_INST_NO	:= NULL ;
				REC_w4(w4).REC_EVAL_TYP	:= NULL ;
				REC_w4(w4).NO_PLN_FLG	:= C_OFF ;
				REC_w4(w4).NO_ITM_INFO_FLG	:= C_OFF ;
				REC_w4(w4).ZERO_EFFECT_FLG := C_OFF ;
				REC_w4(w4).SLIP_NO	:= x1.SLIP_NO ;
				REC_w4(w4).SLIP_SEQ_NO	:= x1.SLIP_SEQ_NO ;
				REC_w4(w4).RMRKS	:= x1.TRD_D_RMRKS ;
				REC_w4(w4).SUB_CHAR1	:= NULL ;
				REC_w4(w4).SUB_CHAR2	:= NULL ;
				REC_w4(w4).SUB_CHAR3	:= NULL ;

				L_MDPT	:= L_ODPT ;
				L_WG	:= L_OWG ;
			END IF ;

			w3 := w3 + 1 ;

			REC_w3(w3).DATA_LNO	:= MAPA_NUM.F_GET_SEQ(C_ACT_INPT_IF_DATA_LNO) ;
			REC_w3(w3).CALC_CTG_CD	:= I_CALC_CTG_CD ;
			REC_w3(w3).WG_CD	:= L_WG ;
			REC_w3(w3).YM		:= x1.AC_YM ;
			REC_w3(w3).AC_DT		:= x1.AC_DT ;
			REC_w3(w3).PAR_ITM_CD	:= x1.PAR_ITM_CD ;
			REC_w3(w3).PAR_ITM_SUB1	:= x1.PAR_ITM_SUB1 ;
			REC_w3(w3).PAR_ITM_SUB2	:= x1.PAR_ITM_SUB2 ;
			REC_w3(w3).PAR_ITM_SUB3	:= x1.PAR_ITM_SUB3 ;
			REC_w3(w3).ITM_MFG_INST_NO := L_ITM_MFG_INST_NO ;
			REC_w3(w3).MFG_ACT_NO := L_MFG_ACT_NO ;
			REC_w3(w3).OPER_ACT_NO	:= L_OPER_ACT_NO ;
			REC_w3(w3).LOC_CD	:= L_LOC ;
			REC_w3(w3).STR_LN_CD	:= NVL(x1.STR_LN_CD, C_NULL_VAL) ;
			REC_w3(w3).MNG_DPT_CD	:= NVL(L_FIX_DPT, L_MDPT) ;
			REC_w3(w3).ITM_CD	:= x1.ITM_CD ;
			REC_w3(w3).ITM_SUB1	:= x1.ITM_SUB1 ;
			REC_w3(w3).ITM_SUB2	:= x1.ITM_SUB2 ;
			REC_w3(w3).ITM_SUB3	:= x1.ITM_SUB3 ;

			IF L_LOT_USE_TYP <> C_PS_USE3 AND x1.LOT_ACT_TYP = C_ACT2 THEN
				REC_w3(w3).LOT_NO	:= x1.LOT_NO ;
			ELSE
				REC_w3(w3).LOT_NO	:= C_NULL_VAL ;
			END IF ;

			IF L_SUBLOT_USE_TYP <> C_PS_USE3 AND x1.SUBLOT_ACT_TYP = C_ACT2 THEN
				REC_w3(w3).SUBLOT_NO	:= x1.SUBLOT_NO ;
			ELSE
				REC_w3(w3).SUBLOT_NO	:= C_NULL_VAL ;
			END IF ;

			IF L_SNO1_USE_TYP <> C_PS_USE3 AND x1.SNO1_ACT_TYP = C_ACT2 THEN
				REC_w3(w3).SNO1	:= x1.SNO1 ;
			ELSE
				REC_w3(w3).SNO1	:= C_NULL_VAL ;
			END IF ;

			IF L_SNO2_USE_TYP <> C_PS_USE3 AND x1.SNO2_ACT_TYP = C_ACT2 THEN
				REC_w3(w3).SNO2	:= x1.SNO2 ;
			ELSE
				REC_w3(w3).SNO2	:= C_NULL_VAL ;
			END IF ;

			IF L_SNO3_USE_TYP <> C_PS_USE3 AND x1.SNO3_ACT_TYP = C_ACT2 THEN
				REC_w3(w3).SNO3	:= x1.SNO3 ;
			ELSE
				REC_w3(w3).SNO3	:= C_NULL_VAL ;
			END IF ;

			IF L_SNO4_USE_TYP <> C_PS_USE3 AND x1.SNO4_ACT_TYP = C_ACT2 THEN
				REC_w3(w3).SNO4	:= x1.SNO4 ;
			ELSE
				REC_w3(w3).SNO4	:= C_NULL_VAL ;
			END IF ;

			REC_w3(w3).AC_SLIP_TYP	:= x1.AC_SLIP_TYP ;
			REC_w3(w3).AC_RSN_CD	:= x1.AC_RSN_CD ;
			REC_w3(w3).STK_BP_CD	:= x1.BP_CD ;
			REC_w3(w3).ASST_TYP	:= L_ASST_TYP ;
			REC_w3(w3).QTY		:= L_QTY * L_SIGN ;
			REC_w3(w3).AMT		:= x1.AMT * L_SIGN ;
			REC_w3(w3).TRD_CUR_CD	:= x1.TRD_CUR_CD ;
			REC_w3(w3).TRD_CUR_AMT	:= x1.TRD_CUR_AMT * L_SIGN ;
			REC_w3(w3).XRATE	:= x1.XRATE ;
			REC_w3(w3).REC_EVAL_TYP	:= NULL ;
			REC_w3(w3).EXPNS_CD	:= NULL ;
			REC_w3(w3).NO_PLN_FLG	:= C_OFF ;
			REC_w3(w3).NO_ITM_INFO_FLG	:= C_OFF ;
			REC_w3(w3).ZERO_EFFECT_FLG := C_OFF ;
			REC_w3(w3).SLIP_NO	:= x1.SLIP_NO ;
			REC_w3(w3).SLIP_SEQ_NO	:= x1.SLIP_SEQ_NO ;
			REC_w3(w3).RMRKS	:= x1.TRD_D_RMRKS ;
			REC_w3(w3).SUB_CHAR1	:= NULL ;
			REC_w3(w3).SUB_CHAR2	:= NULL ;
			REC_w3(w3).SUB_CHAR3	:= NULL ;

			IF L_ITM_MFG_INST_NO <> C_NULL_VAL AND F_CHK_ITM(x1.PAR_ITM_CD, x1.PAR_ITM_SUB1, x1.PAR_ITM_SUB2, x1.PAR_ITM_SUB3, L_ITM_MFG_INST_NO, L_MFG_ACT_NO) = C_ERR
			THEN
				GOTO OPER_INPT ;
			END IF ;

			w6 := w6 + 1 ;

			REC_w6(w6).CALC_CTG_CD	:= I_CALC_CTG_CD ;
			REC_w6(w6).ITM_CD	:= x1.PAR_ITM_CD ;
			REC_w6(w6).ITM_SUB1	:= x1.PAR_ITM_SUB1 ;
			REC_w6(w6).ITM_SUB2	:= x1.PAR_ITM_SUB2 ;
			REC_w6(w6).ITM_SUB3	:= x1.PAR_ITM_SUB3 ;
			REC_w6(w6).ITM_MFG_INST_NO := L_ITM_MFG_INST_NO ;
			REC_w6(w6).MFG_ACT_NO := L_MFG_ACT_NO ;
			REC_w6(w6).WG_CD	:= L_OWG ;
			REC_w6(w6).MNG_DPT_CD	:= NVL(L_FIX_DPT, L_ODPT) ;

			IF x1.AC_SLIP_TYP IN (C_INPUT, C_IN_ONR, C_IN_SS, C_BYPROD) AND x1.ITM_MFG_INST_NO_SET_TYP = C_INST_LOC THEN
				REC_w6(w6).LOT_NO	:= C_NULL_VAL ;
				REC_w6(w6).SUBLOT_NO	:= C_NULL_VAL ;
				REC_w6(w6).SNO1	:= C_NULL_VAL ;
				REC_w6(w6).SNO2	:= C_NULL_VAL ;
				REC_w6(w6).SNO3	:= C_NULL_VAL ;
				REC_w6(w6).SNO4	:= C_NULL_VAL ;
			ELSE
				IF L_LOT_USE_TYP <> C_PS_USE3 AND x1.PAR_LOT_ACT_TYP <> C_ACT1 THEN
					REC_w6(w6).LOT_NO	:= NVL(x1.PAR_LOT_NO, C_NULL_VAL) ;
				ELSE
					REC_w6(w6).LOT_NO	:= C_NULL_VAL ;
				END IF ;

				IF L_SUBLOT_USE_TYP <> C_PS_USE3 AND x1.PAR_SUBLOT_ACT_TYP <> C_ACT1 THEN
					REC_w6(w6).SUBLOT_NO	:= NVL(x1.PAR_SUBLOT_NO, C_NULL_VAL) ;
				ELSE
					REC_w6(w6).SUBLOT_NO	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO1_USE_TYP <> C_PS_USE3 AND x1.PAR_SNO1_ACT_TYP <> C_ACT1 THEN
					REC_w6(w6).SNO1	:= NVL(x1.PAR_SNO1, C_NULL_VAL) ;
				ELSE
					REC_w6(w6).SNO1	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO2_USE_TYP <> C_PS_USE3 AND x1.PAR_SNO2_ACT_TYP <> C_ACT1 THEN
					REC_w6(w6).SNO2	:= NVL(x1.PAR_SNO2, C_NULL_VAL) ;
				ELSE
					REC_w6(w6).SNO2	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO3_USE_TYP <> C_PS_USE3 AND x1.PAR_SNO3_ACT_TYP <> C_ACT1 THEN
					REC_w6(w6).SNO3	:= NVL(x1.PAR_SNO3, C_NULL_VAL) ;
				ELSE
					REC_w6(w6).SNO3	:= C_NULL_VAL ;
				END IF ;

				IF L_SNO4_USE_TYP <> C_PS_USE3 AND x1.PAR_SNO4_ACT_TYP <> C_ACT1 THEN
					REC_w6(w6).SNO4	:= NVL(x1.PAR_SNO4, C_NULL_VAL) ;
				ELSE
					REC_w6(w6).SNO4	:= C_NULL_VAL ;
				END IF ;
			END IF ;

			IF x1.AC_SLIP_TYP IN (C_INPUT, C_IN_ONR, C_IN_SS, C_BYPROD) THEN
				REC_w6(w6).SPPL_CD := x1.BP_CD ;
				REC_w6(w6).PO_NO	:= x1.PO_NO ;
				REC_w6(w6).SLO_NO	:= x1.SLO_NO ;
				REC_w6(w6).IV_NO	:= x1.RCPT_IV_NO ;
			ELSE
				REC_w6(w6).SPPL_CD	:= NVL(x1.BD_BP_CD, x1.BP_CD) ;
				REC_w6(w6).PO_NO	:= NVL(x1.BD_PO_NO, x1.PO_NO) ;
				REC_w6(w6).SLO_NO	:= NVL(x1.BD_SLO_NO, x1.SLO_NO) ;
				REC_w6(w6).IV_NO	:= NVL(x1.BD_IV_NO, x1.RCPT_IV_NO) ;
			END IF ;
			REC_w6(w6).ASST_TYP	:= C_ASST2 ;
			IF x1.MFG_INST_UNIT_TYP = C_ITM THEN
				REC_w6(w6).QTY		:= NVL(x1.MFG_ST_QTY, 0) ;
			ELSE
				REC_w6(w6).QTY		:= NVL(x1.ITM_INST_QTY, 0) ;
			END IF ;
			REC_w6(w6).SCHD_ST_DT	:= NULL ;
			REC_w6(w6).SCHD_END_DT	:= NULL ;
			REC_w6(w6).ACT_ST_DT	:= NULL ;
			REC_w6(w6).ACT_END_DT	:= NULL ;
			REC_w6(w6).RMRKS	:= NULL ;--x1.TRD_RMRKS ;
			REC_w6(w6).SUB_CHAR1	:= NULL ;
			REC_w6(w6).SUB_CHAR2	:= NULL ;
			REC_w6(w6).SUB_CHAR3	:= NULL ;

			P_COL_PROC_ITM() ;

			IF L_ITM_MFG_INST_NO <> C_NULL_VAL
			AND x1.AC_SLIP_TYP IN (
				C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS,				--経費
				C_INSP_SMPL, C_DISP_SCRP, C_SO_STKTK, C_OTH_CCN_SO, C_IN_STKTK, C_OTH_CCN_GR	--入出庫
			) THEN
				t6 := t6 + 1 ;
				TMP_w6(t6) := REC_w6(w6) ;

				REC_w6.DELETE(w6) ;
				w6 := w6 - 1 ;

				REC_CHK_ITM.DELETE(x1.ITM_CD || C_STR_CHK || x1.ITM_SUB1 || C_STR_CHK || x1.ITM_SUB2
					|| C_STR_CHK || x1.ITM_SUB3 || C_STR_CHK || x1.ITM_MFG_INST_NO || C_STR_CHK || x1.MFG_ACT_NO) ;

				GOTO NEXT_LOOP ;
			END IF ;

			IF L_ITM_MFG_INST_NO = C_NULL_VAL THEN
				t3 := t3 + 1 ;

				TMP_w3(t3).CALC_CTG_CD	:= REC_w3(w3).CALC_CTG_CD ;
				TMP_w3(t3).WG_CD		:= REC_w3(w3).WG_CD ;
				TMP_w3(t3).YM		:= REC_w3(w3).YM ;
				TMP_w3(t3).AC_DT		:= REC_w3(w3).AC_DT ;
				TMP_w3(t3).PAR_ITM_CD	:= REC_w3(w3).PAR_ITM_CD ;
				TMP_w3(t3).PAR_ITM_SUB1	:= REC_w3(w3).PAR_ITM_SUB1 ;
				TMP_w3(t3).PAR_ITM_SUB2	:= REC_w3(w3).PAR_ITM_SUB2 ;
				TMP_w3(t3).PAR_ITM_SUB3	:= REC_w3(w3).PAR_ITM_SUB3 ;
				TMP_w3(t3).PAR_LOT_NO	:= REC_w6(w6).LOT_NO ;
				TMP_w3(t3).PAR_SUBLOT_NO	:= REC_w6(w6).SUBLOT_NO ;
				TMP_w3(t3).PAR_SNO1		:= REC_w6(w6).SNO1 ;
				TMP_w3(t3).PAR_SNO2		:= REC_w6(w6).SNO2 ;
				TMP_w3(t3).PAR_SNO3		:= REC_w6(w6).SNO3 ;
				TMP_w3(t3).PAR_SNO4		:= REC_w6(w6).SNO4 ;
				TMP_w3(t3).ITM_MFG_INST_NO := REC_w3(w3).ITM_MFG_INST_NO ;
				TMP_w3(t3).MFG_ACT_NO := REC_w3(w3).MFG_ACT_NO ;
				TMP_w3(t3).OPER_ACT_NO	:= REC_w3(w3).OPER_ACT_NO ;
				TMP_w3(t3).LOC_CD	:= REC_w3(w3).LOC_CD ;
				TMP_w3(t3).STR_LN_CD	:= REC_w3(w3).STR_LN_CD ;
				TMP_w3(t3).MNG_DPT_CD	:= REC_w3(w3).MNG_DPT_CD ;
				TMP_w3(t3).ITM_CD	:= REC_w3(w3).ITM_CD ;
				TMP_w3(t3).ITM_SUB1	:= REC_w3(w3).ITM_SUB1 ;
				TMP_w3(t3).ITM_SUB2	:= REC_w3(w3).ITM_SUB2 ;
				TMP_w3(t3).ITM_SUB3	:= REC_w3(w3).ITM_SUB3 ;
				IF REC_w3(w3).AC_SLIP_TYP IN (
					C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS
				) THEN
					TMP_w3(t3).LOT_NO		:= C_NULL_VAL ;
					TMP_w3(t3).SUBLOT_NO	:= C_NULL_VAL ;
					TMP_w3(t3).SNO1		:= C_NULL_VAL ;
					TMP_w3(t3).SNO2		:= C_NULL_VAL ;
					TMP_w3(t3).SNO3		:= C_NULL_VAL ;
					TMP_w3(t3).SNO4		:= C_NULL_VAL ;
				ELSE
					TMP_w3(t3).LOT_NO		:= REC_w3(w3).LOT_NO ;
					TMP_w3(t3).SUBLOT_NO	:= REC_w3(w3).SUBLOT_NO ;
					TMP_w3(t3).SNO1		:= REC_w3(w3).SNO1 ;
					TMP_w3(t3).SNO2		:= REC_w3(w3).SNO2 ;
					TMP_w3(t3).SNO3		:= REC_w3(w3).SNO3 ;
					TMP_w3(t3).SNO4		:= REC_w3(w3).SNO4 ;
				END IF ;
				TMP_w3(t3).AC_SLIP_TYP	:= REC_w3(w3).AC_SLIP_TYP ;
				TMP_w3(t3).AC_RSN_CD	:= REC_w3(w3).AC_RSN_CD ;
				TMP_w3(t3).STK_BP_CD	:= REC_w3(w3).STK_BP_CD ;
				TMP_w3(t3).ASST_TYP	:= REC_w3(w3).ASST_TYP ;
				TMP_w3(t3).QTY		:= REC_w3(w3).QTY ;
				TMP_w3(t3).AMT		:= REC_w3(w3).AMT ;
				TMP_w3(t3).TRD_CUR_CD	:= REC_w3(w3).TRD_CUR_CD ;
				TMP_w3(t3).TRD_CUR_AMT	:= REC_w3(w3).TRD_CUR_AMT ;
				TMP_w3(t3).XRATE	:= REC_w3(w3).XRATE ;
				TMP_w3(t3).REC_EVAL_TYP	:= REC_w3(w3).REC_EVAL_TYP ;
				TMP_w3(t3).EXPNS_CD	:= REC_w3(w3).EXPNS_CD ;
				TMP_w3(t3).SLIP_NO	:= REC_w3(w3).SLIP_NO ;
				TMP_w3(t3).SLIP_SEQ_NO	:= REC_w3(w3).SLIP_SEQ_NO ;
				TMP_w3(t3).RMRKS	:= REC_w3(w3).RMRKS ;
				TMP_w3(t3).SUB_CHAR1	:= NULL ;
				TMP_w3(t3).SUB_CHAR2	:= NULL ;
				TMP_w3(t3).SUB_CHAR3	:= NULL ;

				REC_w3.DELETE(w3) ;
				w3 := w3 - 1 ;

				REC_w6.DELETE(w6) ;
				w6 := w6 - 1 ;

				GOTO NEXT_LOOP ;
			END IF ;

			<<OPER_INPT>>
				NULL ;

			IF x1.OPER_CD IS NULL OR x1.OPER_CD = C_NULL_VAL OR F_CHK_OPER(x1.PAR_ITM_CD, x1.PAR_ITM_SUB1, x1.PAR_ITM_SUB2, x1.PAR_ITM_SUB3, L_ITM_MFG_INST_NO, L_MFG_ACT_NO, L_OPER_ACT_NO) = C_ERR THEN
				GOTO NEXT_LOOP ;
			END IF ;

			w7 := w7 + 1 ;

			REC_w7(w7).CALC_CTG_CD	:= I_CALC_CTG_CD ;
			REC_w7(w7).ITM_CD	:= x1.PAR_ITM_CD ;
			REC_w7(w7).ITM_SUB1	:= x1.PAR_ITM_SUB1 ;
			REC_w7(w7).ITM_SUB2	:= x1.PAR_ITM_SUB2 ;
			REC_w7(w7).ITM_SUB3	:= x1.PAR_ITM_SUB3 ;
			REC_w7(w7).ITM_MFG_INST_NO := L_ITM_MFG_INST_NO ;
			REC_w7(w7).MFG_ACT_NO := L_MFG_ACT_NO ;
			REC_w7(w7).OPER_ACT_NO	:= L_OPER_ACT_NO ;
			REC_w7(w7).WG_CD	:= L_OWG ;
			REC_w7(w7).MNG_DPT_CD	:= NVL(L_FIX_DPT, L_ODPT) ;
			REC_w7(w7).OPER_CD	:= x1.OPER_CD ;
			REC_w7(w7).OPER_SEQ	:= 1 ;
			REC_w7(w7).DISP_SEQ	:= NVL(x1.DISP_SEQ, 1) ;
			REC_w7(w7).QTY		:= NULL ;
			REC_w7(w7).SCHD_ST_DT	:= NULL ;
			REC_w7(w7).SCHD_END_DT	:= NULL ;
			REC_w7(w7).ACT_ST_DT	:= NULL ;
			REC_w7(w7).ACT_END_DT	:= NULL ;
			REC_w7(w7).RMRKS	:= NULL ;--x1.TRD_D_RMRKS ;
			REC_w7(w7).SUB_CHAR1	:= NULL ;
			REC_w7(w7).SUB_CHAR2	:= NULL ;
			REC_w7(w7).SUB_CHAR3	:= NULL ;

			GOTO NEXT_LOOP ;
		END IF ;

		--支給、出荷実績関連の取込
		IF x1.AC_SLIP_TYP IN (
			C_FFR_PROV, C_ONR_PROV, C_FFR_PRVR, C_ONR_PRVR, C_SHIP, C_SHIP_RET
			)
		THEN
			IF L_NON_PROD_FLG = C_OFF AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			OR L_NON_SLS_FLG = C_OFF AND x1.ASST_TYP = C_ASST1
			THEN
				NULL ;
			ELSE
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.ASSET_MNG_TYP <> C_ASST_MNG1 THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0044', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2,
						MAPA_COMM.F_TO_DISP_ITM(x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, L_PARM), x1.AC_SLIP_TYP) ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.AC_SLIP_TYP IN (C_FFR_PRVR, C_ONR_PRVR, C_SHIP) THEN
				--支給戻関連、出荷は出庫部門を管理部門とする
				L_MDPT	:= NVL(L_GI_DPT, L_GR_DPT) ;
				L_WG	:= NVL(x1.GI_WG_CD, x1.GR_WG_CD) ;
			ELSE	--C_FFR_PROV, C_ONR_PROV, C_SHIP_RET
				--支給関連、出荷返品は入庫部門を管理部門とする
				L_MDPT	:= NVL(L_GR_DPT, L_GI_DPT) ;
				L_WG	:= NVL(x1.GR_WG_CD, x1.GI_WG_CD) ;
			END IF ;

			IF x1.AC_SLIP_TYP IN (C_FFR_PRVR, C_ONR_PRVR, C_SHIP_RET) THEN
				--符号を反転
				L_SIGN := -1 ;
			ELSE	--C_FFR_PROV, C_ONR_PROV, C_SHIP
				--符号はそのまま
				L_SIGN := 1 ;
			END IF ;

			L_ODPT	:= L_MDPT ;
			L_OWG	:= L_WG ;

			IF L_WG IS NULL THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0018', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
				L_DPT_ERR := C_ERR ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF L_MDPT IS NULL THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0017', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
				L_DPT_ERR := C_ERR ;
				GOTO NEXT_LOOP ;
			END IF ;

			--自社から出庫したことにする
			IF L_ASST_TYP = C_ASST3 THEN
				L_ASST_TYP := C_ASST2 ;
			END IF ;

			IF x1.AC_SLIP_TYP IN (C_SHIP, C_SHIP_RET) THEN
				--出荷先の在庫を考慮しない場合は出荷関連のデータを取込まない
				IF L_STK_BP_FLG = C_OFF THEN
					GOTO NEXT_LOOP ;
				END IF ;
			END IF ;

			w4 := w4 + 1 ;

			REC_w4(w4).DATA_LNO	:= MAPA_NUM.F_GET_SEQ(C_ACT_IO_IF_DATA_LNO) ;
			REC_w4(w4).CALC_CTG_CD	:= I_CALC_CTG_CD ;
			REC_w4(w4).WG_CD	:= L_WG ;
			REC_w4(w4).YM		:= x1.AC_YM ;
			REC_w4(w4).AC_DT		:= x1.AC_DT ;
			REC_w4(w4).MNG_DPT_CD	:= NVL(L_FIX_DPT, L_MDPT) ;
			REC_w4(w4).ITM_CD	:= x1.ITM_CD ;
			REC_w4(w4).ITM_SUB1	:= x1.ITM_SUB1 ;
			REC_w4(w4).ITM_SUB2	:= x1.ITM_SUB2 ;
			REC_w4(w4).ITM_SUB3	:= x1.ITM_SUB3 ;

			IF x1.LOT_ACT_TYP = C_ACT2
			AND (L_LOT_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			  OR L_LOT_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_LOT_USE_TYP = C_PS_USE1
			  )
			THEN
				REC_w4(w4).LOT_NO	:= x1.LOT_NO ;
			ELSE
				REC_w4(w4).LOT_NO	:= C_NULL_VAL ;
			END IF ;

			IF x1.SUBLOT_ACT_TYP = C_ACT2
			AND (L_SUBLOT_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			  OR L_SUBLOT_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SUBLOT_USE_TYP = C_PS_USE1
			  )
			THEN
				REC_w4(w4).SUBLOT_NO	:= x1.SUBLOT_NO ;
			ELSE
				REC_w4(w4).SUBLOT_NO	:= C_NULL_VAL ;
			END IF ;

			IF x1.SNO1_ACT_TYP = C_ACT2
			AND (L_SNO1_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			  OR L_SNO1_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SNO1_USE_TYP = C_PS_USE1
			  )
			THEN
				REC_w4(w4).SNO1	:= x1.SNO1 ;
			ELSE
				REC_w4(w4).SNO1	:= C_NULL_VAL ;
			END IF ;

			IF x1.SNO2_ACT_TYP = C_ACT2
			AND (L_SNO2_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			  OR L_SNO2_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SNO2_USE_TYP = C_PS_USE1
			  )
			THEN
				REC_w4(w4).SNO2	:= x1.SNO2 ;
			ELSE
				REC_w4(w4).SNO2	:= C_NULL_VAL ;
			END IF ;

			IF x1.SNO3_ACT_TYP = C_ACT2
			AND (L_SNO3_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			  OR L_SNO3_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SNO3_USE_TYP = C_PS_USE1
			  )
			THEN
				REC_w4(w4).SNO3	:= x1.SNO3 ;
			ELSE
				REC_w4(w4).SNO3	:= C_NULL_VAL ;
			END IF ;

			IF x1.SNO4_ACT_TYP = C_ACT2
			AND (L_SNO4_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			  OR L_SNO4_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SNO4_USE_TYP = C_PS_USE1
			  )
			THEN
				REC_w4(w4).SNO4	:= x1.SNO4 ;
			ELSE
				REC_w4(w4).SNO4	:= C_NULL_VAL ;
			END IF ;

			REC_w4(w4).AC_SLIP_TYP	:= x1.AC_SLIP_TYP ;
			REC_w4(w4).AC_RSN_CD	:= x1.AC_RSN_CD ;

			--出庫ＷＧと入庫ＷＧは同じなのでOTHER_WG_CDを設定しない
			REC_w4(w4).OTHER_WG_CD := NULL ;
			REC_w4(w4).OTHER_DPT_CD	:= NVL(L_FIX_DPT, L_ODPT) ;
			IF REC_w4(w4).AC_SLIP_TYP IN (C_SHIP, C_SHIP_RET) THEN
				REC_w4(w4).BP_CD := x1.DLV_CD ;
			ELSE
				REC_w4(w4).BP_CD := x1.BP_CD ;
			END IF ;
			REC_w4(w4).STK_BP_CD	:= NULL ;
			REC_w4(w4).ASST_TYP	:= L_ASST_TYP ;
			REC_w4(w4).QTY		:= L_QTY * L_SIGN ;
			IF x1.AC_SLIP_TYP IN (C_ONR_PROV, C_ONR_PRVR) THEN
				REC_w4(w4).AMT		:= x1.AMT * L_SIGN ;
				REC_w4(w4).TRD_CUR_CD	:= x1.TRD_CUR_CD ;
				REC_w4(w4).TRD_CUR_AMT	:= x1.TRD_CUR_AMT * L_SIGN ;
				REC_w4(w4).XRATE	:= x1.XRATE ;
			ELSE
				REC_w4(w4).AMT		:= NULL ;
				REC_w4(w4).TRD_CUR_CD	:= NULL ;
				REC_w4(w4).TRD_CUR_AMT	:= NULL ;
				REC_w4(w4).XRATE	:= NULL ;
			END IF ;
			REC_w4(w4).TRD_GRP	:= NULL ;
			REC_w4(w4).TRD_RATIO	:= NULL ;
			REC_w4(w4).ALC_AC_CD	:= NULL ;
			REC_w4(w4).ALC_AMT_FLG	:= C_OFF ;
			REC_w4(w4).ALC_WG_CD	:= NULL ;
			REC_w4(w4).ALC_DPT_CD	:= NULL ;
			REC_w4(w4).ALC_LOC_CD	:= NULL ;
			REC_w4(w4).ALC_OPER_CD	:= NULL ;
			REC_w4(w4).ALC_BP_CD	:= NULL ;
			REC_w4(w4).ALC_CTG_CD	:= NULL ;
			REC_w4(w4).ALC_ITM_CD	:= NULL ;
			REC_w4(w4).ALC_ITM_SUB1	:= NULL ;
			REC_w4(w4).ALC_ITM_SUB2	:= NULL ;
			REC_w4(w4).ALC_ITM_SUB3	:= NULL ;
			REC_w4(w4).ALC_LOT_NO	:= NULL ;
			REC_w4(w4).ALC_SUBLOT_NO	:= NULL ;
			REC_w4(w4).ALC_SNO1	:= NULL ;
			REC_w4(w4).ALC_SNO2	:= NULL ;
			REC_w4(w4).ALC_SNO3	:= NULL ;
			REC_w4(w4).ALC_SNO4	:= NULL ;
			REC_w4(w4).ALC_ITM_MFG_INST_NO	:= NULL ;
			REC_w4(w4).REC_EVAL_TYP	:= NULL ;
			REC_w4(w4).NO_PLN_FLG	:= C_OFF ;
			REC_w4(w4).NO_ITM_INFO_FLG	:= C_OFF ;
			REC_w4(w4).ZERO_EFFECT_FLG := C_OFF ;
			REC_w4(w4).SLIP_NO	:= x1.SLIP_NO ;
			REC_w4(w4).SLIP_SEQ_NO	:= x1.SLIP_SEQ_NO ;
			REC_w4(w4).RMRKS	:= x1.TRD_D_RMRKS ;
			REC_w4(w4).SUB_CHAR1	:= NULL ;
			REC_w4(w4).SUB_CHAR2	:= NULL ;
			REC_w4(w4).SUB_CHAR3	:= NULL ;

			GOTO NEXT_LOOP ;
		END IF ;

		--出庫、入庫実績関連の取込
		IF x1.AC_SLIP_TYP IN (
			C_INSP_SMPL, C_DISP_SCRP, C_SO_STKTK, C_OTH_CCN_SO,	--出庫
			C_IN_STKTK, C_OTH_CCN_GR	--入庫
			)
		AND (x1.PAR_ITM_CD IS NULL OR NVL(x1.BD_LOC_CD, x1.LOC_CD) IS NULL)
		THEN
			IF L_NON_PROD_FLG = C_OFF AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			OR L_NON_SLS_FLG = C_OFF AND x1.ASST_TYP = C_ASST1
			THEN
				NULL ;
			ELSE
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.ASSET_MNG_TYP <> C_ASST_MNG1 THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0044', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2,
						MAPA_COMM.F_TO_DISP_ITM(x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, L_PARM), x1.AC_SLIP_TYP) ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.AC_SLIP_TYP IN (C_IN_STKTK, C_OTH_CCN_GR) THEN
				--入庫関連は入庫部門を管理部門とする
				L_MDPT	:= L_GR_DPT ;
				L_WG	:= x1.GR_WG_CD ;

				--負担・出庫部門を相手部門とする
				L_ODPT	:= NVL(L_BD_DPT, NVL(L_GI_DPT, L_GR_DPT)) ;
				L_OWG	:= NVL(x1.BD_WG_CD, NVL(x1.GI_WG_CD, x1.GR_WG_CD)) ;
			ELSE	--C_INSP_SMPL, C_DISP_SCRP, C_SO_STKTK, C_OTH_CCN_SO
				--その他は出庫部門を管理部門とする
				L_MDPT	:= L_GI_DPT ;
				L_WG	:= x1.GI_WG_CD ;

				--負担・入庫部門を相手部門とする
				L_ODPT	:= NVL(L_BD_DPT, NVL(L_GR_DPT, L_GI_DPT)) ;
				L_OWG	:= NVL(x1.BD_WG_CD, NVL(x1.GR_WG_CD, x1.GI_WG_CD)) ;
			END IF ;

			IF L_WG IS NULL OR L_OWG IS NULL THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0018', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
				L_DPT_ERR := C_ERR ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF L_MDPT IS NULL OR L_ODPT IS NULL THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0017', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
				L_DPT_ERR := C_ERR ;
				GOTO NEXT_LOOP ;
			END IF ;

			w4 := w4 + 1 ;

			REC_w4(w4).DATA_LNO	:= MAPA_NUM.F_GET_SEQ(C_ACT_IO_IF_DATA_LNO) ;
			REC_w4(w4).CALC_CTG_CD	:= I_CALC_CTG_CD ;
			REC_w4(w4).WG_CD	:= L_WG ;
			REC_w4(w4).YM		:= x1.AC_YM ;
			REC_w4(w4).AC_DT		:= x1.AC_DT ;
			REC_w4(w4).MNG_DPT_CD	:= NVL(L_FIX_DPT, L_MDPT) ;
			REC_w4(w4).ITM_CD	:= x1.ITM_CD ;
			REC_w4(w4).ITM_SUB1	:= x1.ITM_SUB1 ;
			REC_w4(w4).ITM_SUB2	:= x1.ITM_SUB2 ;
			REC_w4(w4).ITM_SUB3	:= x1.ITM_SUB3 ;

			IF x1.LOT_ACT_TYP = C_ACT2
			AND (L_LOT_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			  OR L_LOT_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_LOT_USE_TYP = C_PS_USE1
			  )
			THEN
				REC_w4(w4).LOT_NO	:= x1.LOT_NO ;
			ELSE
				REC_w4(w4).LOT_NO := C_NULL_VAL ;
			END IF ;
			REC_w4(w4).ALC_LOT_NO := x1.PAR_LOT_NO ;
			IF REC_w4(w4).ALC_LOT_NO IS NULL AND x1.LOT_NO <> C_NULL_VAL THEN
				REC_w4(w4).ALC_LOT_NO := x1.LOT_NO ;
			END IF ;

			IF x1.SUBLOT_ACT_TYP = C_ACT2
			AND (L_SUBLOT_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			  OR L_SUBLOT_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SUBLOT_USE_TYP = C_PS_USE1
			  )
			THEN
				REC_w4(w4).SUBLOT_NO	:= x1.SUBLOT_NO ;
			ELSE
				REC_w4(w4).SUBLOT_NO := C_NULL_VAL ;
			END IF ;
			REC_w4(w4).ALC_SUBLOT_NO := x1.PAR_SUBLOT_NO ;
			IF REC_w4(w4).ALC_SUBLOT_NO IS NULL AND x1.SUBLOT_NO <> C_NULL_VAL THEN
				REC_w4(w4).ALC_SUBLOT_NO := x1.SUBLOT_NO ;
			END IF ;

			IF x1.SNO1_ACT_TYP = C_ACT2
			AND (L_SNO1_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			  OR L_SNO1_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SNO1_USE_TYP = C_PS_USE1
			  )
			THEN
				REC_w4(w4).SNO1	:= x1.SNO1 ;
			ELSE
				REC_w4(w4).SNO1 := C_NULL_VAL ;
			END IF ;
			REC_w4(w4).ALC_SNO1 := x1.PAR_SNO1 ;
			IF REC_w4(w4).ALC_SNO1 IS NULL AND x1.SNO1 <> C_NULL_VAL THEN
				REC_w4(w4).ALC_SNO1 := x1.SNO1 ;
			END IF ;

			IF x1.SNO2_ACT_TYP = C_ACT2
			AND (L_SNO2_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			  OR L_SNO2_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SNO2_USE_TYP = C_PS_USE1
			  )
			THEN
				REC_w4(w4).SNO2	:= x1.SNO2 ;
			ELSE
				REC_w4(w4).SNO2 := C_NULL_VAL ;
			END IF ;
			REC_w4(w4).ALC_SNO2 := x1.PAR_SNO2 ;
			IF REC_w4(w4).ALC_SNO2 IS NULL AND x1.SNO2 <> C_NULL_VAL THEN
				REC_w4(w4).ALC_SNO2 := x1.SNO2 ;
			END IF ;

			IF x1.SNO3_ACT_TYP = C_ACT2
			AND (L_SNO3_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			  OR L_SNO3_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SNO3_USE_TYP = C_PS_USE1
			  )
			THEN
				REC_w4(w4).SNO3	:= x1.SNO3 ;
			ELSE
				REC_w4(w4).SNO3 := C_NULL_VAL ;
			END IF ;
			REC_w4(w4).ALC_SNO3 := x1.PAR_SNO3 ;
			IF REC_w4(w4).ALC_SNO3 IS NULL AND x1.SNO3 <> C_NULL_VAL THEN
				REC_w4(w4).ALC_SNO3 := x1.SNO3 ;
			END IF ;

			IF x1.SNO4_ACT_TYP = C_ACT2
			AND (L_SNO4_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			  OR L_SNO4_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
			  OR L_SNO4_USE_TYP = C_PS_USE1
			  )
			THEN
				REC_w4(w4).SNO4	:= x1.SNO4 ;
			ELSE
				REC_w4(w4).SNO4 := C_NULL_VAL ;
			END IF ;
			REC_w4(w4).ALC_SNO4 := x1.PAR_SNO4 ;
			IF REC_w4(w4).ALC_SNO4 IS NULL AND x1.SNO4 <> C_NULL_VAL THEN
				REC_w4(w4).ALC_SNO4 := x1.SNO4 ;
			END IF ;

			REC_w4(w4).AC_SLIP_TYP	:= x1.AC_SLIP_TYP ;
			REC_w4(w4).AC_RSN_CD	:= x1.AC_RSN_CD ;
			REC_w4(w4).OTHER_WG_CD	:= L_OWG ;
			IF REC_w4(w4).WG_CD = REC_w4(w4).OTHER_WG_CD THEN
				REC_w4(w4).OTHER_WG_CD := NULL ;
			END IF ;
			REC_w4(w4).OTHER_DPT_CD	:= L_ODPT ;
			IF L_ASST_TYP IN (C_ASST1, C_ASST2) AND x1.STK_ID_TYP = C_STK_ID8 THEN
				REC_w4(w4).BP_CD := x1.BP_CD ;
			ELSE
				REC_w4(w4).BP_CD := NULL ;
			END IF ;
			IF L_ASST_TYP = C_ASST1 OR (L_ASST_TYP = C_ASST2 AND x1.TRD_PTN_TYP = C_TRD_PTN_SLS) THEN
				IF x1.TRD_PTN_TYP = C_TRD_PTN_SLS_RTN THEN
					REC_w4(w4).STK_BP_CD := NULL ;
				ELSIF L_STK_BP_FLG = C_ON THEN
					REC_w4(w4).STK_BP_CD := x1.DLV_CD ;
				ELSE
					REC_w4(w4).STK_BP_CD := NULL ;
				END IF ;
			ELSE
				REC_w4(w4).STK_BP_CD := x1.BP_CD ;
			END IF ;
			REC_w4(w4).ASST_TYP	:= L_ASST_TYP ;
			REC_w4(w4).QTY		:= L_QTY ;
			REC_w4(w4).AMT		:= NULL ;
			REC_w4(w4).TRD_CUR_CD	:= NULL ;
			REC_w4(w4).TRD_CUR_AMT	:= NULL ;
			REC_w4(w4).XRATE	:= NULL ;
			REC_w4(w4).TRD_GRP	:= NULL ;
			REC_w4(w4).TRD_RATIO	:= NULL ;
			REC_w4(w4).ALC_AC_CD	:= NULL ;
			REC_w4(w4).ALC_AMT_FLG	:= C_OFF ;
			REC_w4(w4).ALC_WG_CD	:= L_OWG ;
			REC_w4(w4).ALC_DPT_CD	:= L_ODPT ;
			REC_w4(w4).ALC_LOC_CD	:= NVL(x1.BD_LOC_CD, x1.LOC_CD) ;
			REC_w4(w4).ALC_OPER_CD	:= NVL(x1.BD_OPER_CD, x1.OPER_CD) ;
			REC_w4(w4).ALC_BP_CD	:= NVL(x1.BD_BP_CD, x1.BP_CD) ;
			REC_w4(w4).ALC_CTG_CD	:= x1.BD_CTG_CD ;
			REC_w4(w4).ALC_ITM_CD	:= NVL(x1.PAR_ITM_CD, x1.ITM_CD) ;
			REC_w4(w4).ALC_ITM_SUB1	:= NVL(x1.PAR_ITM_SUB1, x1.ITM_SUB1) ;
			REC_w4(w4).ALC_ITM_SUB2	:= NVL(x1.PAR_ITM_SUB2, x1.ITM_SUB2) ;
			REC_w4(w4).ALC_ITM_SUB3	:= NVL(x1.PAR_ITM_SUB3, x1.ITM_SUB3) ;
			REC_w4(w4).ALC_ITM_MFG_INST_NO	:= x1.ITM_MFG_INST_NO ;
			REC_w4(w4).REC_EVAL_TYP	:= NULL ;
			REC_w4(w4).NO_PLN_FLG	:= C_OFF ;
			REC_w4(w4).NO_ITM_INFO_FLG	:= C_OFF ;
			REC_w4(w4).ZERO_EFFECT_FLG := C_OFF ;
			REC_w4(w4).SLIP_NO	:= x1.SLIP_NO ;
			REC_w4(w4).SLIP_SEQ_NO	:= x1.SLIP_SEQ_NO ;
			REC_w4(w4).RMRKS	:= x1.TRD_D_RMRKS ;
			REC_w4(w4).SUB_CHAR1	:= NULL ;
			REC_w4(w4).SUB_CHAR2	:= NULL ;
			REC_w4(w4).SUB_CHAR3	:= NULL ;

			GOTO NEXT_LOOP ;
		END IF ;

		--振替出庫、入庫実績関連の取込
		IF x1.AC_SLIP_TYP IN (
			C_PROD_ITM_SO, C_PROD_ITM_RET_SO, C_DPT_XFR_SO, C_STK_SW_SO,	--出庫
			C_STK_SW_GR														--入庫
			)
		THEN
			IF x1.AC_SLIP_TYP = C_PROD_ITM_SO AND x1.ASST_TYP = C_ASST1 AND L_NON_PROD_FLG = C_OFF THEN
				x1.ASST_TYP := C_ASST2 ;
			ELSIF x1.AC_SLIP_TYP = C_PROD_ITM_SO AND x1.ASST_TYP = C_ASST2 AND L_NON_PROD_FLG = C_ON THEN
				x1.ASST_TYP := C_ASST1 ;
			END IF ;
			IF x1.AC_SLIP_TYP = C_PROD_ITM_RET_SO AND x1.ASST_TYP = C_ASST2 AND L_NON_SLS_FLG = C_OFF THEN
				x1.ASST_TYP := C_ASST1 ;
			ELSIF x1.AC_SLIP_TYP = C_PROD_ITM_RET_SO AND x1.ASST_TYP = C_ASST1 AND L_NON_SLS_FLG = C_ON THEN
				x1.ASST_TYP := C_ASST2 ;
			END IF ;

			IF L_NON_PROD_FLG = C_OFF AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
			OR L_NON_SLS_FLG = C_OFF AND x1.ASST_TYP = C_ASST1
			THEN
				NULL ;
			ELSE
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.ASSET_MNG_TYP <> C_ASST_MNG1 THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0044', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2,
						MAPA_COMM.F_TO_DISP_ITM(x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, L_PARM), x1.AC_SLIP_TYP) ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.AC_SLIP_TYP = C_STK_SW_GR
			OR x1.AC_SLIP_TYP = C_PROD_ITM_SO AND L_NON_PROD_FLG = C_ON
			OR x1.AC_SLIP_TYP = C_PROD_ITM_RET_SO AND L_NON_SLS_FLG = C_ON
			THEN
				--振替入庫関連は入庫部門を管理部門、出庫部門を相手部門とする
				L_MDPT	:= NVL(L_GR_DPT, L_GI_DPT) ;
				L_WG	:= NVL(x1.GR_WG_CD, x1.GI_WG_CD) ;

				L_ODPT	:= NVL(L_GI_DPT, L_GR_DPT) ;
				L_OWG	:= NVL(x1.GI_WG_CD, x1.GR_WG_CD) ;
			ELSE	--C_PROD_ITM_SO, C_PROD_ITM_RET_SO, C_DPT_XFR_SO, C_STK_SW_SO
				--振替出庫関連は出庫部門を管理部門、入庫部門を相手部門とする
				L_MDPT	:= NVL(L_GI_DPT, L_GR_DPT) ;
				L_WG	:= NVL(x1.GI_WG_CD, x1.GR_WG_CD) ;

				L_ODPT	:= NVL(L_GR_DPT, L_GI_DPT) ;
				L_OWG	:= NVL(x1.GR_WG_CD, x1.GI_WG_CD) ;
			END IF ;

			IF	x1.AC_SLIP_TYP = C_PROD_ITM_SO THEN
				IF L_NON_PROD_FLG = C_ON THEN
					L_ASST_TYP := C_ASST1 ;
				ELSE
					L_ASST_TYP := C_ASST2 ;
				END IF ;
			ELSIF x1.AC_SLIP_TYP = C_PROD_ITM_RET_SO THEN
				IF L_ASST_FLG = C_ON OR L_NON_SLS_FLG = C_ON THEN
					L_ASST_TYP := C_ASST2 ;
				ELSE
					L_ASST_TYP := C_ASST1 ;
				END IF ;
			END IF ;

			IF L_WG IS NULL OR L_OWG IS NULL THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0018', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
				L_DPT_ERR := C_ERR ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF L_MDPT IS NULL OR L_ODPT IS NULL THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0017', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
				L_DPT_ERR := C_ERR ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.AC_SLIP_TYP = C_DPT_XFR_SO
			OR x1.AC_SLIP_TYP IN (C_PROD_ITM_SO, C_PROD_ITM_RET_SO) AND L_ASST_FLG = C_ON THEN
				--部門間移動のとき、出庫ＷＧと入庫ＷＧが同一かつ
				--出庫部門と入庫部門が同一のレコードはとりこまない
				IF (L_FIX_DPT IS NOT NULL OR L_MDPT = L_ODPT) AND L_WG = L_OWG THEN
					GOTO NEXT_LOOP ;
				END IF ;
			END IF ;

			L_TRD_RATIO := NULL ;
			IF x1.AC_SLIP_TYP = C_STK_SW_GR THEN
				IF L_TRD_FLG = C_ON THEN
					L_TRD_RATIO := MAPA_STD_COST.F_GET_STD_AMT(x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, x1.AC_DT, L_WG, L_QTY, L_CO.STK_STD_UPRI_TYP) ;
					IF L_TRD_RATIO IS NULL THEN
						--標準単価マスタから単価が取得できなかったので、振替比率を設定しません。ワーキンググループＣＤ：{1}品目：{2}
						FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0013', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, L_WG,
						MAPA_COMM.F_TO_DISP_ITM(x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3, L_PARM)) ;
					END IF ;
				END IF ;
			END IF ;

			w4 := w4 + 1 ;

			REC_w4(w4).DATA_LNO	:= MAPA_NUM.F_GET_SEQ(C_ACT_IO_IF_DATA_LNO) ;
			REC_w4(w4).CALC_CTG_CD	:= I_CALC_CTG_CD ;
			REC_w4(w4).WG_CD	:= L_WG ;
			REC_w4(w4).YM		:= x1.AC_YM ;
			REC_w4(w4).AC_DT		:= x1.AC_DT ;
			REC_w4(w4).MNG_DPT_CD	:= NVL(L_FIX_DPT, L_MDPT) ;
			REC_w4(w4).ITM_CD	:= x1.ITM_CD ;
			REC_w4(w4).ITM_SUB1	:= x1.ITM_SUB1 ;
			REC_w4(w4).ITM_SUB2	:= x1.ITM_SUB2 ;
			REC_w4(w4).ITM_SUB3	:= x1.ITM_SUB3 ;
			REC_w4(w4).LOT_NO		:= C_NULL_VAL ;
			REC_w4(w4).SUBLOT_NO		:= C_NULL_VAL ;
			REC_w4(w4).SNO1		:= C_NULL_VAL ;
			REC_w4(w4).SNO2		:= C_NULL_VAL ;
			REC_w4(w4).SNO3		:= C_NULL_VAL ;
			REC_w4(w4).SNO4		:= C_NULL_VAL ;
			IF x1.AC_SLIP_TYP IN (C_PROD_ITM_SO, C_PROD_ITM_RET_SO)
			AND L_ASST_FLG = C_OFF AND L_NON_PROD_FLG = C_OFF AND L_NON_SLS_FLG = C_OFF THEN
				--生販連携関連は実績作成処理で変換する
				REC_w4(w4).LOT_NO	:= x1.LOT_NO ;
				REC_w4(w4).SUBLOT_NO	:= x1.SUBLOT_NO ;
				REC_w4(w4).SNO1	:= x1.SNO1 ;
				REC_w4(w4).SNO2	:= x1.SNO2 ;
				REC_w4(w4).SNO3	:= x1.SNO3 ;
				REC_w4(w4).SNO4	:= x1.SNO4 ;
			ELSE
				IF x1.LOT_ACT_TYP = C_ACT2
				AND (L_LOT_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
				  OR L_LOT_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
				  OR L_LOT_USE_TYP = C_PS_USE1
				  )
				THEN
					REC_w4(w4).LOT_NO	:= x1.LOT_NO ;
				END IF ;

				IF x1.SUBLOT_ACT_TYP = C_ACT2
				AND (L_SUBLOT_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
				  OR L_SUBLOT_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
				  OR L_SUBLOT_USE_TYP = C_PS_USE1
				  )
				THEN
					REC_w4(w4).SUBLOT_NO	:= x1.SUBLOT_NO ;
				END IF ;

				IF x1.SNO1_ACT_TYP = C_ACT2
				AND (L_SNO1_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
				  OR L_SNO1_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
				  OR L_SNO1_USE_TYP = C_PS_USE1
				  )
				THEN
					REC_w4(w4).SNO1	:= x1.SNO1 ;
				END IF ;

				IF x1.SNO2_ACT_TYP = C_ACT2
				AND (L_SNO2_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
				  OR L_SNO2_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
				  OR L_SNO2_USE_TYP = C_PS_USE1
				  )
				THEN
					REC_w4(w4).SNO2	:= x1.SNO2 ;
				END IF ;

				IF x1.SNO3_ACT_TYP = C_ACT2
				AND (L_SNO3_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
				  OR L_SNO3_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
				  OR L_SNO3_USE_TYP = C_PS_USE1
				  )
				THEN
					REC_w4(w4).SNO3	:= x1.SNO3 ;
				END IF ;

				IF x1.SNO4_ACT_TYP = C_ACT2
				AND (L_SNO4_USE_TYP = C_PS_USE2 AND x1.ASST_TYP IN (C_ASST2, C_ASST3)
				  OR L_SNO4_USE_TYP = C_PS_USE3 AND x1.ASST_TYP = C_ASST1
				  OR L_SNO4_USE_TYP = C_PS_USE1
				  )
				THEN
					REC_w4(w4).SNO4	:= x1.SNO4 ;
				END IF ;
			END IF ;

			IF x1.AC_SLIP_TYP IN (C_PROD_ITM_SO, C_PROD_ITM_RET_SO) AND L_ASST_FLG = C_ON THEN
				--販売資産を生産資産として取込む場合は部門間移動として扱う
				REC_w4(w4).AC_SLIP_TYP	:= C_DPT_XFR_SO ;
			ELSE
				REC_w4(w4).AC_SLIP_TYP	:= x1.AC_SLIP_TYP ;
			END IF ;
			REC_w4(w4).AC_RSN_CD	:= x1.AC_RSN_CD ;
			REC_w4(w4).OTHER_WG_CD	:= L_OWG ;
			IF REC_w4(w4).WG_CD = REC_w4(w4).OTHER_WG_CD THEN
				REC_w4(w4).OTHER_WG_CD := NULL ;
			END IF ;
			REC_w4(w4).OTHER_DPT_CD	:= NVL(L_FIX_DPT, L_ODPT) ;
			REC_w4(w4).BP_CD	:= NULL ;
			IF L_ASST_TYP = C_ASST1 THEN
				IF L_STK_BP_FLG = C_ON THEN
					REC_w4(w4).STK_BP_CD := x1.DLV_CD ;
				ELSE
					REC_w4(w4).STK_BP_CD := NULL ;
				END IF ;
			ELSE
				REC_w4(w4).STK_BP_CD := x1.BP_CD ;
			END IF ;
			REC_w4(w4).ASST_TYP	:= L_ASST_TYP ;
			IF x1.AC_SLIP_TYP = C_PROD_ITM_SO AND L_NON_PROD_FLG = C_ON
			OR x1.AC_SLIP_TYP = C_PROD_ITM_RET_SO AND L_NON_SLS_FLG = C_ON THEN
				REC_w4(w4).QTY := -1 * L_QTY ;
			ELSE
				REC_w4(w4).QTY := L_QTY ;
			END IF ;
			REC_w4(w4).AMT		:= NULL ;
			REC_w4(w4).TRD_CUR_CD	:= NULL ;
			REC_w4(w4).TRD_CUR_AMT	:= NULL ;
			REC_w4(w4).XRATE	:= NULL ;
			IF x1.AC_SLIP_TYP = C_DPT_XFR_SO THEN
				REC_w4(w4).TRD_GRP := C_STR_TRD3 || TO_CHAR(REC_w4(w4).DATA_LNO) ;
			ELSIF x1.AC_SLIP_TYP IN (C_STK_SW_SO, C_STK_SW_GR) THEN
				REC_w4(w4).TRD_GRP := C_STR_TRD2 || x1.ACT_NO ;
			ELSE	--C_PROD_ITM_SO, C_PROD_ITM_RET_SO
				IF L_NON_PROD_FLG = C_OFF AND L_NON_SLS_FLG = C_OFF THEN
					REC_w4(w4).TRD_GRP := C_STR_TRD3 || TO_CHAR(REC_w4(w4).DATA_LNO) ;
				ELSE
					REC_w4(w4).TRD_GRP := NULL ;
				END IF ;
			END IF ;
			REC_w4(w4).TRD_RATIO	:= L_TRD_RATIO ;
			REC_w4(w4).ALC_AC_CD	:= NULL ;
			REC_w4(w4).ALC_AMT_FLG	:= C_OFF ;
			REC_w4(w4).ALC_WG_CD	:= NULL ;
			REC_w4(w4).ALC_DPT_CD	:= NULL ;
			REC_w4(w4).ALC_LOC_CD	:= NULL ;
			REC_w4(w4).ALC_OPER_CD	:= NULL ;
			REC_w4(w4).ALC_BP_CD	:= NULL ;
			REC_w4(w4).ALC_CTG_CD	:= NULL ;
			REC_w4(w4).ALC_ITM_CD	:= NULL ;
			REC_w4(w4).ALC_ITM_SUB1	:= NULL ;
			REC_w4(w4).ALC_ITM_SUB2	:= NULL ;
			REC_w4(w4).ALC_ITM_SUB3	:= NULL ;
			REC_w4(w4).ALC_LOT_NO	:= NULL ;
			REC_w4(w4).ALC_SUBLOT_NO	:= NULL ;
			REC_w4(w4).ALC_SNO1	:= NULL ;
			REC_w4(w4).ALC_SNO2	:= NULL ;
			REC_w4(w4).ALC_SNO3	:= NULL ;
			REC_w4(w4).ALC_SNO4	:= NULL ;
			REC_w4(w4).ALC_ITM_MFG_INST_NO	:= NULL ;
			REC_w4(w4).REC_EVAL_TYP	:= NULL ;
			REC_w4(w4).NO_PLN_FLG	:= C_OFF ;
			REC_w4(w4).NO_ITM_INFO_FLG	:= C_OFF ;
			REC_w4(w4).ZERO_EFFECT_FLG := C_OFF ;
			REC_w4(w4).SLIP_NO	:= x1.SLIP_NO ;
			REC_w4(w4).SLIP_SEQ_NO	:= x1.SLIP_SEQ_NO ;
			REC_w4(w4).RMRKS	:= x1.TRD_D_RMRKS ;
			REC_w4(w4).SUB_CHAR1	:= NULL ;
			REC_w4(w4).SUB_CHAR2	:= NULL ;
			REC_w4(w4).SUB_CHAR3	:= NULL ;

			GOTO NEXT_LOOP ;
		END IF ;

		--売上実績関連の取込
		IF x1.AC_SLIP_TYP IN (C_SLS, C_SLS_RET, C_SLS_DSCNT, C_SLS_XTRA)
		THEN
			IF L_NON_SLS_FLG = C_OFF THEN
				NULL ;
			ELSE
				GOTO NEXT_LOOP ;
			END IF ;

			IF x1.AC_SLIP_TYP IN (C_SLS_DSCNT, C_SLS_XTRA) THEN
				--負担部門を管理部門とする
				L_MDPT	:= NVL(L_BD_DPT, L_SLS_DPT) ;
				L_WG	:= x1.BD_WG_CD ;

				IF x1.AC_SLIP_TYP = C_SLS_DSCNT THEN
					--売上値引は符号を反転させる
					L_SIGN	:= -1 ;
				ELSE
					--符号はそのまま
					L_SIGN	:= 1 ;
				END IF ;
			ELSIF x1.AC_SLIP_TYP = C_SLS_RET THEN
				--入庫部門を管理部門とする
				L_MDPT	:= NVL(L_GR_DPT, NVL(L_BD_DPT, L_SLS_DPT)) ;
				L_WG	:= NVL(x1.GR_WG_CD, x1.BD_WG_CD) ;

				--売上返品は符号を反転させる
				L_SIGN	:= -1 ;
			ELSE
				--出庫部門を管理部門とする
				L_MDPT	:= NVL(L_GI_DPT, NVL(L_BD_DPT, L_SLS_DPT)) ;
				L_WG	:= NVL(x1.GI_WG_CD, x1.BD_WG_CD) ;

				--符号はそのまま
				L_SIGN	:= 1 ;
			END IF ;

			-- 値引品目かつ売上、売上返品は符号を反転する
			IF x1.DSCNT_ITM_FLG = C_ON AND x1.AC_SLIP_TYP IN (C_SLS, C_SLS_RET) THEN
				L_SIGN := - L_SIGN ;
			END IF ;

			L_ODPT	:= L_SLS_DPT ;

			IF L_WG IS NULL THEN
				IF x1.AC_SLIP_TYP IN (C_SLS_DSCNT, C_SLS_XTRA) THEN
					FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0020', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
				ELSE
					FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0018', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
					L_DPT_ERR := C_ERR ;
				END IF ;
				GOTO NEXT_LOOP ;
			END IF ;

			IF L_MDPT IS NULL OR L_ODPT IS NULL THEN
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0017', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, x1.SLIP_NO, x1.SLIP_SEQ_NO) ;
				L_DPT_ERR := C_ERR ;
				GOTO NEXT_LOOP ;
			END IF ;

			w5 := w5 + 1 ;

			REC_w5(w5).DATA_LNO	:= MAPA_NUM.F_GET_SEQ(C_ACT_SLS_IF_DATA_LNO) ;
			REC_w5(w5).CALC_CTG_CD	:= I_CALC_CTG_CD ;
			REC_w5(w5).WG_CD	:= L_WG ;
			REC_w5(w5).YM		:= x1.AC_YM ;
			REC_w5(w5).AC_DT		:= x1.AC_DT ;
			REC_w5(w5).MNG_DPT_CD	:= NVL(L_FIX_DPT, L_MDPT) ;
			REC_w5(w5).ITM_CD	:= x1.ITM_CD ;
			REC_w5(w5).ITM_SUB1	:= x1.ITM_SUB1 ;
			REC_w5(w5).ITM_SUB2	:= x1.ITM_SUB2 ;
			REC_w5(w5).ITM_SUB3	:= x1.ITM_SUB3 ;

			IF L_LOT_USE_TYP <> C_PS_USE2 AND x1.LOT_ACT_TYP = C_ACT2 THEN
				REC_w5(w5).LOT_NO	:= x1.LOT_NO ;
			ELSE
				REC_w5(w5).LOT_NO	:= C_NULL_VAL ;
			END IF ;

			IF L_SUBLOT_USE_TYP <> C_PS_USE2 AND x1.SUBLOT_ACT_TYP = C_ACT2 THEN
				REC_w5(w5).SUBLOT_NO	:= x1.SUBLOT_NO ;
			ELSE
				REC_w5(w5).SUBLOT_NO	:= C_NULL_VAL ;
			END IF ;

			IF L_SNO1_USE_TYP <> C_PS_USE2 AND x1.SNO1_ACT_TYP = C_ACT2 THEN
				REC_w5(w5).SNO1	:= x1.SNO1 ;
			ELSE
				REC_w5(w5).SNO1	:= C_NULL_VAL ;
			END IF ;

			IF L_SNO2_USE_TYP <> C_PS_USE2 AND x1.SNO2_ACT_TYP = C_ACT2 THEN
				REC_w5(w5).SNO2	:= x1.SNO2 ;
			ELSE
				REC_w5(w5).SNO2	:= C_NULL_VAL ;
			END IF ;

			IF L_SNO3_USE_TYP <> C_PS_USE2 AND x1.SNO3_ACT_TYP = C_ACT2 THEN
				REC_w5(w5).SNO3	:= x1.SNO3 ;
			ELSE
				REC_w5(w5).SNO3	:= C_NULL_VAL ;
			END IF ;

			IF L_SNO4_USE_TYP <> C_PS_USE2 AND x1.SNO4_ACT_TYP = C_ACT2 THEN
				REC_w5(w5).SNO4	:= x1.SNO4 ;
			ELSE
				REC_w5(w5).SNO4	:= C_NULL_VAL ;
			END IF ;

			REC_w5(w5).AC_SLIP_TYP	:= x1.AC_SLIP_TYP ;
			REC_w5(w5).AC_RSN_CD	:= x1.AC_RSN_CD ;
			REC_w5(w5).ASST_TYP	:= L_ASST_TYP ;
			REC_w5(w5).QTY		:= L_QTY * L_SIGN ;
			REC_w5(w5).AMT		:= x1.AMT * L_SIGN ;
			REC_w5(w5).TRD_CUR_CD	:= x1.TRD_CUR_CD ;
			REC_w5(w5).TRD_CUR_AMT	:= x1.TRD_CUR_AMT * L_SIGN ;
			REC_w5(w5).XRATE	:= x1.XRATE ;
			REC_w5(w5).CST_CD	:= x1.CST_CD ;
			REC_w5(w5).DLV_CD	:= x1.DLV_CD ;
			REC_w5(w5).SLS_DPT_CD	:= L_ODPT ;
			REC_w5(w5).SLS_USR_CD	:= x1.SLS_USR_CD ;
			REC_w5(w5).SLO_NO	:= x1.SLO_NO ;
			REC_w5(w5).IV_NO	:= x1.IV_NO ;
			--納品先としてのみ使用するコードを納品先として扱う
			IF L_STK_BP_FLG = C_ON AND x1.AC_SLIP_TYP = C_SLS AND x1.DLV_FLG = C_ON THEN
				REC_w5(w5).STK_BP_CD := x1.DLV_CD ;
			ELSE
				REC_w5(w5).STK_BP_CD := NULL ;
			END IF ;
			REC_w5(w5).ALC_DPT_CD	:= L_ODPT ;
			REC_w5(w5).DEST_CD1	:= x1.DEST_CD1 ;
			REC_w5(w5).DEST_CD2	:= x1.DEST_CD2 ;
			REC_w5(w5).DEST_CD3	:= x1.DEST_CD3 ;
			REC_w5(w5).COST_SLS_CD1	:= NULL ;
			REC_w5(w5).COST_SLS_CD2	:= NULL ;
			REC_w5(w5).COST_SLS_CD3	:= NULL ;
			REC_w5(w5).COST_SLS_CD4	:= NULL ;
			REC_w5(w5).COST_SLS_CD5	:= NULL ;
			REC_w5(w5).ALC_VAL1	:= NULL ;
			REC_w5(w5).ALC_VAL2	:= NULL ;
			REC_w5(w5).ALC_VAL3	:= NULL ;
			REC_w5(w5).ALC_VAL4	:= NULL ;
			REC_w5(w5).ALC_VAL5	:= NULL ;
			REC_w5(w5).REC_EVAL_TYP	:= NULL ;
			REC_w5(w5).NO_PLN_FLG	:= C_OFF ;
			REC_w5(w5).NO_ITM_INFO_FLG	:= C_OFF ;
			REC_w5(w5).NO_EVAL_FLG	:= C_OFF ;
			REC_w5(w5).ZERO_EFFECT_FLG := C_OFF ;
			REC_w5(w5).SLIP_NO	:= x1.SLIP_NO ;
			REC_w5(w5).SLIP_SEQ_NO	:= x1.SLIP_SEQ_NO ;
			REC_w5(w5).RMRKS	:= x1.TRD_D_RMRKS ;
			REC_w5(w5).SUB_CHAR1	:= NULL ;
			REC_w5(w5).SUB_CHAR2	:= NULL ;
			REC_w5(w5).SUB_CHAR3	:= NULL ;

			P_COL_PROC_SLS() ;
			GOTO NEXT_LOOP ;
		END IF ;

		<<NEXT_LOOP>>
			NULL ;

		IF L_DPT_ERR = C_ERR THEN
			GOTO NEXT_LOOP_ERR ;
		END IF ;

		d1 := d1 + 1 ;
		REC_ID(d1) := x1.ROW_ID ;

		IF w1 + w2 + w3 + w4 + w5 + w6 + w7 > C_MAX_CNT THEN
			P_INS_TRAN() ;
		END IF ;

		L_REC_CNT := L_REC_CNT + 1 ;

		GOTO SKIP_ERR ;

		<<NEXT_LOOP_ERR>>
			NULL ;

		L_RSLT := C_ERR ;

		<<SKIP_ERR>>
			NULL ;

	END LOOP ;

	P_INS_TRAN() ;

	REC_CHK_ITM.DELETE ;
	REC_CHK_OPER.DELETE ;

	FOR w IN (
		SELECT
			t.CALC_CTG_CD, t.WG_CD, t.YM, t.AC_DT,
			t.PAR_ITM_CD, t.PAR_ITM_SUB1, t.PAR_ITM_SUB2, t.PAR_ITM_SUB3,
			t.PAR_LOT_NO, t.PAR_SUBLOT_NO, t.PAR_SNO1, t.PAR_SNO2, t.PAR_SNO3, t.PAR_SNO4,
			t.ITM_MFG_INST_NO,
			t.MFG_ACT_NO,
			t.OPER_ACT_NO,
			t.LOC_CD, t.STR_LN_CD,
			t.MNG_DPT_CD,
			t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
			t.LOT_NO, t.SUBLOT_NO, t.SNO1, t.SNO2, t.SNO3, t.SNO4,
			t.AC_SLIP_TYP, t.AC_RSN_CD,
			t.STK_BP_CD, t.ASST_TYP,
			SUM(t.QTY)	QTY,
			SUM(t.AMT)	AMT,
			t.TRD_CUR_CD,
			SUM(t.TRD_CUR_AMT)	TRD_CUR_AMT,
			t.XRATE, t.REC_EVAL_TYP, t.EXPNS_CD,
			MAX(t.SLIP_NO)	SLIP_NO,
			MAX(t.SLIP_SEQ_NO)	SLIP_SEQ_NO,
			MAX(t.RMRKS)	RMRKS
			--, t.SUB_CHAR1, t.SUB_CHAR2, t.SUB_CHAR3
		FROM	MGW_ACT_INPT_IF t
		WHERE	0=0
		GROUP BY t.CALC_CTG_CD, t.WG_CD, t.YM, t.AC_DT,
			t.PAR_ITM_CD, t.PAR_ITM_SUB1, t.PAR_ITM_SUB2, t.PAR_ITM_SUB3,
			t.PAR_LOT_NO, t.PAR_SUBLOT_NO, t.PAR_SNO1, t.PAR_SNO2, t.PAR_SNO3, t.PAR_SNO4,
			t.ITM_MFG_INST_NO,
			t.MFG_ACT_NO,
			t.OPER_ACT_NO,
			t.LOC_CD, t.STR_LN_CD,
			t.MNG_DPT_CD,
			t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
			t.LOT_NO, t.SUBLOT_NO, t.SNO1, t.SNO2, t.SNO3, t.SNO4,
			t.AC_SLIP_TYP, t.AC_RSN_CD,
			t.STK_BP_CD, t.ASST_TYP,
			t.TRD_CUR_CD, t.XRATE,
			t.REC_EVAL_TYP, t.EXPNS_CD
			--, t.SUB_CHAR1, t.SUB_CHAR2, t.SUB_CHAR3
		)
	LOOP
		IF NVL(w.QTY, 0) = 0 AND NVL(w.AMT, 0) = 0 AND NVL(w.TRD_CUR_AMT, 0) = 0 THEN
			GOTO NEXT_LOOP_W ;
		END IF ;

		t3 := t3 + 1 ;

		TMP_w3(t3).CALC_CTG_CD	:= w.CALC_CTG_CD ;
		TMP_w3(t3).WG_CD	:= w.WG_CD ;
		TMP_w3(t3).YM		:= w.YM ;
		TMP_w3(t3).AC_DT		:= w.AC_DT ;
		TMP_w3(t3).PAR_ITM_CD	:= w.PAR_ITM_CD ;
		TMP_w3(t3).PAR_ITM_SUB1	:= w.PAR_ITM_SUB1 ;
		TMP_w3(t3).PAR_ITM_SUB2	:= w.PAR_ITM_SUB2 ;
		TMP_w3(t3).PAR_ITM_SUB3	:= w.PAR_ITM_SUB3 ;
		TMP_w3(t3).PAR_LOT_NO		:= w.PAR_LOT_NO ;
		TMP_w3(t3).PAR_SUBLOT_NO	:= w.PAR_SUBLOT_NO ;
		TMP_w3(t3).PAR_SNO1		:= w.PAR_SNO1 ;
		TMP_w3(t3).PAR_SNO2		:= w.PAR_SNO2 ;
		TMP_w3(t3).PAR_SNO3		:= w.PAR_SNO3 ;
		TMP_w3(t3).PAR_SNO4		:= w.PAR_SNO4 ;
		TMP_w3(t3).ITM_MFG_INST_NO := w.ITM_MFG_INST_NO ;
		TMP_w3(t3).MFG_ACT_NO := w.MFG_ACT_NO ;
		TMP_w3(t3).OPER_ACT_NO	:= w.OPER_ACT_NO ;
		TMP_w3(t3).LOC_CD	:= w.LOC_CD ;
		TMP_w3(t3).STR_LN_CD	:= w.STR_LN_CD ;
		TMP_w3(t3).MNG_DPT_CD	:= w.MNG_DPT_CD ;
		TMP_w3(t3).ITM_CD	:= w.ITM_CD ;
		TMP_w3(t3).ITM_SUB1	:= w.ITM_SUB1 ;
		TMP_w3(t3).ITM_SUB2	:= w.ITM_SUB2 ;
		TMP_w3(t3).ITM_SUB3	:= w.ITM_SUB3 ;
		TMP_w3(t3).LOT_NO		:= w.LOT_NO ;
		TMP_w3(t3).SUBLOT_NO	:= w.SUBLOT_NO ;
		TMP_w3(t3).SNO1		:= w.SNO1 ;
		TMP_w3(t3).SNO2		:= w.SNO2 ;
		TMP_w3(t3).SNO3		:= w.SNO3 ;
		TMP_w3(t3).SNO4		:= w.SNO4 ;
		TMP_w3(t3).AC_SLIP_TYP	:= w.AC_SLIP_TYP ;
		TMP_w3(t3).AC_RSN_CD	:= w.AC_RSN_CD ;
		TMP_w3(t3).STK_BP_CD	:= w.STK_BP_CD ;
		TMP_w3(t3).ASST_TYP	:= w.ASST_TYP ;
		TMP_w3(t3).QTY		:= w.QTY ;
		TMP_w3(t3).AMT		:= w.AMT ;
		TMP_w3(t3).TRD_CUR_CD	:= w.TRD_CUR_CD ;
		TMP_w3(t3).TRD_CUR_AMT	:= w.TRD_CUR_AMT ;
		TMP_w3(t3).XRATE	:= w.XRATE ;
		TMP_w3(t3).REC_EVAL_TYP	:= w.REC_EVAL_TYP ;
		TMP_w3(t3).EXPNS_CD	:= w.EXPNS_CD ;
		TMP_w3(t3).SLIP_NO	:= w.SLIP_NO ;
		TMP_w3(t3).SLIP_SEQ_NO	:= w.SLIP_SEQ_NO ;
		TMP_w3(t3).RMRKS	:= w.RMRKS ;
		TMP_w3(t3).SUB_CHAR1	:= NULL ;
		TMP_w3(t3).SUB_CHAR2	:= NULL ;
		TMP_w3(t3).SUB_CHAR3	:= NULL ;

		<<NEXT_LOOP_W>>
			NULL ;

	END LOOP ;

	DELETE MGW_ACT_INPT_IF t ;

	P_INS_TRAN() ;

	FOR w1 IN (
		SELECT	DISTINCT
			w.PAR_ITM_CD,
			w.PAR_ITM_SUB1,
			w.PAR_ITM_SUB2,
			w.PAR_ITM_SUB3,
			w.CALC_CTG_CD,
			w.WG_CD,
			w.MNG_DPT_CD,
			w.PAR_LOT_NO, w.PAR_SUBLOT_NO, w.PAR_SNO1, w.PAR_SNO2, w.PAR_SNO3, w.PAR_SNO4,
			w.LOC_CD, w.STR_LN_CD, m.SPPL_CD
		FROM	MGW_ACT_INPT_IF w, MAM_LOC m
		WHERE	0=0
		AND	w.LOC_CD = m.LOC_CD(+)
		)
	LOOP
		SELECT	MAX(t.ITM_MFG_INST_NO)
		INTO	L_ITM_MFG_INST_NO
		FROM	MGT_ITM_MFG_INST t
		WHERE	0=0
		AND	t.ITM_MFG_INST_NO LIKE C_STR_NO || '%'
		AND	LENGTH(t.ITM_MFG_INST_NO) = C_ITM_MFG_INST_LENGTH + LENGTH(C_STR_NO)
		AND	t.MFG_ACT_NO = C_NULL_VAL
		AND	t.ITM_CD = w1.PAR_ITM_CD
		AND	t.ITM_SUB1 = w1.PAR_ITM_SUB1
		AND	t.ITM_SUB2 = w1.PAR_ITM_SUB2
		AND	t.ITM_SUB3 = w1.PAR_ITM_SUB3
		AND	t.CALC_CTG_CD = w1.CALC_CTG_CD
		AND	t.WG_CD = w1.WG_CD
		AND	t.MNG_DPT_CD = w1.MNG_DPT_CD
		AND	t.LOT_NO = w1.PAR_LOT_NO
		AND	t.SUBLOT_NO = w1.PAR_SUBLOT_NO
		AND	t.SNO1 = w1.PAR_SNO1
		AND	t.SNO2 = w1.PAR_SNO2
		AND	t.SNO3 = w1.PAR_SNO3
		AND	t.SNO4 = w1.PAR_SNO4
		AND	EXISTS (
				SELECT	'X'
				FROM	MGT_ACT_INPT_IF x
				WHERE	0=0
				AND	x.CALC_CTG_CD = t.CALC_CTG_CD
				AND	x.YM = I_YM
				AND	x.PAR_ITM_CD = t.ITM_CD
				AND	x.PAR_ITM_SUB1 = t.ITM_SUB1
				AND	x.PAR_ITM_SUB2 = t.ITM_SUB2
				AND	x.PAR_ITM_SUB3 = t.ITM_SUB3
				AND	x.ITM_MFG_INST_NO = t.ITM_MFG_INST_NO
				AND	x.MFG_ACT_NO = t.MFG_ACT_NO
				AND	x.LOC_CD = w1.LOC_CD
				AND	x.STR_LN_CD = w1.STR_LN_CD
				)
		;

		IF L_ITM_MFG_INST_NO IS NULL THEN
			L_ITM_MFG_INST_NO := C_STR_NO || LPAD(MAPA_NUM.F_GET_SEQ(C_ITM_MFG_INST), C_ITM_MFG_INST_LENGTH, '0') ;

			w6 := w6 + 1 ;

			REC_w6(w6).CALC_CTG_CD	:= w1.CALC_CTG_CD ;
			REC_w6(w6).ITM_CD	:= w1.PAR_ITM_CD ;
			REC_w6(w6).ITM_SUB1	:= w1.PAR_ITM_SUB1 ;
			REC_w6(w6).ITM_SUB2	:= w1.PAR_ITM_SUB2 ;
			REC_w6(w6).ITM_SUB3	:= w1.PAR_ITM_SUB3 ;
			REC_w6(w6).ITM_MFG_INST_NO := L_ITM_MFG_INST_NO ;
			REC_w6(w6).MFG_ACT_NO := C_NULL_VAL ;
			REC_w6(w6).WG_CD	:= w1.WG_CD ;
			REC_w6(w6).MNG_DPT_CD	:= w1.MNG_DPT_CD ;
			REC_w6(w6).LOT_NO		:= w1.PAR_LOT_NO ;
			REC_w6(w6).SUBLOT_NO	:= w1.PAR_SUBLOT_NO ;
			REC_w6(w6).SNO1		:= w1.PAR_SNO1 ;
			REC_w6(w6).SNO2		:= w1.PAR_SNO2 ;
			REC_w6(w6).SNO3		:= w1.PAR_SNO3 ;
			REC_w6(w6).SNO4		:= w1.PAR_SNO4 ;
			REC_w6(w6).SPPL_CD	:= w1.SPPL_CD ;
			REC_w6(w6).PO_NO	:= NULL ;
			REC_w6(w6).SLO_NO	:= NULL ;
			REC_w6(w6).IV_NO	:= NULL ;
			REC_w6(w6).ASST_TYP	:= C_ASST2 ;
			REC_w6(w6).QTY		:= 0 ;
			REC_w6(w6).SCHD_ST_DT	:= NULL ;
			REC_w6(w6).SCHD_END_DT	:= NULL ;
			REC_w6(w6).ACT_ST_DT	:= NULL ;
			REC_w6(w6).ACT_END_DT	:= NULL ;
			REC_w6(w6).RMRKS	:= NULL ;
			REC_w6(w6).SUB_CHAR1	:= NULL ;
			REC_w6(w6).SUB_CHAR2	:= NULL ;
			REC_w6(w6).SUB_CHAR3	:= NULL ;
			P_COL_PROC_ITM() ;
		END IF ;

		FOR w2 IN (
			SELECT	w.*
			FROM	MGW_ACT_INPT_IF w
			WHERE	0=0
			AND	w.PAR_ITM_CD = w1.PAR_ITM_CD
			AND	w.PAR_ITM_SUB1 = w1.PAR_ITM_SUB1
			AND	w.PAR_ITM_SUB2 = w1.PAR_ITM_SUB2
			AND	w.PAR_ITM_SUB3 = w1.PAR_ITM_SUB3
			AND	w.CALC_CTG_CD = w1.CALC_CTG_CD
			AND	w.MNG_DPT_CD = w1.MNG_DPT_CD
			AND	w.PAR_LOT_NO = w1.PAR_LOT_NO
			AND	w.PAR_SUBLOT_NO = w1.PAR_SUBLOT_NO
			AND	w.PAR_SNO1 = w1.PAR_SNO1
			AND	w.PAR_SNO2 = w1.PAR_SNO2
			AND	w.PAR_SNO3 = w1.PAR_SNO3
			AND	w.PAR_SNO4 = w1.PAR_SNO4
			AND	w.LOC_CD = w1.LOC_CD
			AND	w.STR_LN_CD = w1.STR_LN_CD
			)
		LOOP
			w3 := w3 + 1 ;

			REC_w3(w3).DATA_LNO	:= MAPA_NUM.F_GET_SEQ(C_ACT_INPT_IF_DATA_LNO) ;
			REC_w3(w3).CALC_CTG_CD	:= w2.CALC_CTG_CD ;
			REC_w3(w3).WG_CD	:= w2.WG_CD ;
			REC_w3(w3).YM		:= w2.YM ;
			REC_w3(w3).AC_DT		:= w2.AC_DT ;
			REC_w3(w3).PAR_ITM_CD	:= w2.PAR_ITM_CD ;
			REC_w3(w3).PAR_ITM_SUB1	:= w2.PAR_ITM_SUB1 ;
			REC_w3(w3).PAR_ITM_SUB2	:= w2.PAR_ITM_SUB2 ;
			REC_w3(w3).PAR_ITM_SUB3	:= w2.PAR_ITM_SUB3 ;
			REC_w3(w3).ITM_MFG_INST_NO := L_ITM_MFG_INST_NO ;
			REC_w3(w3).MFG_ACT_NO	:= w2.MFG_ACT_NO ;
			REC_w3(w3).OPER_ACT_NO	:= w2.OPER_ACT_NO ;
			REC_w3(w3).LOC_CD	:= w2.LOC_CD ;
			REC_w3(w3).STR_LN_CD	:= w2.STR_LN_CD ;
			REC_w3(w3).MNG_DPT_CD	:= w2.MNG_DPT_CD ;
			REC_w3(w3).ITM_CD	:= w2.ITM_CD ;
			REC_w3(w3).ITM_SUB1	:= w2.ITM_SUB1 ;
			REC_w3(w3).ITM_SUB2	:= w2.ITM_SUB2 ;
			REC_w3(w3).ITM_SUB3	:= w2.ITM_SUB3 ;
			REC_w3(w3).LOT_NO		:= w2.LOT_NO ;
			REC_w3(w3).SUBLOT_NO	:= w2.SUBLOT_NO ;
			REC_w3(w3).SNO1		:= w2.SNO1 ;
			REC_w3(w3).SNO2		:= w2.SNO2 ;
			REC_w3(w3).SNO3		:= w2.SNO3 ;
			REC_w3(w3).SNO4		:= w2.SNO4 ;
			REC_w3(w3).AC_SLIP_TYP	:= w2.AC_SLIP_TYP ;
			REC_w3(w3).AC_RSN_CD	:= w2.AC_RSN_CD ;
			REC_w3(w3).STK_BP_CD	:= w2.STK_BP_CD ;
			REC_w3(w3).ASST_TYP	:= w2.ASST_TYP ;
			REC_w3(w3).QTY		:= w2.QTY ;
			REC_w3(w3).AMT		:= w2.AMT ;
			REC_w3(w3).TRD_CUR_CD	:= w2.TRD_CUR_CD ;
			REC_w3(w3).TRD_CUR_AMT	:= w2.TRD_CUR_AMT ;
			REC_w3(w3).XRATE	:= w2.XRATE ;
			REC_w3(w3).REC_EVAL_TYP	:= w2.REC_EVAL_TYP ;
			REC_w3(w3).EXPNS_CD	:= w2.EXPNS_CD ;
			REC_w3(w3).NO_PLN_FLG	:= C_OFF ;
			REC_w3(w3).NO_ITM_INFO_FLG	:= C_OFF ;
			REC_w3(w3).ZERO_EFFECT_FLG := C_OFF ;
			REC_w3(w3).SLIP_NO	:= w2.SLIP_NO ;
			REC_w3(w3).SLIP_SEQ_NO	:= w2.SLIP_SEQ_NO ;
			REC_w3(w3).RMRKS	:= w2.RMRKS ;
			REC_w3(w3).SUB_CHAR1	:= NULL ;
			REC_w3(w3).SUB_CHAR2	:= NULL ;
			REC_w3(w3).SUB_CHAR3	:= NULL ;
		END LOOP ;
	END LOOP ;

	P_INS_TRAN() ;

	IF t6 > 0 THEN
		G_MFG_INST_CNT := G_MFG_INST_CNT + t6 ;

		BEGIN
			FORALL t IN 1..t6
			SAVE EXCEPTIONS
			INSERT INTO MGT_ITM_MFG_INST VALUES TMP_w6(t) ;
		EXCEPTION
		WHEN BULK_ERROR THEN
			FOR i IN 1..SQL%BULK_EXCEPTIONS.COUNT LOOP
				-- 既存のデータを優先するので一意制約はエラーとしない
				IF SQL%BULK_EXCEPTIONS(i).ERROR_CODE = 1 THEN
					G_MFG_INST_CNT := G_MFG_INST_CNT - 1 ;
				ELSE
					RAISE ;
				END IF ;
			END LOOP ;
		END ;
	END IF ;

	IF u6 > 0 THEN
		FORALL u IN 1..u6
			DELETE MGT_ITM_MFG_INST t
			WHERE 0=0
			AND t.CALC_CTG_CD = UPD_w6(u).CALC_CTG_CD
			AND t.ITM_CD = UPD_w6(u).ITM_CD
			AND t.ITM_SUB1 = UPD_w6(u).ITM_SUB1
			AND t.ITM_SUB2 = UPD_w6(u).ITM_SUB2
			AND t.ITM_SUB3 = UPD_w6(u).ITM_SUB3
			AND t.ITM_MFG_INST_NO = UPD_w6(u).ITM_MFG_INST_NO
			AND t.MFG_ACT_NO = UPD_w6(u).MFG_ACT_NO
			AND t.UPD_SRV_REQ_NO = FCPA_CONTEXT.F_GET_PROCESSID
			;
		G_MFG_INST_CNT := G_MFG_INST_CNT - SQL%ROWCOUNT ;
		FORALL u IN 1..u6
			DELETE MGT_ITM_MFG_INST t
			WHERE 0=0
			AND t.CALC_CTG_CD = UPD_w6(u).CALC_CTG_CD
			AND t.ITM_CD = UPD_w6(u).ITM_CD
			AND t.ITM_SUB1 = UPD_w6(u).ITM_SUB1
			AND t.ITM_SUB2 = UPD_w6(u).ITM_SUB2
			AND t.ITM_SUB3 = UPD_w6(u).ITM_SUB3
			AND t.ITM_MFG_INST_NO = UPD_w6(u).ITM_MFG_INST_NO
			AND t.MFG_ACT_NO = UPD_w6(u).MFG_ACT_NO
			;
		G_MFG_INST_CNT := G_MFG_INST_CNT + u6 ;
		FORALL u IN 1..u6
			INSERT INTO MGT_ITM_MFG_INST VALUES UPD_w6(u) ;
	END IF ;

	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0022', L_REC_CNT) ;
	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0026', G_MFG_INST_CNT) ;
	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0027', G_INST_OPER_CNT) ;
	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0028', G_MFG_CNT) ;
	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0029', G_PURC_CNT) ;
	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0030', G_INPT_CNT) ;
	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0031', G_IO_CNT) ;
	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0032', G_SLS_CNT) ;

	<<SKIP_TRAN>>
		NULL ;

	COMMIT ;

	--作業実績情報の取込
	IF I_WK = C_OFF OR L_NON_PROD_FLG = C_ON THEN
		GOTO SKIP_WK ;
	END IF ;

	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0038') ;

	SELECT	COUNT(*)
	INTO	L_REC_CNT
	FROM	MGVT_MST_WK_ACT t
	WHERE	0=0
	AND	t.AC_DT BETWEEN L_ST_DT AND L_END_DT
	AND	t.WK_COST <> 0
	;

	IF L_REC_CNT = 0 THEN
		FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0023', L_REC_CNT) ;
		GOTO SKIP_WK ;
	END IF ;

	--部門のチェック
	L_TMP_DT := NULL ;
	REC_DPT.DELETE ;
	L_CHK_ERR := C_OFF ;
	FOR x2 IN (
		SELECT
			t.AC_DT,
			t.DPT_CD
		FROM	MGVT_MST_WK_ACT t
		WHERE	0=0
		AND	t.AC_DT BETWEEN L_ST_DT AND L_END_DT
		AND	t.ITM_MFG_INST_NO IS NOT NULL
		AND	t.WK_COST <> 0
		AND	(
			L_ITM_OUT_CNT = 0
			OR
			NOT EXISTS (
				SELECT	'X'
				FROM	MAM_COST_ITM_OUT m
				WHERE	0=0
				AND	m.ITM_CD = t.ITM_CD
				AND	m.ITM_SUB1 = t.ITM_SUB1
				AND	m.ITM_SUB2 = t.ITM_SUB2
				AND	m.ITM_SUB3 = t.ITM_SUB3
				AND	m.YM <= I_YM
				)
			)
		UNION
		SELECT
			t.AC_DT,
			t.DPT_CD
		FROM	MGVT_MST_WK_ACT t
		WHERE	0=0
		AND	t.AC_DT BETWEEN L_ST_DT AND L_END_DT
		AND	t.ITM_MFG_INST_NO IS NULL
		AND	(t.ITM_CD IS NULL OR t.LOC_CD IS NULL)
		AND	t.WK_COST <> 0
		UNION
		SELECT
			t.AC_DT,
			t.DPT_CD
		FROM	MGVT_MST_WK_ACT t
		WHERE	0=0
		AND	t.AC_DT BETWEEN L_ST_DT AND L_END_DT
		AND	t.ITM_MFG_INST_NO IS NULL
		AND	t.ITM_CD IS NOT NULL
		AND	t.LOC_CD IS NOT NULL
		AND	t.WK_COST <> 0
		AND	(
			L_ITM_OUT_CNT = 0
			OR
			NOT EXISTS (
				SELECT	'X'
				FROM	MAM_COST_ITM_OUT m
				WHERE	0=0
				AND	m.ITM_CD = t.ITM_CD
				AND	m.ITM_SUB1 = t.ITM_SUB1
				AND	m.ITM_SUB2 = t.ITM_SUB2
				AND	m.ITM_SUB3 = t.ITM_SUB3
				AND	m.YM <= I_YM
				)
			)
		)
	LOOP
		IF L_TMP_DT IS NULL OR L_TMP_DT <> x2.AC_DT THEN
			REC_DPT.DELETE ;
			L_TMP_DT := x2.AC_DT ;
		END IF ;

		MGPA_COST_IF.P_GET_DPT(
			MAPA_DPT.F_GET_DPT_CD_NE(x2.DPT_CD, x2.AC_DT),
			L_FIX_DPT,
			x2.AC_DT,
			REC_DPT,
			L_MDPT,
			C_ON) ;

		IF L_MDPT IS NULL THEN
			L_RSLT := C_ERR ;
			L_CHK_ERR := C_ON ;
		END IF ;
	END LOOP ;

	IF L_CHK_ERR = C_ON THEN
		GOTO SKIP_WK ;
	END IF ;

	--取得するときは年月ごとに再取り込みを行う
	DELETE	MGT_ITM_MFG_INST t
	WHERE	0=0
	AND	t.ITM_MFG_INST_NO LIKE C_STR_NO2 || '%'
	AND	LENGTH(t.ITM_MFG_INST_NO) = C_ITM_MFG_INST_LENGTH + LENGTH(C_STR_NO2)
	AND	t.MFG_ACT_NO = C_NULL_VAL
	AND	t.CALC_CTG_CD = I_CALC_CTG_CD
	AND	EXISTS (
			SELECT	'X'
			FROM	MGT_ACT_INST_WK_IF w
			WHERE	0=0
			AND	w.ITM_CD = t.ITM_CD
			AND	w.ITM_SUB1 = t.ITM_SUB1
			AND	w.ITM_SUB2 = t.ITM_SUB2
			AND	w.ITM_SUB3 = t.ITM_SUB3
			AND	w.ITM_MFG_INST_NO = t.ITM_MFG_INST_NO
			AND	w.MFG_ACT_NO = t.MFG_ACT_NO
			AND	w.CALC_CTG_CD = t.CALC_CTG_CD
			AND	w.YM = I_YM
			AND (I_RERUN = C_ON OR w.SCM_IF_FLG = C_ON)
			)
	;
	DELETE MGT_ACT_INST_WK_IF t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG_CD AND (I_RERUN = C_ON OR t.SCM_IF_FLG = C_ON) ;
	DELETE MGT_ACT_OTHER_WK_IF t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG_CD AND (I_RERUN = C_ON OR t.SCM_IF_FLG = C_ON) ;

	--指図工数実績
	INSERT INTO MGT_ACT_INST_WK_IF (
		DATA_LNO,
		CALC_CTG_CD, WG_CD,
		YM,
		AC_DT,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		ITM_MFG_INST_NO,
		MFG_ACT_NO,
		OPER_ACT_NO,
		LOC_CD, STR_LN_CD,
		WK_COST_CD,
		WK_RSN_CD,
		WK_COST,
		NO_PLN_FLG, NO_ITM_INFO_FLG,
		WK_ACT_NO,
		RMRKS, SUB_CHAR1, SUB_CHAR2, SUB_CHAR3,
		SCM_IF_FLG
		)
	SELECT
		MAPA_NUM.F_GET_SEQ(C_ACT_INST_WK_IF_DATA_LNO),
		I_CALC_CTG_CD, t.LOC_WG_CD,
		I_YM,
		t.AC_DT,
		t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
		DECODE(m2.ITM_MFG_INST_NO_SET_TYP,
			C_INST_LOC, C_STR_NO3 || SUBSTR(t.LOC_CD, 1, C_ITM_MFG_INST_NO_L-LENGTH(C_STR_NO3)),
			t.ITM_MFG_INST_NO),
		DECODE(m2.MFG_ACT_NO_SET_TYP,
			C_MFG_NON,
				DECODE(m2.ITM_MFG_INST_NO_SET_TYP,
					C_INST_LOC, NVL(SUBSTR(t.LOC_CD, C_ITM_MFG_INST_NO_L-LENGTH(C_STR_NO3)+1, C_MFG_ACT_NO_L), C_NULL_VAL),
					C_NULL_VAL),
			DECODE(t8.MFG_INST_UNIT_TYP,
				C_OPER, C_NULL_VAL,
				NVL(t.MFG_ACT_NO, C_NULL_VAL))),
		DECODE(m2.OPER_ACT_NO_SET_TYP,
			C_OPER_NON, C_NULL_VAL,
			C_OPER_OPER, t.OPER_CD,
			NVL(DECODE(L_OPER_SUM_FLG, C_ON, t.OPER_CD, t.OPER_ACT_NO), C_NULL_VAL)),
		t.LOC_CD, NVL(t.STR_LN_CD, C_NULL_VAL),
		t.WK_COST_CD,
		t.WK_RSN_CD,
		t.WK_COST,
		C_OFF, C_OFF,
		t.WK_ACT_NO,
		t.INTR_RMRKS, NULL, NULL, NULL,--t.SUB_CHAR1, t.SUB_CHAR2, t.SUB_CHAR3
		C_ON
	FROM	MGVT_MST_WK_ACT t, MGVT_MST_MFG_ACT t7, MGVT_MST_MFG_INST t8, MAM_ITM_SRCH m1, MAM_CALC_PTN m2
	WHERE	0=0
	AND	t.AC_DT BETWEEN L_ST_DT AND L_END_DT
	AND	t.ITM_MFG_INST_NO IS NOT NULL
	AND	t.WK_COST <> 0
	AND t7.MFG_ACT_NO(+) = t.MFG_ACT_NO
	AND t8.MFG_INST_NO(+) = t7.MFG_INST_NO
	AND	t.ITM_CD = m1.ITM_CD(+)
	AND	t.ITM_SUB1 = m1.ITM_SUB1(+)
	AND	t.ITM_SUB2 = m1.ITM_SUB2(+)
	AND	t.ITM_SUB3 = m1.ITM_SUB3(+)
	AND	m1.DEL_FLG(+) = C_OFF
	AND	m1.RELEASE_FLG(+) = C_ON
	AND	m1.CALC_PTN_CD = m2.CALC_PTN_CD(+)
	AND	(
		L_ITM_OUT_CNT = 0
		OR
		NOT EXISTS (
			SELECT	'X'
			FROM	MAM_COST_ITM_OUT m
			WHERE	0=0
			AND	m.ITM_CD = t.ITM_CD
			AND	m.ITM_SUB1 = t.ITM_SUB1
			AND	m.ITM_SUB2 = t.ITM_SUB2
			AND	m.ITM_SUB3 = t.ITM_SUB3
			AND	m.YM <= I_YM
			)
		)
	;
	L_INST_WK_CNT := SQL%ROWCOUNT ;

	--指図外工数実績
	INSERT INTO MGT_ACT_OTHER_WK_IF (
		DATA_LNO,
		CALC_CTG_CD, WG_CD,
		YM, AC_DT,
		DPT_CD, CTG_CD,
		LOC_CD, OPER_CD,
		LOT_NO,
		SUBLOT_NO,
		SNO1,
		SNO2,
		SNO3,
		SNO4,
		WK_COST_CD,
		WK_RSN_CD,
		WK_COST,
		NO_PLN_FLG,
		WK_ACT_NO,
		RMRKS, SUB_CHAR1, SUB_CHAR2, SUB_CHAR3,
		SCM_IF_FLG
		)
	SELECT
		MAPA_NUM.F_GET_SEQ(C_ACT_OTHER_WK_IF_DATA_LNO),
		I_CALC_CTG_CD, t.DPT_WG_CD,
		I_YM,
		t.AC_DT,
		MGPA_COST_IF.F_GET_DPT(
			MAPA_DPT.F_GET_DPT_CD_NE(t.DPT_CD, t.AC_DT),
			NULL,
			t.AC_DT,
			C_OFF), NULL,
		t.LOC_CD, t.OPER_CD,
		t.LOT_NO,
		t.SUBLOT_NO,
		t.SNO1,
		t.SNO2,
		t.SNO3,
		t.SNO4,
		t.WK_COST_CD,
		t.WK_RSN_CD,
		t.WK_COST,
		C_OFF,
		t.WK_ACT_NO,
		t.INTR_RMRKS, NULL, NULL, NULL,--t.SUB_CHAR1, t.SUB_CHAR2, t.SUB_CHAR3
		C_ON
	FROM	MGVT_MST_WK_ACT t
	WHERE	0=0
	AND	t.AC_DT BETWEEN L_ST_DT AND L_END_DT
	AND	t.ITM_MFG_INST_NO IS NULL
	AND	(t.ITM_CD IS NULL OR t.LOC_CD IS NULL)
	AND	t.WK_COST <> 0
	AND	t.DPT_WG_CD IS NOT NULL
	;
	L_OTHER_WK_CNT := SQL%ROWCOUNT ;

	--指図工程情報
	REC_w7.DELETE ;
	w7 := 0 ;
	G_INST_OPER_CNT := 0 ;
	FOR x IN (
		SELECT	DISTINCT
			t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
			DECODE(m2.ITM_MFG_INST_NO_SET_TYP,
				C_INST_LOC, C_STR_NO3 || SUBSTR(t.LOC_CD, 1, C_ITM_MFG_INST_NO_L-LENGTH(C_STR_NO3)),
				t.ITM_MFG_INST_NO)	ITM_MFG_INST_NO,
			DECODE(m2.MFG_ACT_NO_SET_TYP,
				C_MFG_NON,
					DECODE(m2.ITM_MFG_INST_NO_SET_TYP,
						C_INST_LOC, NVL(SUBSTR(t.LOC_CD, C_ITM_MFG_INST_NO_L-LENGTH(C_STR_NO3)+1, C_MFG_ACT_NO_L), C_NULL_VAL),
						C_NULL_VAL),
				DECODE(t8.MFG_INST_UNIT_TYP,
					C_OPER, C_NULL_VAL,
					NVL(t.MFG_ACT_NO, C_NULL_VAL)))	MFG_ACT_NO,
			DECODE(m2.OPER_ACT_NO_SET_TYP,
				C_OPER_NON, C_NULL_VAL,
				C_OPER_OPER, t.OPER_CD,
				DECODE(L_OPER_SUM_FLG, C_ON, t.OPER_CD, t.OPER_ACT_NO))	OPER_ACT_NO,
			t.LOC_WG_CD	WG_CD,
			MGPA_COST_IF.F_GET_DPT(
				MAPA_DPT.F_GET_DPT_CD_NE(t.DPT_CD, t.AC_DT),
				L_FIX_DPT,
				t.AC_DT,
				C_OFF)	MNG_DPT_CD,
			t.OPER_CD,
			DECODE(m2.OPER_ACT_NO_SET_TYP,
				C_OPER_OPER, 1,
				DECODE(L_OPER_SUM_FLG, C_ON, 1, NVL(t3.OPER_SEQ, 0)))	OPER_SEQ,
			DECODE(m2.OPER_ACT_NO_SET_TYP,
				C_OPER_OPER, 1,
				DECODE(L_OPER_SUM_FLG, C_ON, 1, t3.DISP_SEQ))	DISP_SEQ,
			DECODE(m2.OPER_ACT_NO_SET_TYP,
				C_OPER_OPER, NULL,
				DECODE(L_OPER_SUM_FLG, C_ON, NULL, t2.BASE_UNIT_QTY))	QTY
		FROM	MGVT_MST_WK_ACT t, MGVT_MST_OPER_ACT t2, MGVT_MST_OPER_INST t3, MGVT_MST_MFG_ACT t7, MGVT_MST_MFG_INST t8,
			MAM_ITM_SRCH m1, MAM_CALC_PTN m2
		WHERE	0=0
		AND	t.AC_DT BETWEEN L_ST_DT AND L_END_DT
		AND	t.ITM_MFG_INST_NO IS NOT NULL
		AND	t.OPER_ACT_NO IS NOT NULL
		AND	t.OPER_ACT_NO <> C_NULL_VAL
		AND	t.OPER_CD IS NOT NULL
		AND	t.OPER_CD <> C_NULL_VAL
		AND	t.WK_COST <> 0
		AND	t.OPER_ACT_NO = t2.OPER_ACT_NO(+)
		AND	t2.OPER_INST_NO = t3.OPER_INST_NO(+)
		AND	t7.MFG_ACT_NO(+) = t.MFG_ACT_NO
		AND	t8.MFG_INST_NO(+) = t7.MFG_INST_NO
		AND	t.ITM_CD = m1.ITM_CD(+)
		AND	t.ITM_SUB1 = m1.ITM_SUB1(+)
		AND	t.ITM_SUB2 = m1.ITM_SUB2(+)
		AND	t.ITM_SUB3 = m1.ITM_SUB3(+)
		AND	m1.DEL_FLG(+) = C_OFF
		AND	m1.RELEASE_FLG(+) = C_ON
		AND	m1.CALC_PTN_CD = m2.CALC_PTN_CD(+)
		AND	NVL(m2.OPER_ACT_NO_SET_TYP, C_NULL_VAL) <> C_OPER_NON
		AND	(
			L_ITM_OUT_CNT = 0
			OR
			NOT EXISTS (
				SELECT	'X'
				FROM	MAM_COST_ITM_OUT m
				WHERE	0=0
				AND	m.ITM_CD = t.ITM_CD
				AND	m.ITM_SUB1 = t.ITM_SUB1
				AND	m.ITM_SUB2 = t.ITM_SUB2
				AND	m.ITM_SUB3 = t.ITM_SUB3
				AND	m.YM <= I_YM
				)
			)
		)
	LOOP
		w7 := w7 + 1 ;
		REC_w7(w7).CALC_CTG_CD		:= I_CALC_CTG_CD ;
		REC_w7(w7).ITM_CD			:= x.ITM_CD ;
		REC_w7(w7).ITM_SUB1			:= x.ITM_SUB1 ;
		REC_w7(w7).ITM_SUB2			:= x.ITM_SUB2 ;
		REC_w7(w7).ITM_SUB3			:= x.ITM_SUB3 ;
		REC_w7(w7).ITM_MFG_INST_NO	:= x.ITM_MFG_INST_NO ;
		REC_w7(w7).MFG_ACT_NO		:= x.MFG_ACT_NO ;
		REC_w7(w7).OPER_ACT_NO		:= x.OPER_ACT_NO ;
		REC_w7(w7).WG_CD			:= x.WG_CD ;
		REC_w7(w7).MNG_DPT_CD		:= x.MNG_DPT_CD ;
		REC_w7(w7).OPER_CD			:= x.OPER_CD ;
		REC_w7(w7).OPER_SEQ			:= x.OPER_SEQ ;
		REC_w7(w7).DISP_SEQ			:= x.DISP_SEQ ;
		REC_w7(w7).QTY				:= x.QTY ;
		REC_w7(w7).SCHD_ST_DT		:= NULL ;
		REC_w7(w7).SCHD_END_DT		:= NULL ;
		REC_w7(w7).ACT_ST_DT		:= NULL ;
		REC_w7(w7).ACT_END_DT		:= NULL ;
		REC_w7(w7).RMRKS			:= NULL ;
		REC_w7(w7).SUB_CHAR1		:= NULL ;
		REC_w7(w7).SUB_CHAR2		:= NULL ;
		REC_w7(w7).SUB_CHAR3		:= NULL ;

		IF w7 > C_MAX_CNT THEN
			P_INS_TRAN() ;
		END IF ;
	END LOOP ;

	P_INS_TRAN() ;

	--指図情報は無いが品目が指定されているデータを指図工数実績として取り込む
	REC_w6.DELETE ;
	REC_w8.DELETE ;
	w6 := 0 ;
	w8 := 0 ;
	G_INST_WK_CNT := 0 ;
	G_MFG_INST_CNT := 0 ;

	INSERT INTO MGW_ACT_INST_WK_IF (
		CALC_CTG_CD, WG_CD,
		YM, AC_DT,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		ITM_MFG_INST_NO, MFG_ACT_NO, OPER_ACT_NO,
		LOC_CD, STR_LN_CD,
		MNG_DPT_CD,
		WK_COST_CD, WK_RSN_CD, WK_COST,
		WK_ACT_NO,
		RMRKS, SUB_CHAR1, SUB_CHAR2, SUB_CHAR3)
	SELECT
		I_CALC_CTG_CD, t.LOC_WG_CD,
		I_YM, t.AC_DT,
		t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
		CASE WHEN L_LOT_USE_TYP <> C_PS_USE3 THEN
			CASE WHEN NVL(m2.LOT_ACT_TYP, C_ACT1) <> C_ACT1 THEN NVL(t.LOT_NO, C_NULL_VAL)
			ELSE C_NULL_VAL END
		ELSE C_NULL_VAL END	LOT_NO,
		CASE WHEN L_SUBLOT_USE_TYP <> C_PS_USE3 THEN
			CASE WHEN NVL(m2.SUBLOT_ACT_TYP, C_ACT1) <> C_ACT1 THEN NVL(t.SUBLOT_NO, C_NULL_VAL)
			ELSE C_NULL_VAL END
		ELSE C_NULL_VAL END	SUBLOT_NO,
		CASE WHEN L_SNO1_USE_TYP <> C_PS_USE3 THEN
			CASE WHEN NVL(m2.SNO1_ACT_TYP, C_ACT1) <> C_ACT1 THEN t.SNO1
			ELSE C_NULL_VAL END
		ELSE C_NULL_VAL END	SNO1,
		CASE WHEN L_SNO2_USE_TYP <> C_PS_USE3 THEN
			CASE WHEN NVL(m2.SNO2_ACT_TYP, C_ACT1) <> C_ACT1 THEN t.SNO2
			ELSE C_NULL_VAL END
		ELSE C_NULL_VAL END	SNO2,
		CASE WHEN L_SNO3_USE_TYP <> C_PS_USE3 THEN
			CASE WHEN NVL(m2.SNO3_ACT_TYP, C_ACT1) <> C_ACT1 THEN t.SNO3
			ELSE C_NULL_VAL END
		ELSE C_NULL_VAL END	SNO3,
		CASE WHEN L_SNO4_USE_TYP <> C_PS_USE3 THEN
			CASE WHEN NVL(m2.SNO4_ACT_TYP, C_ACT1) <> C_ACT1 THEN t.SNO4
			ELSE C_NULL_VAL END
		ELSE C_NULL_VAL END	SNO4,
		C_NULL_VAL, C_NULL_VAL, C_NULL_VAL,
		t.LOC_CD, NVL(t.STR_LN_CD, C_NULL_VAL),
		MGPA_COST_IF.F_GET_DPT(
			MAPA_DPT.F_GET_DPT_CD_NE(t.DPT_CD, t.AC_DT),
			L_FIX_DPT,
			t.AC_DT,
			C_OFF),
		t.WK_COST_CD, t.WK_RSN_CD, SUM(t.WK_COST),
		MAX(t.WK_ACT_NO),
		MAX(t.INTR_RMRKS), NULL, NULL, NULL--t.SUB_CHAR1, t.SUB_CHAR2, t.SUB_CHAR3
	FROM	MGVT_MST_WK_ACT t, MAM_ITM_SRCH m1, MAM_CALC_PTN m2
	WHERE	0=0
	AND	t.AC_DT BETWEEN L_ST_DT AND L_END_DT
	AND	t.ITM_MFG_INST_NO IS NULL
	AND	t.ITM_CD IS NOT NULL
	AND	t.LOC_CD IS NOT NULL
	AND	t.WK_COST <> 0
	AND	t.ITM_CD = m1.ITM_CD
	AND	t.ITM_SUB1 = m1.ITM_SUB1
	AND	t.ITM_SUB2 = m1.ITM_SUB2
	AND	t.ITM_SUB3 = m1.ITM_SUB3
	AND	m1.DEL_FLG = C_OFF
	AND	m1.RELEASE_FLG = C_ON
	AND	m1.ASSET_MNG_TYP = C_ASST_MNG1
	AND	m1.CALC_PTN_CD = m2.CALC_PTN_CD(+)
	AND	(
		L_ITM_OUT_CNT = 0
		OR
		NOT EXISTS (
			SELECT	'X'
			FROM	MAM_COST_ITM_OUT m
			WHERE	0=0
			AND	m.ITM_CD = t.ITM_CD
			AND	m.ITM_SUB1 = t.ITM_SUB1
			AND	m.ITM_SUB2 = t.ITM_SUB2
			AND	m.ITM_SUB3 = t.ITM_SUB3
			AND	m.YM <= I_YM
			)
		)
	GROUP BY
		t.LOC_WG_CD,
		t.AC_DT,
		t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
		CASE WHEN L_LOT_USE_TYP <> C_PS_USE3 THEN
			CASE WHEN NVL(m2.LOT_ACT_TYP, C_ACT1) <> C_ACT1 THEN NVL(t.LOT_NO, C_NULL_VAL)
			ELSE C_NULL_VAL END
		ELSE C_NULL_VAL END,
		CASE WHEN L_SUBLOT_USE_TYP <> C_PS_USE3 THEN
			CASE WHEN NVL(m2.SUBLOT_ACT_TYP, C_ACT1) <> C_ACT1 THEN NVL(t.SUBLOT_NO, C_NULL_VAL)
			ELSE C_NULL_VAL END
		ELSE C_NULL_VAL END,
		CASE WHEN L_SNO1_USE_TYP <> C_PS_USE3 THEN
			CASE WHEN NVL(m2.SNO1_ACT_TYP, C_ACT1) <> C_ACT1 THEN t.SNO1
			ELSE C_NULL_VAL END
		ELSE C_NULL_VAL END,
		CASE WHEN L_SNO2_USE_TYP <> C_PS_USE3 THEN
			CASE WHEN NVL(m2.SNO2_ACT_TYP, C_ACT1) <> C_ACT1 THEN t.SNO2
			ELSE C_NULL_VAL END
		ELSE C_NULL_VAL END,
		CASE WHEN L_SNO3_USE_TYP <> C_PS_USE3 THEN
			CASE WHEN NVL(m2.SNO3_ACT_TYP, C_ACT1) <> C_ACT1 THEN t.SNO3
			ELSE C_NULL_VAL END
		ELSE C_NULL_VAL END,
		CASE WHEN L_SNO4_USE_TYP <> C_PS_USE3 THEN
			CASE WHEN NVL(m2.SNO4_ACT_TYP, C_ACT1) <> C_ACT1 THEN t.SNO4
			ELSE C_NULL_VAL END
		ELSE C_NULL_VAL END,
		t.LOC_CD, NVL(t.STR_LN_CD, C_NULL_VAL),
		MGPA_COST_IF.F_GET_DPT(
			MAPA_DPT.F_GET_DPT_CD_NE(t.DPT_CD, t.AC_DT),
			L_FIX_DPT,
			t.AC_DT,
			C_OFF),
		t.WK_COST_CD, t.WK_RSN_CD
	;

	FOR w1 IN (
		SELECT	DISTINCT
			w.ITM_CD,
			w.ITM_SUB1,
			w.ITM_SUB2,
			w.ITM_SUB3,
			w.CALC_CTG_CD,
			w.WG_CD,
			w.MNG_DPT_CD,
			w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
			w.LOC_CD, w.STR_LN_CD, m.SPPL_CD
		FROM	MGW_ACT_INST_WK_IF w, MAM_LOC m
		WHERE	0=0
		AND	w.LOC_CD = m.LOC_CD(+)
		)
	LOOP
		SELECT	MAX(t.ITM_MFG_INST_NO)
		INTO	L_ITM_MFG_INST_NO
		FROM	MGT_ITM_MFG_INST t
		WHERE	0=0
		AND	t.ITM_MFG_INST_NO LIKE C_STR_NO2 || '%'
		AND	LENGTH(t.ITM_MFG_INST_NO) = C_ITM_MFG_INST_LENGTH + LENGTH(C_STR_NO2)
		AND	t.MFG_ACT_NO = C_NULL_VAL
		AND	t.ITM_CD = w1.ITM_CD
		AND	t.ITM_SUB1 = w1.ITM_SUB1
		AND	t.ITM_SUB2 = w1.ITM_SUB2
		AND	t.ITM_SUB3 = w1.ITM_SUB3
		AND	t.CALC_CTG_CD = I_CALC_CTG_CD
		AND	t.WG_CD = w1.WG_CD
		AND	t.MNG_DPT_CD = w1.MNG_DPT_CD
		AND	t.LOT_NO = w1.LOT_NO
		AND	t.SUBLOT_NO = w1.SUBLOT_NO
		AND	t.SNO1 = w1.SNO1
		AND	t.SNO2 = w1.SNO2
		AND	t.SNO3 = w1.SNO3
		AND	t.SNO4 = w1.SNO4
		AND	EXISTS (
				SELECT	'X'
				FROM	MGT_ACT_INST_WK_IF x
				WHERE	0=0
				AND	x.CALC_CTG_CD = t.CALC_CTG_CD
				AND	x.YM = I_YM
				AND	x.ITM_CD = t.ITM_CD
				AND	x.ITM_SUB1 = t.ITM_SUB1
				AND	x.ITM_SUB2 = t.ITM_SUB2
				AND	x.ITM_SUB3 = t.ITM_SUB3
				AND	x.ITM_MFG_INST_NO = t.ITM_MFG_INST_NO
				AND	x.MFG_ACT_NO = t.MFG_ACT_NO
				AND	x.LOC_CD = w1.LOC_CD
				AND	x.STR_LN_CD = w1.STR_LN_CD
				)
		;

		IF L_ITM_MFG_INST_NO IS NULL THEN
			L_ITM_MFG_INST_NO := C_STR_NO2 || LPAD(MAPA_NUM.F_GET_SEQ(C_ITM_MFG_INST), C_ITM_MFG_INST_LENGTH, '0') ;

			w6 := w6 + 1 ;

			REC_w6(w6).CALC_CTG_CD	:= I_CALC_CTG_CD ;
			REC_w6(w6).ITM_CD	:= w1.ITM_CD ;
			REC_w6(w6).ITM_SUB1	:= w1.ITM_SUB1 ;
			REC_w6(w6).ITM_SUB2	:= w1.ITM_SUB2 ;
			REC_w6(w6).ITM_SUB3	:= w1.ITM_SUB3 ;
			REC_w6(w6).ITM_MFG_INST_NO := L_ITM_MFG_INST_NO ;
			REC_w6(w6).MFG_ACT_NO := C_NULL_VAL ;
			REC_w6(w6).WG_CD	:= w1.WG_CD ;
			REC_w6(w6).MNG_DPT_CD	:= w1.MNG_DPT_CD ;
			REC_w6(w6).LOT_NO		:= w1.LOT_NO ;
			REC_w6(w6).SUBLOT_NO	:= w1.SUBLOT_NO ;
			REC_w6(w6).SNO1		:= w1.SNO1 ;
			REC_w6(w6).SNO2		:= w1.SNO2 ;
			REC_w6(w6).SNO3		:= w1.SNO3 ;
			REC_w6(w6).SNO4		:= w1.SNO4 ;
			REC_w6(w6).SPPL_CD	:= w1.SPPL_CD ;
			REC_w6(w6).PO_NO	:= NULL ;
			REC_w6(w6).SLO_NO	:= NULL ;
			REC_w6(w6).IV_NO	:= NULL ;
			REC_w6(w6).ASST_TYP	:= C_ASST2 ;
			REC_w6(w6).QTY		:= 0 ;
			REC_w6(w6).SCHD_ST_DT	:= NULL ;
			REC_w6(w6).SCHD_END_DT	:= NULL ;
			REC_w6(w6).ACT_ST_DT	:= NULL ;
			REC_w6(w6).ACT_END_DT	:= NULL ;
			REC_w6(w6).RMRKS	:= NULL ;
			REC_w6(w6).SUB_CHAR1	:= NULL ;
			REC_w6(w6).SUB_CHAR2	:= NULL ;
			REC_w6(w6).SUB_CHAR3	:= NULL ;
			P_COL_PROC_ITM() ;
		END IF ;

		FOR w2 IN (
			SELECT	w.*
			FROM	MGW_ACT_INST_WK_IF w
			WHERE	0=0
			AND	w.ITM_CD = w1.ITM_CD
			AND	w.ITM_SUB1 = w1.ITM_SUB1
			AND	w.ITM_SUB2 = w1.ITM_SUB2
			AND	w.ITM_SUB3 = w1.ITM_SUB3
			AND	w.CALC_CTG_CD = w1.CALC_CTG_CD
			AND	w.MNG_DPT_CD = w1.MNG_DPT_CD
			AND	w.LOT_NO = w1.LOT_NO
			AND	w.SUBLOT_NO = w1.SUBLOT_NO
			AND	w.SNO1 = w1.SNO1
			AND	w.SNO2 = w1.SNO2
			AND	w.SNO3 = w1.SNO3
			AND	w.SNO4 = w1.SNO4
			AND	w.LOC_CD = w1.LOC_CD
			AND	w.STR_LN_CD = w1.STR_LN_CD
			)
		LOOP
			w8 := w8 + 1 ;

			REC_w8(w8).DATA_LNO	:= MAPA_NUM.F_GET_SEQ(C_ACT_INST_WK_IF_DATA_LNO) ;
			REC_w8(w8).CALC_CTG_CD	:= I_CALC_CTG_CD ;
			REC_w8(w8).WG_CD	:= w2.WG_CD ;
			REC_w8(w8).YM		:= I_YM ;
			REC_w8(w8).AC_DT	:= w2.AC_DT ;
			REC_w8(w8).ITM_CD	:= w2.ITM_CD ;
			REC_w8(w8).ITM_SUB1	:= w2.ITM_SUB1 ;
			REC_w8(w8).ITM_SUB2	:= w2.ITM_SUB2 ;
			REC_w8(w8).ITM_SUB3	:= w2.ITM_SUB3 ;
			REC_w8(w8).ITM_MFG_INST_NO	:= L_ITM_MFG_INST_NO ;
			REC_w8(w8).MFG_ACT_NO	:= w2.MFG_ACT_NO ;
			REC_w8(w8).OPER_ACT_NO	:= w2.OPER_ACT_NO ;
			REC_w8(w8).LOC_CD		:= w2.LOC_CD ;
			REC_w8(w8).STR_LN_CD	:= w2.STR_LN_CD ;
			REC_w8(w8).WK_COST_CD	:= w2.WK_COST_CD ;
			REC_w8(w8).WK_RSN_CD	:= w2.WK_RSN_CD ;
			REC_w8(w8).WK_COST		:= w2.WK_COST ;
			REC_w8(w8).NO_PLN_FLG	:= C_OFF ;
			REC_w8(w8).NO_ITM_INFO_FLG	:= C_OFF ;
			REC_w8(w8).WK_ACT_NO	:= w2.WK_ACT_NO ;
			REC_w8(w8).RMRKS		:= w2.RMRKS ;
			REC_w8(w8).SUB_CHAR1	:= NULL ;
			REC_w8(w8).SUB_CHAR2	:= NULL ;
			REC_w8(w8).SUB_CHAR3	:= NULL ;
			REC_w8(w8).SCM_IF_FLG	:= C_ON ;
		END LOOP ;

		IF w6 + w8 > C_MAX_CNT THEN
			P_INS_TRAN() ;
		END IF ;
	END LOOP ;

	P_INS_TRAN() ;

	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0023', L_REC_CNT) ;
	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0033', L_INST_WK_CNT + G_INST_WK_CNT) ;
	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0034', L_OTHER_WK_CNT) ;
	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0026', G_MFG_INST_CNT) ;
	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0027', G_INST_OPER_CNT) ;

	<<SKIP_WK>>
		NULL ;

	COMMIT ;

	--仕掛実績情報の取込
	IF I_WIP = C_OFF OR L_NON_PROD_FLG = C_ON THEN
		GOTO SKIP_WIP ;
	END IF ;

	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0039') ;

	SELECT	COUNT(*)
	INTO	L_REC_CNT
	FROM	MGVT_MST_MLY_WIP t
	WHERE	0=0
	AND	t.YM = I_YM
	AND t.CMPL_FLG = C_OFF
	AND	t.BASE_UNIT_WIP_QTY <> 0
	;

	IF L_REC_CNT = 0 THEN
		FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0024', L_REC_CNT) ;
		GOTO SKIP_WIP ;
	END IF ;

	--部門のチェック
	REC_DPT.DELETE ;
	MGPA_COST_IF.P_LOC_INIT ;
	L_CHK_ERR := C_OFF ;
	FOR x3 IN (
		SELECT	DISTINCT
			t.LOC_CD
		FROM	MGVT_MST_MLY_WIP t
		WHERE	0=0
		AND	t.YM = I_YM
		AND	t.BASE_UNIT_WIP_QTY <> 0
		AND t.CMPL_FLG = C_OFF
		AND	(
			L_ITM_OUT_CNT = 0
			OR
			NOT EXISTS (
				SELECT	'X'
				FROM	MAM_COST_ITM_OUT m
				WHERE	0=0
				AND	m.ITM_CD = t.ITM_CD
				AND	m.ITM_SUB1 = t.ITM_SUB1
				AND	m.ITM_SUB2 = t.ITM_SUB2
				AND	m.ITM_SUB3 = t.ITM_SUB3
				AND	m.YM <= I_YM
				)
			)
		)
	LOOP
		MGPA_COST_IF.P_GET_DPT(
			MAPA_LOC.F_GET_ASST_DPT_CD_NE(x3.LOC_CD, L_END_DT, C_ON),
			L_FIX_DPT,
			L_END_DT,
			REC_DPT,
			L_MDPT,
			C_ON) ;

		IF L_MDPT IS NULL THEN
			L_RSLT := C_ERR ;
			L_CHK_ERR := C_ON ;
		ELSE
			MGPA_COST_IF.P_LOC_CACHE(x3.LOC_CD, L_MDPT) ;
		END IF ;
	END LOOP ;

	IF L_CHK_ERR = C_ON THEN
		GOTO SKIP_WIP ;
	END IF ;

	--取得するときは年月ごとに再取り込みを行う
	DELETE MGT_ACT_INST_WIP_IF t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG_CD AND (I_RERUN = C_ON OR t.SCM_IF_FLG = C_ON) ;

	--仕掛情報の取込
	INSERT INTO MGT_ACT_INST_WIP_IF (
		DATA_LNO,
		CALC_CTG_CD, WG_CD,
		YM,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		ITM_MFG_INST_NO,
		MFG_ACT_NO,
		OPER_ACT_NO,
		LOC_CD, STR_LN_CD,
		AC_RSN_CD,
		WIP_QTY,
		WIP_PER,
		RMRKS, SUB_CHAR1, SUB_CHAR2, SUB_CHAR3,
		SCM_IF_FLG
		)
	SELECT
		MAPA_NUM.F_GET_SEQ(C_ACT_INST_WIP_IF_DATA_LNO),
		I_CALC_CTG_CD, x.WG_CD,
		x.YM,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.ITM_MFG_INST_NO,
		x.MFG_ACT_NO,
		C_NULL_VAL,
		x.LOC_CD, x.STR_LN_CD,
		NULL,
		SUM(x.BASE_UNIT_WIP_QTY),
		MAX(x.WIP_RATE),
		NULL, NULL, NULL, NULL,--x.SUB_CHAR1, x.SUB_CHAR2, x.SUB_CHAR3
		C_ON
	FROM (
		SELECT
			t2.WG_CD,
			t.YM,
			t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
			DECODE(m2.ITM_MFG_INST_NO_SET_TYP,
				C_INST_LOC, C_STR_NO3 || SUBSTR(t.LOC_CD, 1, C_ITM_MFG_INST_NO_L-LENGTH(C_STR_NO3)),
				t.ITM_MFG_INST_NO)	ITM_MFG_INST_NO,
			DECODE(m2.MFG_ACT_NO_SET_TYP,
				C_MFG_NON,
					DECODE(m2.ITM_MFG_INST_NO_SET_TYP,
						C_INST_LOC, NVL(SUBSTR(t.LOC_CD, C_ITM_MFG_INST_NO_L-LENGTH(C_STR_NO3)+1, C_MFG_ACT_NO_L), C_NULL_VAL),
						C_NULL_VAL),
				DECODE(t8.MFG_INST_UNIT_TYP,
					C_OPER, C_NULL_VAL,
					NVL(t.MFG_ACT_NO, C_NULL_VAL)))	MFG_ACT_NO,
			t.LOC_CD,
			t.STR_LN_CD,
			t.BASE_UNIT_WIP_QTY,
			DECODE(m2.ITM_MFG_INST_NO_SET_TYP, C_INST_LOC, 50, t.WIP_RATE)	WIP_RATE
			--, t.SUB_CHAR1, t.SUB_CHAR2, t.SUB_CHAR3
		FROM	MGVT_MST_MLY_WIP t, MGVT_MST_ITM_MFG_INST t2, MGVT_MST_MFG_ACT t7, MGVT_MST_MFG_INST t8,
			MAM_ITM_SRCH m1, MAM_CALC_PTN m2
		WHERE	0=0
		AND	t.YM = I_YM
		AND	t.BASE_UNIT_WIP_QTY <> 0
		AND t.CMPL_FLG = C_OFF
		AND t.ITM_MFG_INST_NO = t2.ITM_MFG_INST_NO
		AND t7.MFG_ACT_NO(+) = t.MFG_ACT_NO
		AND t8.MFG_INST_NO(+) = t7.MFG_INST_NO
		AND	t.ITM_CD = m1.ITM_CD(+)
		AND	t.ITM_SUB1 = m1.ITM_SUB1(+)
		AND	t.ITM_SUB2 = m1.ITM_SUB2(+)
		AND	t.ITM_SUB3 = m1.ITM_SUB3(+)
		AND	m1.DEL_FLG(+) = C_OFF
		AND	m1.RELEASE_FLG(+) = C_ON
		AND	m1.CALC_PTN_CD = m2.CALC_PTN_CD(+)
		AND	(
			L_ITM_OUT_CNT = 0
			OR
			NOT EXISTS (
				SELECT	'X'
				FROM	MAM_COST_ITM_OUT m
				WHERE	0=0
				AND	m.ITM_CD = t.ITM_CD
				AND	m.ITM_SUB1 = t.ITM_SUB1
				AND	m.ITM_SUB2 = t.ITM_SUB2
				AND	m.ITM_SUB3 = t.ITM_SUB3
				AND	m.YM <= I_YM
				)
			)
		) x
	WHERE	0=0
	GROUP BY x.WG_CD, x.YM, x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.ITM_MFG_INST_NO, x.MFG_ACT_NO, x.LOC_CD, x.STR_LN_CD
		--, x.SUB_CHAR1, x.SUB_CHAR2, x.SUB_CHAR3
	;
	L_WIP_CNT := SQL%ROWCOUNT ;

	--品目製造指図情報
	REC_w6.DELETE ;
	w6 := 0 ;
	G_MFG_INST_CNT := 0;

	FOR w1 IN (
			SELECT
				x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
				x.ITM_MFG_INST_NO,
				x.MFG_ACT_NO,
				x.WG_CD,
				x.MNG_DPT_CD,
				x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
				x.SPPL_CD,
				x.PO_NO, x.SLO_NO, x.RCPT_IV_NO,
				x.ASST_TYP,
				x.BASE_UNIT_SCHD_QTY
			FROM (
				SELECT
					t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
					DECODE(m2.ITM_MFG_INST_NO_SET_TYP,
						C_INST_LOC, C_STR_NO3 || SUBSTR(t.LOC_CD, 1, C_ITM_MFG_INST_NO_L-LENGTH(C_STR_NO3)),
						t.ITM_MFG_INST_NO)	ITM_MFG_INST_NO,
					DECODE(m2.MFG_ACT_NO_SET_TYP,
						C_MFG_NON,
							DECODE(m2.ITM_MFG_INST_NO_SET_TYP,
								C_INST_LOC, NVL(SUBSTR(t.LOC_CD, C_ITM_MFG_INST_NO_L-LENGTH(C_STR_NO3)+1, C_MFG_ACT_NO_L), C_NULL_VAL),
								C_NULL_VAL),
						DECODE(t8.MFG_INST_UNIT_TYP,
							C_OPER, C_NULL_VAL,
							NVL(t.MFG_ACT_NO, C_NULL_VAL)))	MFG_ACT_NO,
					t2.WG_CD,
					MGPA_COST_IF.F_GET_LOC_TO_DPT(t.LOC_CD)	MNG_DPT_CD,
					CASE WHEN m2.ITM_MFG_INST_NO_SET_TYP = C_INST_LOC THEN
						C_NULL_VAL
					ELSE
						CASE WHEN L_LOT_USE_TYP <> C_PS_USE3 THEN
							CASE WHEN NVL(m2.LOT_ACT_TYP, C_ACT1) <> C_ACT1 THEN NVL(t.LOT_NO, C_NULL_VAL)
							ELSE C_NULL_VAL END
						ELSE C_NULL_VAL END
					END	LOT_NO,
					CASE WHEN m2.ITM_MFG_INST_NO_SET_TYP = C_INST_LOC THEN
						C_NULL_VAL
					ELSE
						CASE WHEN L_SUBLOT_USE_TYP <> C_PS_USE3 THEN
							CASE WHEN NVL(m2.SUBLOT_ACT_TYP, C_ACT1) <> C_ACT1 THEN NVL(t.SUBLOT_NO, C_NULL_VAL)
							ELSE C_NULL_VAL END
						ELSE C_NULL_VAL END
					END	SUBLOT_NO,
					CASE WHEN m2.ITM_MFG_INST_NO_SET_TYP = C_INST_LOC THEN
						C_NULL_VAL
					ELSE
						CASE WHEN L_SNO1_USE_TYP <> C_PS_USE3 THEN
							CASE WHEN NVL(m2.SNO1_ACT_TYP, C_ACT1) <> C_ACT1 THEN t.SNO1
							ELSE C_NULL_VAL END
						ELSE C_NULL_VAL END
					END	SNO1,
					CASE WHEN m2.ITM_MFG_INST_NO_SET_TYP = C_INST_LOC THEN
						C_NULL_VAL
					ELSE
						CASE WHEN L_SNO2_USE_TYP <> C_PS_USE3 THEN
							CASE WHEN NVL(m2.SNO2_ACT_TYP, C_ACT1) <> C_ACT1 THEN t.SNO2
							ELSE C_NULL_VAL END
						ELSE C_NULL_VAL END
					END	SNO2,
					CASE WHEN m2.ITM_MFG_INST_NO_SET_TYP = C_INST_LOC THEN
						C_NULL_VAL
					ELSE
						CASE WHEN L_SNO3_USE_TYP <> C_PS_USE3 THEN
							CASE WHEN NVL(m2.SNO3_ACT_TYP, C_ACT1) <> C_ACT1 THEN t.SNO3
							ELSE C_NULL_VAL END
						ELSE C_NULL_VAL END
					END	SNO3,
					CASE WHEN m2.ITM_MFG_INST_NO_SET_TYP = C_INST_LOC THEN
						C_NULL_VAL
					ELSE
						CASE WHEN L_SNO4_USE_TYP <> C_PS_USE3 THEN
							CASE WHEN NVL(m2.SNO4_ACT_TYP, C_ACT1) <> C_ACT1 THEN t.SNO4
							ELSE C_NULL_VAL END
						ELSE C_NULL_VAL END
					END	SNO4,
					t2.SPPL_CD,
					DECODE(L_TGT_PO_NO_FLG, C_OFF, t4.PO_NO)	PO_NO,
					DECODE(L_TGT_SLO_FLG, C_OFF, t4.SLO_NO)		SLO_NO,
					DECODE(L_TGT_IV_FLG, C_OFF, t6.RCPT_IV_NO)	RCPT_IV_NO,
					DECODE(L_ASST_FLG, C_OFF, t.ASST_TYP, C_ASST2)	ASST_TYP,
					DECODE(m2.ITM_MFG_INST_NO_SET_TYP,
						C_INST_LOC, 0,
						DECODE(m2.MFG_ACT_NO_SET_TYP,
							C_MFG_NON, 0, t.BASE_UNIT_SCHD_QTY))	BASE_UNIT_SCHD_QTY,
					TRUNC(t3.ST_SCHD_TM, 'DD')	ST_SCHD_TM,
					TRUNC(t3.END_SCHD_TM, 'DD')	END_SCHD_TM,
					t.ST_AC_DT,
					t.END_AC_DT,
					t3.INTR_RMRKS, t3.SUB_CHAR1, t3.SUB_CHAR2, t3.SUB_CHAR3,
					ROW_NUMBER() OVER (PARTITION BY
						t.ITM_CD,
						t.ITM_SUB1,
						t.ITM_SUB2,
						t.ITM_SUB3,
						DECODE(m2.ITM_MFG_INST_NO_SET_TYP,
							C_INST_LOC, C_STR_NO3 || SUBSTR(t.LOC_CD, 1, C_ITM_MFG_INST_NO_L-LENGTH(C_STR_NO3)),
							t.ITM_MFG_INST_NO),
						DECODE(m2.MFG_ACT_NO_SET_TYP,
							C_MFG_NON,
								DECODE(m2.ITM_MFG_INST_NO_SET_TYP,
									C_INST_LOC, NVL(SUBSTR(t.LOC_CD, C_ITM_MFG_INST_NO_L-LENGTH(C_STR_NO3)+1, C_MFG_ACT_NO_L), C_NULL_VAL),
									C_NULL_VAL),
							DECODE(t8.MFG_INST_UNIT_TYP,
								C_OPER, C_NULL_VAL,
								NVL(t.MFG_ACT_NO, C_NULL_VAL)))
						ORDER BY t3.ST_SCHD_TM, t3.MFG_INST_NO) AS ST_SCHD_TM_RN
				FROM	MGVT_MST_MLY_WIP t, MGVT_MST_ITM_MFG_INST t2, MGVT_MST_MFG_INST t3, MGVT_MST_PURC_ACT_D t4, MGVT_MST_ARR_PR t5, MGVT_MST_ARR_SCHD t6,
					MAM_ITM_SRCH m1, MAM_CALC_PTN m2, MGVT_MST_MFG_ACT t7, MGVT_MST_MFG_INST t8
				WHERE	0=0
				AND	t.YM = I_YM
				AND	t.BASE_UNIT_WIP_QTY <> 0
				AND t.CMPL_FLG = C_OFF
				AND t.ITM_MFG_INST_NO = t2.ITM_MFG_INST_NO
				AND t2.ITM_MFG_INST_NO = t3.ITM_MFG_INST_NO
				AND t3.PO_D_NO = t4.PO_D_NO(+)
				AND t3.PO_D_NO = t5.PO_D_NO(+)
				AND t3.MFG_INST_NO = t6.MFG_INST_NO(+)
				AND t5.ARR_PR_NO = t6.ARR_PR_NO(+)
				AND t7.MFG_ACT_NO(+) = t.MFG_ACT_NO
				AND t8.MFG_INST_NO(+) = t7.MFG_INST_NO
				AND	t.ITM_CD = m1.ITM_CD
				AND	t.ITM_SUB1 = m1.ITM_SUB1
				AND	t.ITM_SUB2 = m1.ITM_SUB2
				AND	t.ITM_SUB3 = m1.ITM_SUB3
				AND	m1.DEL_FLG = C_OFF
				AND	m1.RELEASE_FLG = C_ON
				AND	m1.ASSET_MNG_TYP = C_ASST_MNG1
				AND	m1.CALC_PTN_CD = m2.CALC_PTN_CD(+)
				AND	(
					L_ITM_OUT_CNT = 0
					OR
					NOT EXISTS (
						SELECT	'X'
						FROM	MAM_COST_ITM_OUT m
						WHERE	0=0
						AND	m.ITM_CD = t.ITM_CD
						AND	m.ITM_SUB1 = t.ITM_SUB1
						AND	m.ITM_SUB2 = t.ITM_SUB2
						AND	m.ITM_SUB3 = t.ITM_SUB3
						AND	m.YM <= I_YM
						)
					)
				) x
			WHERE	0=0
			AND	x.ST_SCHD_TM_RN = 1
		)
	LOOP
		w6 := w6 + 1 ;

		REC_w6(w6).CALC_CTG_CD	:= I_CALC_CTG_CD ;
		REC_w6(w6).ITM_CD	:= w1.ITM_CD ;
		REC_w6(w6).ITM_SUB1	:= w1.ITM_SUB1 ;
		REC_w6(w6).ITM_SUB2	:= w1.ITM_SUB2 ;
		REC_w6(w6).ITM_SUB3	:= w1.ITM_SUB3 ;
		REC_w6(w6).ITM_MFG_INST_NO	:= w1.ITM_MFG_INST_NO ;
		REC_w6(w6).MFG_ACT_NO	:= w1.MFG_ACT_NO ;
		REC_w6(w6).WG_CD	:= w1.WG_CD ;
		REC_w6(w6).MNG_DPT_CD	:= w1.MNG_DPT_CD ;
		REC_w6(w6).LOT_NO	:= w1.LOT_NO ;
		REC_w6(w6).SUBLOT_NO	:= w1.SUBLOT_NO ;
		REC_w6(w6).SNO1	:= w1.SNO1 ;
		REC_w6(w6).SNO2	:= w1.SNO2 ;
		REC_w6(w6).SNO3	:= w1.SNO3 ;
		REC_w6(w6).SNO4	:= w1.SNO4 ;
		REC_w6(w6).SPPL_CD	:= w1.SPPL_CD ;
		REC_w6(w6).PO_NO	:= w1.PO_NO ;
		REC_w6(w6).SLO_NO	:= w1.SLO_NO ;
		REC_w6(w6).IV_NO	:= w1.RCPT_IV_NO ;
		REC_w6(w6).ASST_TYP	:= w1.ASST_TYP ;
		REC_w6(w6).QTY	:= w1.BASE_UNIT_SCHD_QTY ;
		REC_w6(w6).SCHD_ST_DT	:= NULL ;
		REC_w6(w6).SCHD_END_DT	:= NULL ;
		REC_w6(w6).ACT_ST_DT	:= NULL ;
		REC_w6(w6).ACT_END_DT	:= NULL ;
		REC_w6(w6).RMRKS	:= NULL ;
		REC_w6(w6).SUB_CHAR1	:= NULL ;
		REC_w6(w6).SUB_CHAR2	:= NULL ;
		REC_w6(w6).SUB_CHAR3	:= NULL ;

		IF w6 > C_MAX_CNT THEN
			P_INS_TRAN() ;
		END IF ;
	END LOOP ;

	IF w6 > 0 THEN
		P_INS_TRAN() ;
	END IF ;

	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0024', L_REC_CNT) ;
	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0036', L_WIP_CNT) ;
	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0026', G_MFG_INST_CNT) ;

	<<SKIP_WIP>>
		NULL ;

	COMMIT ;

	--在庫情報の取込
	IF I_STK = C_OFF THEN
		GOTO SKIP_STK ;
	END IF ;

	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0040') ;

	IF I_NON_MOV = C_ON THEN
		G_YM := I_YM ;
		P_SET_NON_MOVE() ;
	END IF ;

	SELECT	COUNT(*)
	INTO	L_REC_CNT
	FROM	MGVT_MST_MLY_STK_DTL t
	WHERE	0=0
	AND	t.AC_YM = I_YM
	AND	t.IO_ACT_TYP = C_END_STK
	AND	t.BASE_UNIT_QTY <> 0
	;

	IF L_REC_CNT = 0 THEN
		FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0025', L_REC_CNT) ;
		GOTO SKIP_STK ;
	END IF ;

	--部門のチェック
	REC_DPT.DELETE ;
	MGPA_COST_IF.P_LOC_INIT ;
	L_CHK_ERR := C_OFF ;
	FOR x4 IN (
		SELECT	DISTINCT
			t.LOC_CD
		FROM	MGVT_MST_MLY_STK_DTL t, MAM_LOC m1, MAM_BP m2
		WHERE	0=0
		AND	t.AC_YM = I_YM
		AND	t.IO_ACT_TYP = C_END_STK
		AND	t.BASE_UNIT_QTY <> 0
		AND	t.LOC_CD = m1.LOC_CD
		AND	m1.DEL_FLG = C_OFF
		AND t.STK_ARRV_BP_CD = m2.BP_CD(+)
		AND (
			m1.SPPL_CD IS NOT NULL AND t.STK_ID_TYP IN (C_STK_ID1, C_STK_ID8)
			OR
			m1.SPPL_CD IS NULL AND t.ASST_TYP <> C_ASST3
			)
		AND	(
			L_NON_PROD_FLG = C_OFF AND t.ASST_TYP IN (C_ASST2, C_ASST3)
			OR
			L_NON_SLS_FLG = C_OFF AND t.ASST_TYP = C_ASST1
			)
		AND	(
			L_ITM_OUT_CNT = 0
			OR
			NOT EXISTS (
				SELECT	'X'
				FROM	MAM_COST_ITM_OUT m
				WHERE	0=0
				AND	m.ITM_CD = t.ITM_CD
				AND	m.ITM_SUB1 = t.ITM_SUB1
				AND	m.ITM_SUB2 = t.ITM_SUB2
				AND	m.ITM_SUB3 = t.ITM_SUB3
				AND	m.YM <= I_YM
				)
			)
		)
	LOOP
		MGPA_COST_IF.P_GET_DPT(
			MAPA_LOC.F_GET_ASST_DPT_CD_NE(x4.LOC_CD, L_END_DT, C_ON),
			L_FIX_DPT,
			L_END_DT,
			REC_DPT,
			L_MDPT,
			C_ON) ;

		IF L_MDPT IS NULL THEN
			L_RSLT := C_ERR ;
			L_CHK_ERR := C_ON ;
		ELSE
			MGPA_COST_IF.P_LOC_CACHE(x4.LOC_CD, L_MDPT) ;
		END IF ;
	END LOOP ;

	IF L_CHK_ERR = C_ON THEN
		GOTO SKIP_STK ;
	END IF ;

	--取得するときは年月ごとに再取り込みを行う
	DELETE MGT_ACT_STK_IF t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG_CD AND (I_RERUN = C_ON OR t.SCM_IF_FLG = C_ON) ;

	--在庫情報の取込
	INSERT INTO MGT_ACT_STK_IF (
		DATA_LNO,
		CALC_CTG_CD, WG_CD,
		YM,
		MNG_DPT_CD,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		BP_CD,
		ASST_TYP,
		QTY,
		FIRST_GR_DT, VLD_DT, LMT_DT, NON_MOV_BASE_DT,
		RMRKS, SUB_CHAR1, SUB_CHAR2, SUB_CHAR3,
		SCM_IF_FLG
		)
	SELECT
		MAPA_NUM.F_GET_SEQ(C_ACT_STK_IF_DATA_LNO),
		I_CALC_CTG_CD, z.WG_CD,
		z.AC_YM,
		z.MNG_DPT_CD,
		z.ITM_CD, z.ITM_SUB1, z.ITM_SUB2, z.ITM_SUB3,
		NVL(z.LOT_NO, C_NULL_VAL), NVL(z.SUBLOT_NO, C_NULL_VAL), NVL(z.SNO1, C_NULL_VAL), NVL(z.SNO2, C_NULL_VAL), NVL(z.SNO3, C_NULL_VAL), NVL(z.SNO4, C_NULL_VAL),
		z.BP_CD,
		z.ASST_TYP,
		z.QTY,
		z.FIRST_GR_DT, z.VLD_DT, z.LMT_DT,
		(-- 滞留基準年月
			SELECT
				NVL(MAX(W.NON_MOV_GI_YM), MIN(W.NON_MOV_GR_YM))
			FROM
				MGT_NON_MOV_STK W
			WHERE 0=0
			AND W.ITM_CD = z.ITM_CD
			AND W.ITM_SUB1 = z.ITM_SUB1
			AND W.ITM_SUB2 = z.ITM_SUB2
			AND W.ITM_SUB3 = z.ITM_SUB3
			AND (z.LOT_NO IS NULL OR G_LOT_NON_MOV_FLG = C_OFF OR W.LOT_NO = z.LOT_NO)
			AND (z.SUBLOT_NO IS NULL OR G_SUBLOT_NON_MOV_FLG = C_OFF OR W.SUBLOT_NO = z.SUBLOT_NO)
			AND (z.SNO1 IS NULL OR G_SNO1_NON_MOV_FLG = C_OFF OR W.SNO1 = z.SNO1)
			AND (z.SNO2 IS NULL OR G_SNO2_NON_MOV_FLG = C_OFF OR W.SNO2 = z.SNO2)
			AND (z.SNO3 IS NULL OR G_SNO3_NON_MOV_FLG = C_OFF OR W.SNO3 = z.SNO3)
			AND (z.SNO4 IS NULL OR G_SNO4_NON_MOV_FLG = C_OFF OR W.SNO4 = z.SNO4)
			AND (G_WG_NON_MOV_FLG = C_OFF OR W.WG_CD = z.WG_CD)
		),
		NULL, NULL, NULL, NULL,
		C_ON
	FROM (
		SELECT
			x.WG_CD,
			x.AC_YM,
			x.MNG_DPT_CD,
			x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
			x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
			x.BP_CD,
			x.ASST_TYP,
			SUM(x.QTY)			QTY,
			MIN(x.FIRST_GR_DT)	FIRST_GR_DT,
			MIN(x.VLD_DT)		VLD_DT,
			MIN(x.LMT_DT)		LMT_DT
		FROM (
			SELECT
				m1.WG_CD,
				t.AC_YM,
				MGPA_COST_IF.F_GET_LOC_TO_DPT(t.LOC_CD)	MNG_DPT_CD,
				t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
				CASE WHEN L_LOT_USE_TYP = C_PS_USE2 AND t.ASST_TYP IN (C_ASST2, C_ASST3)
					OR L_LOT_USE_TYP = C_PS_USE3 AND t.ASST_TYP = C_ASST1
					OR L_LOT_USE_TYP = C_PS_USE1 THEN
						CASE WHEN NVL(m4.LOT_ACT_TYP, C_ACT1) = C_ACT2 THEN t.LOT_NO
						ELSE NULL END
				ELSE NULL END LOT_NO,
				CASE WHEN L_SUBLOT_USE_TYP = C_PS_USE2 AND t.ASST_TYP IN (C_ASST2, C_ASST3)
					OR L_SUBLOT_USE_TYP = C_PS_USE3 AND t.ASST_TYP = C_ASST1
					OR L_SUBLOT_USE_TYP = C_PS_USE1 THEN
						CASE WHEN NVL(m4.SUBLOT_ACT_TYP, C_ACT1) = C_ACT2 THEN t.SUBLOT_NO
						ELSE NULL END
				ELSE NULL END SUBLOT_NO,
				CASE WHEN L_SNO1_USE_TYP = C_PS_USE2 AND t.ASST_TYP IN (C_ASST2, C_ASST3)
					OR L_SNO1_USE_TYP = C_PS_USE3 AND t.ASST_TYP = C_ASST1
					OR L_SNO1_USE_TYP = C_PS_USE1 THEN
						CASE WHEN NVL(m4.SNO1_ACT_TYP, C_ACT1) = C_ACT2 THEN t.SNO1
						ELSE NULL END
				ELSE NULL END	SNO1,
				CASE WHEN L_SNO2_USE_TYP = C_PS_USE2 AND t.ASST_TYP IN (C_ASST2, C_ASST3)
					OR L_SNO2_USE_TYP = C_PS_USE3 AND t.ASST_TYP = C_ASST1
					OR L_SNO2_USE_TYP = C_PS_USE1 THEN
						CASE WHEN NVL(m4.SNO2_ACT_TYP, C_ACT1) = C_ACT2 THEN t.SNO2
						ELSE NULL END
				ELSE NULL END SNO2,
				CASE WHEN L_SNO3_USE_TYP = C_PS_USE2 AND t.ASST_TYP IN (C_ASST2, C_ASST3)
					OR L_SNO3_USE_TYP = C_PS_USE3 AND t.ASST_TYP = C_ASST1
					OR L_SNO3_USE_TYP = C_PS_USE1 THEN
						CASE WHEN NVL(m4.SNO3_ACT_TYP, C_ACT1) = C_ACT2 THEN t.SNO3
						ELSE NULL END
				ELSE NULL END SNO3,
				CASE WHEN L_SNO4_USE_TYP = C_PS_USE2 AND t.ASST_TYP IN (C_ASST2, C_ASST3)
					OR L_SNO4_USE_TYP = C_PS_USE3 AND t.ASST_TYP = C_ASST1
					OR L_SNO4_USE_TYP = C_PS_USE1 THEN
						CASE WHEN NVL(m4.SNO4_ACT_TYP, C_ACT1) = C_ACT2 THEN t.SNO4
						ELSE NULL END
				ELSE NULL END SNO4,
				CASE t.ASST_TYP
				WHEN C_ASST1 THEN
					DECODE(L_STK_BP_FLG, C_OFF, NULL, DECODE(t.STK_ARRV_BP_CD, C_NULL_VAL, NULL,
						CASE
						WHEN m2.DLV_FLG = C_ON AND m2.TDLV_FLG = C_OFF THEN t.STK_ARRV_BP_CD
						WHEN m2.DLV_FLG = C_ON AND m2.TDLV_FLG = C_ON THEN
							CASE WHEN t.FIX_NO_TYP IN (C_FIX_NO_DLV_SLIP_NO, C_FIX_NO_IV_NO) THEN t.STK_ARRV_BP_CD
							ELSE NULL END
						ELSE NULL END))
				WHEN C_ASST2 THEN
					DECODE(t.STK_ARRV_BP_CD, C_NULL_VAL, NULL,
						CASE
						WHEN m2.DLV_FLG = C_ON AND m2.TDLV_FLG = C_OFF THEN t.STK_ARRV_BP_CD
						WHEN m2.DLV_FLG = C_ON AND m2.TDLV_FLG = C_ON THEN
							CASE WHEN t.FIX_NO_TYP IN (C_FIX_NO_DLV_SLIP_NO, C_FIX_NO_IV_NO) THEN t.STK_ARRV_BP_CD
							ELSE NULL END
						ELSE t.STK_ARRV_BP_CD END)
				ELSE
					DECODE(t.STK_ARRV_BP_CD, C_NULL_VAL, NULL, t.STK_ARRV_BP_CD)
				END	BP_CD,
				DECODE(L_ASST_FLG, C_OFF, t.ASST_TYP, DECODE(t.ASST_TYP, C_ASST3, C_ASST3, C_ASST2))	ASST_TYP,
				t.BASE_UNIT_QTY	QTY,
				t.SUB_CHAR1, t.SUB_CHAR2, t.SUB_CHAR3,
				t2.FIRST_GR_DT, t2.VLD_DT, t2.LMT_DT
			FROM	MGVT_MST_MLY_STK_DTL t, MGVT_MSVT_LOT_LIST t2,
					MAM_LOC m1, MAM_BP m2, MAM_ITM_SRCH m3, MAM_CALC_PTN m4
			WHERE	0=0
			AND	t.AC_YM = I_YM
			AND	t.IO_ACT_TYP = C_END_STK
			AND	t.BASE_UNIT_QTY <> 0
			AND	t.ITM_CD = t2.ITM_CD(+)
			AND	t.ITM_SUB1 = t2.ITM_SUB1(+)
			AND	t.ITM_SUB2 = t2.ITM_SUB2(+)
			AND	t.ITM_SUB3 = t2.ITM_SUB3(+)
			AND	t.LOT_NO = t2.LOT_NO(+)
			AND	t.SUBLOT_NO = t2.SUBLOT_NO(+)
			AND	NOT EXISTS (
				SELECT	'X'
				FROM	MGVT_MST_PURC_ACT_IO w1, MGVT_MST_PURC_ACT_D w2
				WHERE	0=0
				AND	t.FIX_NO_TYP = C_FIX_NO_PURC_ACT_IO
				AND	w1.PURC_ACT_IO_NO = t.FIX_NO
				AND	w1.PURC_ACT_D_NO = w2.PURC_ACT_D_NO(+)
				AND	w1.PURC_ACT_D_SEQ = w2.PURC_ACT_D_SEQ(+)
				AND	(L_CO_PARM.NON_TRANSIT_FLG = C_ON OR w2.MFG_INST_NO IS NOT NULL)
				)
			AND	t.LOC_CD = m1.LOC_CD
			AND	m1.DEL_FLG = C_OFF
			AND t.STK_ARRV_BP_CD = m2.BP_CD(+)
			AND	t.ITM_CD = m3.ITM_CD
			AND	t.ITM_SUB1 = m3.ITM_SUB1
			AND	t.ITM_SUB2 = m3.ITM_SUB2
			AND	t.ITM_SUB3 = m3.ITM_SUB3
			AND	m3.DEL_FLG = C_OFF
			AND	m3.RELEASE_FLG = C_ON
			AND	m3.ASSET_MNG_TYP = C_ASST_MNG1
			AND	m3.CALC_PTN_CD = m4.CALC_PTN_CD(+)
			AND (
				m1.SPPL_CD IS NOT NULL AND t.STK_ID_TYP IN (C_STK_ID1, C_STK_ID8)
				OR
				m1.SPPL_CD IS NULL AND t.ASST_TYP <> C_ASST3
				)
			AND	(
				L_NON_PROD_FLG = C_OFF AND t.ASST_TYP IN (C_ASST2, C_ASST3)
				OR
				L_NON_SLS_FLG = C_OFF AND t.ASST_TYP = C_ASST1
				)
			AND	(
				L_ITM_OUT_CNT = 0
				OR
				NOT EXISTS (
					SELECT	'X'
					FROM	MAM_COST_ITM_OUT m
					WHERE	0=0
					AND	m.ITM_CD = t.ITM_CD
					AND	m.ITM_SUB1 = t.ITM_SUB1
					AND	m.ITM_SUB2 = t.ITM_SUB2
					AND	m.ITM_SUB3 = t.ITM_SUB3
					AND	m.YM <= I_YM
					)
				)
			) x
		WHERE	0=0
		GROUP BY x.WG_CD, x.AC_YM, x.MNG_DPT_CD, x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
			x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4, x.BP_CD, x.ASST_TYP
			--, x.SUB_CHAR1, x.SUB_CHAR2, x.SUB_CHAR3
		) z
	;
	L_STK_CNT := SQL%ROWCOUNT ;

	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0025', L_REC_CNT) ;
	FCPA_BATCH_LOG.P_PROC_LOG('MGBBD0035', L_STK_CNT) ;

	<<SKIP_STK>>
		NULL ;

	COMMIT ;

	IF L_RSLT = C_ERR THEN
		COMMIT ; --正常データは取込済みにするため
		L_MSG := FCPA_ERR.MSG_BINDER('MGPA_INS_SCM2MGTIF.P_IF') ;
		FCPA_ERR.RAISE_APP_ERR('MGBXD0037', L_MSG) ;
	END IF ;

	--処理が終了しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0002', 'MGPA_INS_SCM2MGTIF.P_IF') ;

EXCEPTION
WHEN LOCK_ERROR THEN
	FCPA_ERR.RAISE_APP_ERR('MGBXD0029') ;
END P_IF ;

END MGPA_INS_SCM2MGTIF ;
/
